window.__LEX={"G4200":"<h1>porismos</h1>\n<p>Strong n° 4200 <i>Prononciation [por-is-mos']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>acquisition, gain</li>\n<li>source de gain</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πορισμός, οῦ (ὁ) :<br>      1</b> action de se procurer, POL. <i>3, 112, 2 ; particul</i>. action de se procurer de l’argent, PLUT. <i>M. 524</i> d, <i>etc. ;</i><br><b>      2</b> moyen pour se procurer, expédient, PLUT. <i>Cato ma. 25 ; particul</i>. moyen de gagner, NT. <i>1Tim. 6, 5</i>.<br><span><b>Étym</b>. πορίζω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πορισμος - πορισμός</font>\n<br><br>vient d'un dérivé de poros (un chemin, c.à.d. le moyen)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (2)</li>\n</ul>\n</td></tr>\n</table>","G4201":"<h1>Porkios</h1>\n<p>Strong n° 4201 <i>Prononciation [por'-kee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Porcius (Festus) = « de cochon, bestial »\n<ol><li>le successeur de Félix comme procurateur de Judée</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πόρκιος, </b><b>ου (ὁ)</b> = <i>lat</i>. Porcius, <i>n. d’h. rom</i>. PLUT. <i>Popl. 11</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πορκιος - Πόρκιος</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4202":"<h1>porneia</h1>\n<p>Strong n° 4202 <i>Prononciation [por-ni'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>relation sexuelle illicite\n<ol type=\"a\">\n<li>adultère, fornication, homosexualité, mœurs d'une lesbienne, relation avec des animaux etc.</li>\n<li>relation sexuelle avec un proche parent</li>\n<li>relation sexuelle avec un ou une divorcée (<a class=\"ref\" data-r=\"MRK10.11-12\">Marc 10.11, 12</a>)</li>\n</ol>\n</li>\n<li>métaph. le culte des idoles\n<ol type=\"a\">\n<li>de la souillure de l'idolâtrie, provenant de la consommation de sacrifices offerts aux idoles</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πορνεία, </b><b>ας (ἡ) :<br>      1</b> prostitution, DÉM. <i>403, 26, etc. ;</i><br><b>      2</b> <i>p. ext</i>. toute action déshonnête (adultère, <i>etc.) ; particul</i>. relations avec les Gentils, idolâtrie, SPT. <i>Num. 14, 33, etc</i>.<br><span><b>Étym</b>. πορνεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πορνεια - πορνεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n25 fois dans 24 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (3)</li>\n<li>1 Corinthiens (5)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G4203":"<h1>porneuo</h1>\n<p>Strong n° 4203 <i>Prononciation [porn-yoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prostituer son corps à la convoitise d'un autre</li>\n<li>se livrer à une relation sexuelle illicite\n<ol type=\"a\">\n<li>commettre la fornication</li>\n</ol>\n</li>\n<li>métaph. être adonné à l'idolâtrie, adorer les idoles\n<ol type=\"a\">\n<li>permettre à un autre de nous conduire à l'idolâtrie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πορνεύω</b>, vivre dans la prostitution, faire métier de prostituée <i>ou</i> de prostitué, LUC. <i>Alex. 5 ;</i> PHALAR. <i>Ep. 8 ; fig</i>. avoir des relations avec les Gentils, pratiquer l’idolâtrie, SPT. <i>1Par. 5, 25 ; Ps. 72, 27, etc. ;</i><br><b><i>Moy.</i></b> <i>m. sign., en parl. de femmes,</i> HDT. <i>1, 93 ; p. opp. à</i> ἑταιρεῖν, ESCHN. <i>8, 8 et 16 ; en parl. d’hommes,</i> ESCHN. <i>22, 12, etc</i>.<br><span><b>Étym</b>. πόρνη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προνευω - πορνεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\t\n11 fois dans 7 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (4)</li>\n<li>Apocalypse (7)</li>\n</ul>\n</td></tr>\n</table>","G4204":"<h1>porne</h1>\n<p>Strong n° 4204 <i>Prononciation [por'-nay]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une femme qui vend son corps pour un usage sexuel\n<ol type=\"a\">\n<li>une prostituée, une fille de joie, qui se livre à la souillure pour l'appât du gain</li>\n<li>toute femme satisfaite d'une relation sexuelle illicite, que ce soit pour le gain ou par luxure</li>\n</ol>\n</li>\n<li>métaph. une idolâtre\n<ol type=\"a\">\n<li>de « Babylone » c.à.d. Rome, le siège principal de l'idolâtrie</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πόρνη, </b><b>ης (ἡ)</b> femme de mauvaise vie, ARCHIL. <i>142 (116) ;</i> AR. <i>Ach. 527</i>.<br><span><b>Étym</b>. πέρνημι, vendre, <i>parce que les prostituées étaient en gén. primitiv. des esclaves</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προνη - πόρνη</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>Apocalypse (5)</li>\n</ul>\n</td></tr>\n</table>","G4205":"<h1>pornos</h1>\n<p>Strong n° 4205 <i>Prononciation [por'-nos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un homme qui prostitue son corps et le loue à la convoitise d'un autre</li>\n<li>un prostitué</li>\n<li>homme qui se complaît dans la relation sexuelle illicite, un qui fornique</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πόρνος, </b><b>ου (ὁ)</b> qui se prostitue, débauché, AR. <i>Pl. 155 ;</i> XÉN. <i>Mem. 1, 6, 13, etc</i>.<br><span><b>Étym</b>. πέρνημι ; <i>cf</i>. πόρνη.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πορνος - πόρνος</font>\n<br><br>Voir définition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n10 fois dans 10 versets de 5 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (4)</li>\n<li>Ephésiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (2)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4206":"<h1>porrho</h1>\n<p>Strong n° 4206 <i>Prononciation [por'-rho]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>loin, à distance, un long chemin de</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πόρρω</b>, <i>adv. :</i><br><b>   I</b> en avant :<br><b>      1</b> (<i>avec idée de lieu</i>) πόρρω ὑποτιθέναι τὰ ὀπίσθια σκέλη ὑπὸ τὰ ἐμπρόσθια, XÉN. <i>Eq. 11, 2,</i> poser les jambes de derrière en avant sous celles de devant ; τὸ πόρρω, ATT. en avant ; <i>avec un gén</i>. προϐαίνειν πόρρω τῆς μοχθηρίας, XÉN. <i>Ap. 30,</i> aller bien avant <i>ou</i> s’enfoncer dans la voie du vice ; πόρρω σοφίας ἐλαύνειν, PLAT. <i>Euthyphr. 4</i> b, <i>etc. ;</i> ἥκειν, PLAT. <i>Euthyd. 294</i> d, avancer dans la voie de la sagesse, être parvenu à un certain point dans la voie de la sagesse ;<br><b>      2</b> (<i>avec idée de temps</i>) πόρρω τῆς ἡμέρας οὔσης, ESCHN. <i>70, 41,</i> le jour étant fort avancé ; <i>avec le gén. :</i> ἐκάθευδον μέχρι πόρρω τῆς ἡμέρας, XÉN. <i>Hell. 7, 2, 19,</i> ils dormirent jusqu’à une heure avancée du jour ; πόρρω τῶν νυκτῶν, PLAT. <i>Prot. 310</i> c, <i>Conv. 217</i> d, fort avant dans la nuit ; πόρρω τῆς ἡλικίας, PLAT. <i>Gorg. 484</i> c ; PLUT. <i>Dem. 2,</i> dans un âge avancé ; τὸ <i>ou</i> τὰ πόρρω, ATT. ce qui est en avant, l’avenir ;<br><b>   II</b> <i>p. suite,</i> loin, très loin :<br><b>      1</b> (<i>avec idée de lieu</i>) XÉN. <i>Mem. 1, 2, 54 ; p. opp. à</i> ἐγγύς, PLAT. <i>Prot. 356</i> e ; <i>avec le gén. :</i> οὐ πόρρω τῶν βωμῶν, PLAT. <i>Leg. 800</i> c, non loin des autels ; π. τῶν πυλῶν, PLUT. <i>Cam. 4,</i> loin des portes ; <i>avec une prép. :</i> π. ἀπό <i>et le gén</i>. XÉN. <i>Mem. 1, 4, 6, etc</i>. loin de, <i>etc. ; fig</i>. π. ἀποτείνειν τὸν λόγον, PLAT. <i>Gorg. 458</i> b, étendre <i>ou</i> prolonger trop longtemps l’entretien ; τινὰ <i>ou</i> τὶ π. ποιεῖν, ANAX. (ATH. <i>558</i> c) laisser loin derrière soi qqn <i>ou</i> qqe ch. ;<br><b>      2</b> (<i>avec idée de temps</i>) tard, très tard : πόρρω πεπαίνεται, TH. <i>C.P. 1, 11,</i> il mûrit tard.<br><span>•<i> Cp</i>. πορρωτέρω, XÉN. <i>Hell. 7, 5, 13 ;</i> PLAT. <i>Eryx. 397</i> c, <i>etc. ;</i> PLUT. <i>Cam. 4 ; ou</i> πορρώτερον, PLAT. <i>Leg. 348 ;</i> <i>• Sup</i>. πορρωτάτω, XÉN. <i>Mem. 1, 2, 54 ;</i> PLAT. <i>Tim. 70</i> e ; ISOCR. <i>34</i> c, <i>etc. Ces cp. et sup. se construisent comme le positif, abs</i>. XÉN. <i>Hell. 7, 5, 13, ou avec le gén</i>. πορρωτέρω τοῦ δέοντος, PLAT. <i>Rsp. 562</i> d, bien au delà de ce qu’il faut, beaucoup plus qu’il ne faut ; πορρωτάτω τῶν ὑποψιῶν, ISOCR. <i>34</i> c, très loin de tout soupçon.<br><span><b>Étym</b>. πόρσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πορρω - πόρρω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4207":"<h1>porrhothen</h1>\n<p>Strong n° 4207 <i>Prononciation [por'-rho-then]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>vient de loin, de loin, éloigné</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πόρρωθεν</b>, <i>adv. :</i><br><b>      1</b> de loin, ATT. ;<br><b>      2</b> depuis longtemps, ATT.<br><span><b>Étym</b>. πόρρω, -θεν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πορρωθεν - πόρρωθεν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4208":"<h1>porrhotero</h1>\n<p>Strong n° 4208 <i>Prononciation [por-rho-ter'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>plus loin</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πορρώτερον</b>, <i>cp. de</i> .\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πορρωτηρω - πορρώτερον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4209":"<h1>porphura</h1>\n<p>Strong n° 4209 <i>Prononciation [por-foo'-rah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>coquillage, mollusque (murex) donnant un colorant pourpre violet ou cramoisi</li>\n<li>un tissu coloré de teinture pourpre, (colorant très cher), un vêtement fait de tissu pourpre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πορφύρα, </b><b>ας (ἡ)</b> <span>[ῠ]</span><br><b>      1</b> le pourpre, <i>coquillage d’où l’on tire la pourpre,</i> ESCHL. <i>Ag. 959 ;</i> SOPH. <i>fr. 438 ;</i> ARSTT. <i>H.A. 4, 4, 2, etc. ;</i><br><b>      2</b> <i>p. suite,</i> la pourpre (<i>dans Hom</i>. φοῖνιξ), HDT. <i>3, 22 ;</i> PLAT. <i>Leg. 847</i> c ; ISOCR. <i>240</i> d, <i>etc. ; p. ext</i>. étoffe, vêtement <i>ou</i> tapis teints en pourpre, <i>au plur</i>. ESCHL. <i>Ag. 957 ; au sg. collect</i>. ARSTT. LUC. <i>Nic. 4, 2, 20 ;</i> πορφύρα πλατεῖα, POL. <i>10, 26, 1 ;</i> DS. <i>20, 34 ;</i> D. PHAL. <i>§ 108 ; ou abs</i>. πορφύρα, LUC. <i>H. conscr. 15, etc</i>. le laticlave (latus clavus) <i>ou</i> bande de pourpre sur la toge des sénateurs romains.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πορφυρή, HDT. <i>l. c</i>.<br><span><b>Étym</b>. φύρω, <i>avec redoubl. ; v</i>. πορφύρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πορφυρα - πορφύρα</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Apocalypse (2)</li>\n</ul>\n</td></tr>\n</table>","G4210":"<h1>porphurous</h1>\n<p>Strong n° 4210 <i>Prononciation [por-foo-rooce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>pourpre, couleur pourpre, fait de tissu teint en pourpre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πορφυροῦς, </b><b>ᾶ, οῦν</b>, <i>v</i>. πορφύρεος.<br>\n<b>πορφύρεος-οῦς, έα-ᾶ, έον-οῦν</b> <span>[ῠ]</span><br><b>   I</b> <i>dans Hom</i>. qui se soulève en bouillonnant, <i>p. suite,</i> qui se colore d’une teinte sombre, <i>en parl. des flots de la mer,</i> IL. <i>1, 482 ;</i> OD. <i>2, 428 ; 13, 85 ; ou d’un fleuve,</i> IL. <i>21, 326 ;</i> OD. <i>11, 242 ;</i> π. ἅλς, IL. <i>16, 391,</i> la mer soulevée (par la tempête <i>ou</i> par les coups de rame) et qui se colore d’une teinte foncée ; <i>p. ext</i>. de couleur sombre, sombre, <i>en parl. d’un nuage,</i> IL. <i>17, 551 ; du sang,</i> IL. <i>17, 361 (cf</i>. αἷμα κελαινόν) ; <i>de la mort dans un combat,</i> IL. <i>5, 83 ; 16, 334 ; 20, 477 (cf</i>. θάνατος μέλας), <i>d’où subst</i>. ὁ πορφύρεος, ANTH. <i>11, 13,</i> celle qui est sombre, la mort ; <i>de vêtements, d’étoffes,</i> IL. <i>7, 221, etc. ;</i> OD. <i>4, 115, etc. ; de tapis,</i> IL. <i>9, 200 ;</i> OD. <i>20, 151, etc. ;</i><br><b>   II</b> <i>après Homère et par confusion du sens primit. avec celui de</i> πορφύρα :<br><b>      1</b> de couleur pourpre, d’un rouge foncé, PD. <i>P. 4, 203, 326 ;</i> HDT. <i>1, 50, etc. ; d’où</i> d’un rouge rosé, ANACR. <i>2, 3 ;</i> SIM. <i>fr. 72, etc. ;</i> τὰ πορφυρᾶ, EL. <i>N.A. 17, 33,</i> étoffes de pourpre ; <i>en parl. de pers</i>. vêtu de pourpre, LUC. <i>Tim. 20 ;</i><br><b>      2</b> <i>p. ext</i>. éclatant, brillant, <i>en parl. de l’arc-en-ciel,</i> IL. <i>17, 547 ; de serpents aux reflets brillants,</i> IL. <i>11, 26, etc</i>.<br><span><b>Étym</b>. φύρω <i>avec redoubl., le mot étant homérique et</i> πορφύρα, <i>étant inconnu à Homère ; v</i>. πορφύρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προφυρους - πορφυροῦς</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jean (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4211":"<h1>porphuropolis</h1>\n<p>Strong n° 4211 <i>Prononciation [por-foo-rop'-o-lis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une marchande de pourpre, ou d'étoffe teinte en pourpre</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πορφυρό·πωλις, ιδος (ἡ)</b> <span>[ῠῐδ]</span> marchande d’étoffes de pourpre, NT. <i>Ap. 16, 14</i>.<br><span><b>Étym</b>. π. πωλέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πορφυροπωλις - πορφυρόπωλις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4212":"<h1>posakis</h1>\n<p>Strong n° 4212 <i>Prononciation [pos-ak'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>combien souvent</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ποσάκις</b> <span>[ᾰῐ]</span> <i>adv. interr</i>. combien de fois ? PLAT. <i>Ep. 353</i> d ; οἱ ποσάκις πόσοι ἀριθμοί, ARSTT. <i>Metaph. 4, 14, 2,</i> les nombres carrés ; οἱ ποσάκις ποσάκις πόσοι, ARSTT. <i>Metaph. 4, 14, 2,</i> les nombre cubes.<br><span><b>Étym</b>. πόσος, -άκις.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποσακις - ποσάκις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4213":"<h1>posis</h1>\n<p>Strong n° 4213 <i>Prononciation [pos'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une boisson, un breuvage</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>πόσις, </b><b>εως (ἡ) :<br>      1</b> action de boire, <i>d’où</i> boisson, IL. <i>1, 469, etc. ;</i> OD. <i>10, 176, etc. ;</i> HDT. <i>1, 172, etc. ;</i> THC. <i>7, 73, etc. ;</i><br><b>      2</b> gorgée d’une boisson, ESCHL. <i>Ch. 578 ;</i> ANT. <i>113, 30 ; au plur</i>. PLAT. <i>Leg. 641</i> a.<br><span><b><span class=\"arrow\"></span></b> <i>Gén. ion</i>. πόσιος, IL. <i>1, 469, etc. ;</i> THCR. <i>Idyl. 14, 29 ; dat. ion</i>. πόσι, HDT. <i>5, 19</i>.<br><span><b>Étym</b>. πίνω.</span></span><br><br>\n➁ <b>πόσις, </b><b>ιος (ὁ) :<br>      1</b> fiancé, ARSTT. <i>Pol. 1, 3 ;</i><br><b>      2</b> époux, <i>d’ord</i>. époux légitime, IL. <i>5, 71, etc. ;</i> ESCHL. <i>Ag. 1108 ;</i> SOPH. <i>Tr. 550 ;</i> EUR. <i>Alc. 323, etc. ; rare en prose,</i> ARSTT. <i>Pol. 7, 16, 18, etc. ; qqf</i>. amant : κρυπτὸς π. EUR. <i>Or. 561,</i> époux secret.<br><span><b><span class=\"arrow\"></span></b> <i>Voc</i>. πόσι, EUR. <i>Alc. 323, etc. ;</i> AR. <i>Th. 913 ; ou</i> πόσις, EUR. <i>Hel. 1399 ; gén</i>. πόσεως, <i>sans ex. ;</i> πόσιος, EUR. <i>Med. 906 dout. ; dat. épq</i>. πόσεϊ, IL. <i>5, 71 ; d’où</i> πόσει, ATT. ; <i>acc</i>. πόσιν, ESCHL. <i>Ag. 1108, etc. ; acc. pl. épq</i>. πόσιας, IL. <i>6, 240 ; nomin. sg. poét</i>. πόσσις, ANTH. <i>6, 323</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *poti-, maître <i>de maison,</i> époux ; <i>cf</i>. πότνια, δεσπότης, Ποσειδῶν, <i>lat</i>. potis, potēns <i>et</i> hospes.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποσις - πόσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Jean (1)</li>\n<li>Romains (1)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4214":"<h1>posos</h1>\n<p>Strong n° 4214 <i>Prononciation [pos'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>combien est grand</li>\n<li>combien de choses</li>\n<li>combien de temps</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ποσός, </b><b>ή, όν</b>, qui est de quelque grandeur, en quelque quantité, PLAT. <i>Soph. 245</i> d, <i>etc. ;</i> τὸ ποσόν, PLAT. <i>Phil. 24</i> d ; ARSTT. <i>Categ. 6, etc</i>. quantité ; κατὰ ποσόν, jusqu’à un certain point, ARSTT. <i>Nic. 8, 7, 3 ;</i> ἐπὶ ποσόν, pour un certain temps, POL. <i>2, 34, 15, etc</i>.<br><span><b>Étym</b>. *πός.</span><br><br>\n➁ <b>πόσος, </b><b>η, ον</b>, combien grand ? combien nombreux ? :<br><b>      1</b> <i>en parl. de l’espace,</i> combien grand ? combien long ? combien loin ? XÉN. <i>Cyr. 6, 3, 10, etc. ;</i> ARSTT. <i>Probl. 5, 25 ;</i><br><b>      2</b> <i>en parl. du temps,</i> combien long ? SOPH. <i>O.R. 558 ;</i> PLAT. <i>Rsp. 540</i> a, <i>etc. ;</i><br><b>      3</b> <i>en parl. du nombre,</i> combien nombreux ? <i>au sg. collectif,</i> ESCHL. <i>Pers. 334 ;</i> XÉN. <i>Cyr. 3, 1, 31 ;</i> PLAT. <i>Theæt. 198</i> c, <i>au plur</i>. HDT. <i>7, 234 ;</i> XÉN. <i>Mem. 4, 4, 7, etc. ;</i><br><b>      4</b> <i>en parl. du prix, de la valeur,</i> AR. <i>fr. 1262 ;</i> πόσου (<i>s.-e</i>. ἀργυρίου), AR. <i>Ach. 819, etc. ;</i> XÉN. <i>Cyr. 3, 1, 36 ;</i> PLAT. <i>Ap. 20</i> b, <i>etc. ; ou</i> ἐπὶ πόσῳ (<i>s.-e</i>. ἀργυρίῳ) ; XÉN. <i>Cyr. 3, 1, 43 ;</i> PLAT. <i>Ap. 41</i> a ; <i>ou</i> ἐκ πόσου ; DÉM. <i>1216, 18,</i> pour combien d’argent ? à quel prix ? ;<br><b>      5</b> <i>fig. en parl. de choses abstraites,</i> combien grand ? combien fort ? PLAT. <i>Conv. 216</i> d ; AR. <i>Ran. 55 ; en ces divers sens, joint à</i> τις, <i>pour marquer l’indéterminat. :</i> π. τις ; XÉN. <i>Cyr. 4, 6, 10 ;</i> SOPH. <i>O.R. 558, etc</i>. de quelle grandeur, de quelle longueur, peut bien être ? πόσ' ἄττα ; ARSTT. <i>Nic. 5, 5, 10,</i> combien peut-il y avoir, <i>etc. ? neutre adv</i>. πόσον ; AR. <i>Eccl. 399 ;</i> πόσα ; XÉN. <i>Mem. 2, 2, 8,</i> en quelle quantité ?.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κόσος, HDT. <i>l. c</i>.<br><span><b>Étym</b>. *πός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποσος - πόσος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Pronom</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n27 fois dans 27 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (6)</li>\n<li>Luc (6)</li>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4215":"<h1>potamos</h1>\n<p>Strong n° 4215 <i>Prononciation [pot-am-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un courant, une rivière, un fleuve</li>\n<li>un torrent</li>\n<li>les flots</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ποταμός, </b><b>οῦ (ὁ)</b> <span>[ᾰ]</span><br><b>      1</b> fleuve, rivière, HOM. ATT. <i>etc. ; prov</i>. <span>ἄνω ποταμῶν</span>, ESCHL. <i>fr. 378 ; cf</i>. EUR. <i>Med. 410, etc</i>. en remontant le courant, <i>en parl. d’événements extraordinaires ; en gén</i>. tout courant liquide, <i>particul</i>. courant de lave, PD. <i>P. 1, 42 ;</i> ESCHL. <i>Pr. 368, etc. ; en parl. des fleuves de feu des enfers,</i> PLAT. <i>Phæd. 111</i> d ;<br><b>      2</b> rivière artificielle, canal, ARR. <i>An. 7, 21, 1 ;</i> STR. <i>740, etc. ;</i><br><b>      3</b> <i>p. anal. nom d’une constellation, auj</i>. l’Éridan, <i>constellation de l’hémisphère sud,</i> ARAT. <i>358, etc</i>.<br><span><b>Étym</b>. <i>incert. ; cf. p.-ê</i>. πέτομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποταμος - ποταμός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n16 fois dans 16 versets de 7 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>Marc (1)</li>\n<li>Luc (2)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Apocalypse (8)</li>\n</ul>\n</td></tr>\n</table>","G4216":"<h1>potamophoretos</h1>\n<p>Strong n° 4216 <i>Prononciation [pot-am-of-or'-ay-tos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>emporté par un courant (c.à.d. entraîné, noyé dans les eaux)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ποταμο·φόρητος, ος, ον</b> <span>[ᾰ]</span> emporté par le fleuve, NT. <i>Apoc. 12, 15</i>.<br><span><b>Étym</b>. π. φορέω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποταμοφορητος - ποταμοφόρητος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4217":"<h1>potapos</h1>\n<p>Strong n° 4217 <i>Prononciation [pot-ap-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>de quelle sorte ou qualité (de quelle manière)\n<ol type=\"a\">\n<li>de personnes</li>\n<li>de choses</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ποταπός, </b><b>ή, όν</b> <span>[ᾰ]</span> <i>c</i>. ποδαπός, NT. <i>Matth. 8, 27 ;</i> SEXT. <i>479, 13 Bkk</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποταπος - ποταπός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4218":"<h1>pote</h1>\n<p>Strong n° 4218 <i>Prononciation [pot-eh']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>autrefois c.à.d. auparavant, jadis, il y a quelque temps ...</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ποτέ</b>, <i>adv. indéf. enclitique,</i> quelquefois, une fois par hasard, un jour :<br><b>   I</b> (<i>avec idée de temps indéterminé</i>) τότε ποτέ, PLAT. <i>Criti. 115</i> b, alors en un temps quelconque ; ἦ σοι γὰρ Αἴας πολέμιος προὔστη ποτέ ; SOPH. <i>Aj. 1133,</i> le belliqueux Ajax s’opposa-t-il jamais à toi ? <i>càd</i>. fut-il jamais ton ennemi ? <i>cf</i>. SOPH. <i>Aj. 1106, etc. ;</i> DÉM. <i>53, 12, etc. ; en ce sens, après les conj. dubitatives</i> εἰ, ἐάν, εἴπερ, <i>etc</i>. ATT. (<i>v. ces mots) ; joint au pron. indéf</i>. τις, ATT. ; <i>au pron. relat</i>. ὅστις : ὅστις ποτέ, qui à un moment quelconque, ATT. ; <i>particul. avec les particules</i> δή <i>et</i> οὖν : ὅστις δή ποτε, ὅστις δή ποτ' οὖν, ATT. <i>m. sign. etc. ; avec une nég. :</i> οὔ ποτε, μή ποτε, ATT. ; <i>d’où en un mot :</i> οὔποτε, μήποτε, ATT. non en un temps quelconque, jamais ; <i>ou séparés par d’autres mots :</i> οὐκ… ποτε. IL. <i>19, 271 ;</i> μὴ… ποτε, SOPH. <i>Ant. 648, 762 ; de même</i> οὐδέποτε, μηδέποτε, οὐδεπώποτε, μηδεπώποτε, <i>etc. (v. ces mots) ; rar. avant la négation,</i> SOPH. <i>Ant. 750 ; en relation avec un autre</i> ποτέ <i>ou un mot analogue :</i> ποτὲ μὲν… ποτὲ δέ, XÉN. <i>Mem. 4, 2, 32 ;</i> PLAT. <i>Theæt. 170</i> c, <i>etc</i>. tantôt… tantôt ; ποτὲ μὲν… αὖθις δέ, PLAT. <i>Rsp. 560</i> a ; ποτὲ μὲν… ἐνίοτε δέ, PLAT. <i>Phæd. 59</i> a ; ποτὲ… τότε δέ, PLAT. <i>Theæt. 192</i> d ; ποτὲ μὲν… τότε δέ, POL. <i>4, 38, 6 ;</i> ποτὲ μὲν… νῦν δέ, LUC. <i>D. mort. 11, 1, m. sign. ; ou, avec</i> ποτὲ δέ <i>dans le second membre non précédé de</i> ποτὲ μέν, TH. <i>Char. 9 ;</i> POL. <i>6, 15, 8, m. sign. ; qqf. pour marquer l’attente au sens de</i> enfin, IL. <i>1, 205 ;</i> OD. <i>2, 76 ;</i> HDT. <i>1, 116, etc. ; particul. avec un impér</i>. SOPH. <i>Ph. 816, 1041, etc. ; ou après un mot interrog. :</i> τίς ποτε ; ESCHL. <i>Eum. 408, etc</i>. qui enfin ? τί ποτε ; PLAT. <i>Theæt. 187</i> d, <i>etc</i>. quoi enfin ? <i>avec</i> ἀεί : ἀεί ποτε, THC. <i>1, 13, etc</i>. de tout temps ;<br><b>   II</b> (<i>avec idée de temps déterminé</i>) :<br><b>      1</b> <i>en parl. du passé,</i> autrefois, jadis : ὅν ποτ' Ἀθήνη θρέψε, IL. <i>2, 547,</i> qu’Athènè nourrit jadis ; <i>joint à</i> ἤδη : ἤδη ποτέ, IL. <i>1, 260, etc. ; ou</i> ποτ' ἤδη, ESCHL. <i>Eum. 50, etc. ; dans les récits :</i> οὕτω ποτ' ἦν μῦς καὶ γαλῆ, AR. <i>Vesp. 1182,</i> ainsi donc il était une fois un rat et un chat ; <i>avec un prés. hist. :</i> τὸν μὲν ξένοι ποτὲ λῃσταὶ φονεύουσι, SOPH. <i>O.R. 714,</i> des brigands étrangers le tuent un jour ; <i>cf</i>. EUR. <i>El. 416, Bacch. 2 ; sans verbe avec un subst. :</i> τήν ποτε φιλίαν, AND. <i>26, 16,</i> l’amitié d’autrefois ;<br><b>      2</b> <i>en parl. de l’avenir,</i> un jour : καί ποτέ τοι παρέσσεται δῶρα, IL. <i>1, 213,</i> et un jour tu recevras des présents ; <i>cf</i>. IL. <i>1, 240 ;</i> SOPH. <i>Ph. 880, etc</i>.<br><span><b><span class=\"arrow\"></span></b> ποτέ <i>se place d’ord. après un mot, qqf. au commenc. de la prop</i>. EUR. <i>Ion 563 ;</i> DÉM. <i>959, 24 ;</i> ALCIPHR. <i>1, 3, 2 ; dor</i>. ποκά, PD. <i>N. 6, 43, etc. ; éol</i>. πότα, SAPPH. <i>fr. 1, 5 Bgk ; ion</i>. κοτέ, HDT. <i>l. c. etc</i>.<br><span><b>Étym</b>. *πός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποτε - ποτέ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n32 fois dans 31 versets de 15 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Jean (1)</li>\n<li>Actes (1)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (1)</li>\n<li>Galates (4)</li>\n<li>Ephésiens (6)</li>\n<li>Philippiens (1)</li>\n<li>Colossiens (2)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Tite (1)</li>\n<li>Philémon (1)</li>\n<li>Hébreux (4)</li>\n<li>1 Pierre (3)</li>\n<li>2 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G4219":"<h1>pote</h1>\n<p>Strong n° 4219 <i>Prononciation [pot'-eh]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>quand ?, à quelle heure ?</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πό·τε</b>, <i>adv. interr</i>. quand ? à quelle époque ? IL. <i>19, 227 ;</i> OD. <i>4, 642, etc. ;</i> πότε δή ; ESCHL. <i>Ch. 720, m. sign. ;</i> ἐς πότε ; SOPH. <i>Aj. 1185,</i> jusques à quand ?.<br><span><b>Étym</b>. *πός, τε.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποτε - πότε</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n19 fois dans 17 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (7)</li>\n<li>Marc (5)</li>\n<li>Luc (4)</li>\n<li>Jean (2)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4220":"<h1>poteron</h1>\n<p>Strong n° 4220 <i>Prononciation [pot'-er-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>lequel des deux</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>πότερος, </b><b>α, ον :<br>      1</b> <i>adj. interr</i>. lequel des deux ? κότερα (<i>ion</i>.) τούτων αἱρετώτερά ἐστι ; HDT. <i>3, 52,</i> laquelle de ces deux choses est préférable ? πότερα τύχης καὶ πότερα γνώμης ἔργα κρίνεις ; XÉN. <i>Mem. 1, 4, 4,</i> laquelle des deux choses estimes-tu être l’œuvre de la fortune, et laquelle l’œuvre de la réflexion ? <i>dans le disc. indir. :</i> οὐκ ἂν γνοίης ποτέροισι μετείη, IL. <i>5, 85,</i> tu n’aurais pas reconnu à laquelle de ces deux (armées) appartenait (Diomède) ; ἐρωτώσης τῆς μητρὸς πότερος καλλίων δοκεῖ εἶναι ὁ πατὴρ ἢ οὗτος, XÉN. <i>Cyr. 1, 3, 2,</i> sa mère lui demandant lequel des deux lui paraissait être le plus beau, son père <i>ou</i> son grand-père ; <i>avec la mention des deux objets de l’alternative en appos. après</i> πότερος : πότερος ὁ ἰατρὸς ἢ ὁ ὀψοποιός, PLAT. <i>Gorg. 464</i> d, lequel des deux, le médecin <i>ou</i> le cuisinier ; <i>de même dans le disc. indir. (v. ci-dessus</i> XÉN. <i>Cyr. 1, 3, 2) ; joint à</i> τις, PLAT. <i>Leg. 715</i> a ; <i>répété dans la même propos. :</i> πότερος ποτέρου φίλος γίγνεται ; PLAT. <i>Lys. 212</i> a, lequel des deux devient l’ami de l’autre (<i>litt</i>. duquel des deux) ? <i>adv. au neutre</i> πότερον <i>ou</i> πότερα, <i>dans le premier membre d’une interrog. disjonctive dont les deux termes sont réunis par</i> ἤ (<i>cf. lat</i>. utrum… an) : τίνες κατῆρξαν πότερον Ἕλληνες μάχης, ἢ παῖς ἐμός ; ESCHL. <i>Pers. 351,</i> lequel des deux a commencé le combat, les Grecs ou mon fils ? <i>cf</i>. ESCHL. <i>Suppl. 335, etc. ;</i> HDT. <i>1, 88, etc. ; dans le disc. indir. :</i> HDT. <i>1, 91 ; 3, 32, etc. ; avec un verbe dans chacune des propos. correspondantes :</i> πότερα οὐδενὶ ἀρέσαι δύναται, ἢ ἔστιν οἷς καὶ πάνυ ἀρέσκει ; XÉN. <i>Mem. 2, 3, 6, litt</i>. laquelle des deux choses est-ce ? ne peut-il plaire à personne, ou y a-t-il des gens à qui il plaît, et même fort ? <i>p. ext. en parl. d’une alternative entre trois choses, p. suite avec</i> ἤ <i>répété deux fois,</i> HDT. <i>3, 82 ;</i> ESCHL. <i>Suppl. 247 ;</i> SOPH. <i>O.R. 112 ; même entre quatre choses,</i> SOPH. <i>El. 539 ; avec une des deux alternatives s.-entendue (la seconde,</i> ESCHL. <i>Pers. 239, etc. ;</i> SOPH. <i>Ph. 1235, etc. ;</i> PLAT. <i>Soph. 228</i> a, <i>etc. ; la première en s.-entend</i>. πότερον, PLAT. <i>Theæt. 161</i> d) ;<br><b>      2</b> <i>adj. indéf</i>. l’un ou l’autre, l’un des deux, PLAT. <i>Charm. 171</i> b, <i>Theæt. 145</i> a, <i>Phil. 20</i> e, <i>etc. (en ce sens accentué</i> ποτερός <i>sel</i>. PHOT. <i>Lex. v°</i> πότερος).<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κότερος, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. *πός, <i>cf. lat</i>. uter <i>p</i>. *cuter, <i>sscr</i>. kataras = πότερος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποτερον - πότερον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Conjonction</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4221":"<h1>poterion</h1>\n<p>Strong n° 4221 <i>Prononciation [pot-ay'-ree-on</i>]</p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une coupe, un récipient pour boire</li>\n<li>métaph. le sort ou expérience, en joie ou adversité, la désignation divine, favorable ou défavorable, sont comme une coupe que Dieu nous présente à boire : la prospérité ou l'adversité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ποτήριον, </b><b>ου (τὸ) :<br>      1</b> vase à boire, coupe, ALC. <i>52 (60) ;</i> HDT. <i>2, 37 ; 3, 148, etc. ;</i> AR. <i>Eq. 120, etc. ;</i> CTÉS. (ATH. <i>464</i> a), <i>etc. ; t. eccl</i>. calice eucharistique, NT. <i>1Cor. 11, 25, etc. ;</i><br><b>      2</b> <i>p. anal</i>. astragale épineux (<i>astragalus poterium</i> L.) <i>plante,</i> DIOSC. <i>3, 15, etc</i>.<br><span><b>Étym</b>. <i>dim. de</i> ποτήρ.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποτηριον - ποτήριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n32 fois dans 29 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (8)</li>\n<li>Marc (6)</li>\n<li>Luc (5)</li>\n<li>Jean (1)</li>\n<li>1 Corinthiens (8)</li>\n<li>Apocalypse (4)</li>\n</ul>\n</td></tr>\n</table>","G4222":"<h1>potizo</h1>\n<p>Strong n° 4222 <i>Prononciation [pot-id'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>donner à boire, fournir de la boisson</li>\n<li>arroser, irriguer (des plantes, champs etc.)</li>\n<li>métaph. imprégner, saturer son esprit</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ποτίζω</b> <span>(<i>ao</i>. ἐπότισα)</span><br><b>      1</b> donner à boire, faire boire, <i>avec l’acc. de la substance qu’on donne à boire,</i> HPC. <i>Aph. 1260 ;</i> ARSTT. <i>Phys. 2, 8, 11 ; avec double acc. :</i> τινά τι π. donner qqe ch. à boire à qqn, SPT. <i>Gen. 24, 17 ;</i> NT. <i>Marc. 9, 41, etc. ;</i> ἵππους τι π. PLAT. <i>Phædr. 247</i> e, donner qqe ch. à boire à des chevaux ;<br><b>      2</b> <i>p. ext</i>. abreuver (la terre, ANTH. <i>1, 100 ;</i> SPT. <i>Gen. 13, 10, etc. ;</i> STR. <i>11, 4, 3, etc. Kram., etc</i>. les plantes, XÉN. <i>Conv. 2, 25 ;</i> les bestiaux, THCR. <i>Idyl. 1, 121) ; au pass</i>. ποτιζομένη γῆ, LUC. <i>Abd. 27,</i> terre abreuvée, arrosée.<br><span><b><span class=\"arrow\"></span></b> <i>Dor</i>. ποτίσδω, THCR. <i>l. c</i>.<br><span><b>Étym</b>. πότος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποτιζω - ποτίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n17 fois dans 15 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (2)</li>\n<li>Luc (1)</li>\n<li>Romains (2)</li>\n<li>1 Corinthiens (6)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4223":"<h1>Potioloi</h1>\n<p>Strong n° 4223 <i>Prononciation [pot-ee'-ol-oy]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pouzzoles (Angl. Puteoli) = « petites sources »\n<ol><li>une cité de Campanie, en Italie, située sur la Baie de Naples</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποτιολοι - Ποτίολοι</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre de lieu</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4224":"<h1>potos</h1>\n<p>Strong n° 4224 <i>Prononciation [pot'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une beuverie, faire la fête</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>ποτός, </b><b>ή, όν :<br>   I</b> <i>adj</i>. qu’on boit, bu, EUR. <i>Hipp. 516 ;</i> THC. <i>6, 100 ; joint à</i> ἐδανός, ESCHL. <i>Ag. 1408 ;</i><br><b>   II</b> <i>subst</i>. τὸ ποτόν :<br><b>      1</b> boisson, <i>en gén</i>. OD. <i>2, 341 ;</i> HDT. <i>2, 121 ; au plur</i>. HDT. <i>5, 54 ;</i> XÉN. <i>An. 2, 3, 27 ; joint à</i> σίτια, PLAT. <i>Prot. 334</i> a, <i>à</i> βρωτά, EUR. <i>Suppl. 1110 ; particul</i>. vin, IL. <i>1, 470, etc. ;</i> ESCHL. <i>Pers. 615, etc. ;</i><br><b>      2</b> <i>p. ext</i>. eau potable, ESCHL. <i>Ag. 1157, etc. ;</i> SOPH. <i>Ph. 21, etc. ;</i> THCR. <i>Idyl. 13, 46</i>.<br><span><b>Étym</b>. πίνω.</span><br><br>\n➁ <b>πότος, </b><b>ου (ὁ)</b> action de boire, boisson, XÉN. <i>An. 7, 3, 26 ;</i> PLAT. <i>Conv. 176</i> a, <i>etc. ; au pl</i>. PLAT. <i>Rsp. 329</i> a ; ISOCR. <i>9</i> a, <i>etc. ;</i> ἐν τῷ πότῳ, PLAT. <i>Prot. 347</i> c ; παρὰ πότον, XÉN. <i>An. 2, 3, 15, Conv. 8, 41, etc</i>. en buvant, pendant le repas.<br><span><b>Étym</b>. πίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">ποτος - πότος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4225":"<h1>pou</h1>\n<p>Strong n° 4225 <i>Prononciation [poo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>où ?, en quel lieu ?</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>ποῦ</b>, <i>adv. de lieu interr</i>. où ? en quel endroit ? :<br><b>      1</b> <i>d’ord. sans mouv</i>. ποῦ τοι Δηΐφοϐος ; IL. <i>13, 172,</i> où donc est Dèiphobos ? ἀλλ' ἧμιν Αἴας ποῦ 'στιν ; SOPH. <i>Aj. 733,</i> mais Ajax où est-il ? <i>dans le disc. indir</i>. τίς οἶδεν ὑμῶν ποῦ ποθ' οἱ Φωκῆς ξένοι ; SOPH. <i>El. 1442,</i> qui de vous sait où peuvent bien être les étrangers Phocidiens ? <i>avec</i> δή, ESCHL. <i>Ch. 900 ; ou</i> δῆτα, ESCHL. <i>Ch. 916 ;</i> SOPH. <i>El. 1450 ; etc. ; avec le gén</i>. ποῦ γῆς ; ESCHL. <i>Pers. 231 ;</i> ποῦ τῆς χώρας ; XÉN. <i>Hipp. 7, 14, etc</i>. en quel endroit de la terre ? de ce pays ? <i>fig</i>. ποῦ σοι τύχης ἕστηκεν ; SOPH. <i>Aj. 102,</i> quelle a été sa fortune ? qu’est-il devenu ? <i>cf</i>. SOPH. <i>El. 390, Ant. 42, etc. ;</i><br><b>      2</b> <i>qqf. avec idée d’un mouv. antérieur :</i> ποῦ τοι ἀπειλαὶ οἴχονται ; IL. <i>13, 219,</i> où sont maintenant les menaces ? elles s’en sont allées ; <i>cf</i>. SOPH. <i>Aj. 1237</i>.<br><span><b>Étym</b>. *πός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">που - πού</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4226":"<h1>pou</h1>\n<p>Strong n° 4226 <i>Prononciation [poo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>quelque part</li>\n<li>de près</li>\n<li>quelque part auprès de, autour de</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πού</b>, <i>adv. indéf. enclitique :</i><br><b>      1</b> quelque part, en quelque endroit, IL. <i>23, 460 ;</i> ESCHL. <i>Suppl. 778 ; joint à un adv</i>. οὐχ ἕκας που, SOPH. <i>Ph. 41,</i> qqe part non loin ; πέλας που, SOPH. <i>Ph. 163,</i> qqe part près d’ici ; <i>avec un gén. :</i> ποὺ αὐτοῦ ἀγρῶν, OD. <i>4, 639,</i> là même qqe part dans les champs ; ποὺ τῆς χώρας, XÉN. <i>Cyr. 6, 1, 42,</i> qqe part dans le pays ;<br><b>      2</b> en quelque manière, <i>d’où,</i> peut-être, probablement, je pense, je suppose, <i>etc</i>. θεός πού σοι τόγ' ἔδωκεν, IL. <i>1, 178,</i> c’est un dieu, je pense, qui t’a fait ce présent ; <i>cf</i>. IL. <i>2, 116 ; 3, 308 ;</i> ESCHL. <i>Pr. 1064, etc. ;</i> HDT. <i>3, 73 ;</i> THC. <i>3, 56, etc. ; particul. avec les conj. qui marquent le doute ou la possibilité :</i> εἴ που, ESCHL. <i>Suppl. 40 ;</i> SOPH. <i>El. 1473,</i> si par hasard ; ἐάν που, XÉN. <i>Hier. 3, 2, m. sign. ;</i> εἰ μή που, PLAT. <i>Rsp. 372</i> a, à moins que par hasard ; <i>avec un pron. indéf</i>. καί πού τι, THC. <i>2, 87,</i> et encore peut-être ; <i>avec un adv</i>. τάχα που, SOPH. <i>O.R. 1116,</i> peut-être, je pense ; <i>cf</i>. EUR. <i>El. 518 ; avec un n. de nombre :</i> ἔτεα τρία καὶ δέκα κου μάλιστα, HDT. <i>1, 119,</i> environ treize ans au plus ; <i>cf</i>. PAUS. <i>8, 11, 4, etc. ; avec la nég</i>. οὔ τι που, certes pas, IL. <i>17, 446 ;</i> PD. <i>P. 4, 154 ;</i> PLAT. <i>Rsp. 361</i> d, <i>etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. κου, HDT. <i>l. c. etc</i>.<br><span><b>Étym</b>. *πός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">που - ποῦ</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n47 fois dans 42 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (4)</li>\n<li>Marc (3)</li>\n<li>Luc (7)</li>\n<li>Jean (19)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (8)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n<li>1 Jean (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4227":"<h1>Poudes</h1>\n<p>Strong n° 4227 <i>Prononciation [poo'-dace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Pudens = « timide, modeste »\n<ol><li>un chrétien, ami de Timothée à Rome, et peut-être un des soixante-dix disciples</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>Πούδης, </b><b>εντος (ὁ)</b> = <i>lat</i>. Pudens, <i>n. d’h. rom</i>. ANTH. <i>App. 160, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πουδης - Πούδης</font>\n<br><br>origine : Latin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4228":"<h1>pous</h1>\n<p>Strong n° 4228 <i>Prononciation [pooce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un pied, à la fois de l'homme ou de l'animal\n<ol type=\"a\">\n<li>souvent en Orient, le vainqueur était celui qui posait son pied sur le vaincu</li>\n<li>on dit de disciples qui écoutent l'instruction de leur maître qu'ils sont à ses pieds</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πούς, </b><b>ποδός</b>, <i>dat. pl</i>. <b>ποσί (ὁ) :<br>   I</b> pied (de l’homme et des animaux) :<br><b>      1</b> <i>propr</i>. le pied, <i>càd</i>. la partie inférieure de la jambe, IL. <i>11, 377 ;</i> HDT. <i>9, 37, etc. ; au plur</i>. IL. <i>17, 386, etc</i>. τέγγειν πόδα <i>ou</i> πόδας, mouiller le pied, <i>càd</i>. toucher l’eau, la mer avec les pieds, PLAT. <i>Leg. 866</i> c ; <i>d’où</i> mettre le pied à l’eau en quittant le rivage pour s’embarquer, EUR. <i>I.T. 1380 ;</i> ἐς πόδας ἐκ κεφαλῆς, IL. <i>18, 353 ; 23, 169 ;</i> ἀπὸ τᾶς κεφαλᾶς ποτὶ τὼ πόδε, THCR. <i>Idyl. 20, 12,</i> de la tête aux pieds ; ἐκ κεφαλῆς ἐς πόδας ἄκρους, IL. <i>16, 640,</i> de la tête au bout des pieds ; ἐκ τῶν ποδῶν ἐς τὴν κεφαλήν, AR. <i>Pl. 650,</i> des pieds à la tête ; <i>fig. càd</i>. du commencement jusqu’à la fin ; ἐς κορυφὴν ἐκ ποδός, ANTH. <i>7, 388,</i> des pieds à la tête ; ἐκ τριχὸς ἄχρι ποδῶν, ANTH. <i>5, 194,</i> des cheveux, <i>càd</i>. de la tête aux pieds ; <i>particul. avec idée de vitesse :</i> πόδεσσι νικᾶν, IL. <i>20, 410 ;</i> OD. <i>13, 261 ; ou</i> ποσσὶ κρατεῖν, PD. <i>N. 3, 89,</i> vaincre à la course ; ὡς ἔχει ποδῶν, PLAT. <i>Gorg. 507</i> d ; <i>ellipt</i>. ὅπως ποδῶν, ESCHL. <i>Suppl. 837 ;</i> ᾗ ποδῶν ἔχουσιν, EL. <i>V.H. 1, 11 ; ou</i> ὡς ποδῶν εἶχον τάχιστα, HDT. <i>6, 116,</i> de toute la vitesse de ses pieds, de leurs pieds ; ποσσὶν ἀμφοτέροισιν, IL. <i>13, 78 ;</i> ἀμφοῖν ποδοῖν, AR. <i>Av. 35 ; ou</i> ἐκ δυοῖν ποδοῖν, ARSTD. <i>t. 1, 117,</i> (aller, fuir, <i>etc</i>.) de ses deux pieds, <i>càd</i>. de toute sa vitesse ; βοηθεῖν καὶ χειρὶ καὶ ποδί, ESCHN. <i>69, 9,</i> porter secours des pieds et des mains, <i>càd</i>. de tout son pouvoir ; <i>ou</i> ὅλῳ ποδί, ARSTT. <i>H.A. 1, 15,</i> de tout son pied, <i>càd</i>. de toute sa force ; οὐ τὸν ἕτερον πόδα προϐαίνειν, AR. <i>Eccl. 161 ;</i> LUC. <i>H. conscr. 29, etc</i>. ne pas avancer un pied, <i>càd</i>. n’avancer à rien ; <i>p. ext</i>. πούς τινος, EUR. <i>Hipp. 661, etc</i>. le pied d’une personne, pour cette personne même. — <i>Ce mot entre dans un grand nombre de locutions :</i> τὰ πρὸ τῶν ποδῶν, XÉN. <i>Lac. 3, 4, etc. ; ou</i> πρὸ ποδῶν, PLAT. <i>Rsp. 432</i> d ; τὰ πρὸς ποσίν, SOPH. <i>O.R. 130 ;</i> τὰ πρὸ τοῖν ποδοῖν, LUC. <i>Bis acc. 34,</i> ce qui est devant les pieds, <i>càd</i>. à proximité, présent ; ὁ ἐν ποσί, HDT. <i>3, 79,</i> le premier venu ; τὰ ἐν ποσί, les choses présentes, LUC. <i>Nigr. 7, etc. cf</i>. SOPH. <i>Ant. 1327 ; ou</i> les choses ordinaires, habituelles, PLAT. <i>Theæt. 175</i> b ; τὰ παρὰ πόδα, SOPH. <i>Ph. 838 ; ou</i> τὰ παρὰ πόδας, PLAT. <i>Theæt. 174</i> a ; LUC. <i>Cal. 1,</i> ce qu’on a devant soi, ce qu’on rencontre devant soi, <i>p. ext</i>. les choses ordinaires, communes <i>ou</i> faciles ; <i>d’où sans art</i>. παρὰ πόδα, PLAT. <i>Soph. 242</i> a, sur le moment ; παρὰ πόδας, tout de suite après, POL. <i>1, 35, 3, etc. ; ou</i> au moment même, POL. <i>6, 9, 2 ; ou</i> à portée, LUC. <i>H. conscr. 13 ;</i> παρὰ ποδός, <i>poét</i>. πὰρ ποδός, à partir du pied, <i>càd</i>. devant le pied, à notre portée, en notre pouvoir, PD. <i>P. 3, 108, etc. ; p. suite,</i> sans réflexion, THGN. <i>282 ;</i> πὰρ ποδί, PD. <i>O. 1, 118 ;</i> devant le pied, devant les pieds, <i>càd</i>. aussitôt ; ἐκ ποδὸς ἕπεσθαι, POL. <i>3, 68, 1, etc. ; ou</i> ἀκολουθεῖν, DH. <i>2, 33, etc</i>. suivre pas à pas, marcher du même pas ; ἐκ. ποδῶν, HDT. <i>6, 35 ;</i> ATT. <i>c</i>. ἐκποδών ; ἐπὶ πόδα, XÉN. <i>Cyr. 3, 3, 69 ; 7, 1, 34 ; 7, 5, 6, etc. ;</i> ARR. <i>An. 5, 17, 7 ; ou</i> ἐπὶ πόδας, LUC. <i>Pisc. 12,</i> à reculons, en arrière ; κατὰ πόδα, <i>ou</i> κατὰ πόδας, HDT. <i>5, 98 ; 9, 89 ;</i> THC. <i>3, 98 ; 4, 126, etc. ;</i> XÉN. <i>Hell. 2, 1, 20 ;</i> PLAT. <i>Soph. 243</i> d, <i>etc</i>. pied à pied, pas à pas, en suivant de très près, <i>càd</i>. tout de suite, sans retard (<i>ttef</i>. κατὰ πόδας, en courant, grâce à la vitesse, XÉN. <i>Cyr. 1, 6, 40 ; Mem. 2, 6, 9, etc</i>.) ; τῇ κατὰ πόδας ἡμέρᾳ, POL. <i>1, 12, 1,</i> le jour qui suivit immédiatement ; <i>avec un gén. :</i> κατὰ πόδας τῆς ἐκκλησίας, POL. <i>3, 45, 5,</i> aussitôt après l’assemblée ; περὶ πόδα, LUC. <i>H. conscr. 14, etc</i>. autour du pied, <i>càd</i>. de manière à bien chausser ; ἔστι μοι τὸ χρῆμα περὶ πόδα, PLAT. COM. <i>2-2, 687 Mein.,</i> l’affaire me chausse, <i>càd</i>. me va, me convient parfaitement ; τινὸς ἔξω πόδα ἔχειν, ESCHL. <i>Pr. 263, ou</i> κομίζειν, ESCHL. <i>Ch. 697,</i> avoir <i>ou</i> porter le pied hors de qqe ch., <i>càd</i>. être débarrassé, délivré de qqe ch., être hors de qqe ch. ; τινὸς ἐκτὸς πόδα ἔχειν, SOPH. <i>Ph. 1260, m. sign. ;</i> ποσσὶ καταστείϐειν, SAPPH. <i>fr. 94 Bgk ;</i> ποδὶ ἐπεμϐῆναι, SOPH. <i>El. 456 ;</i> ὑπὸ πόδας τίθεσθαι, <i>acc</i>. PLUT. <i>M. 1097</i> c, <i>Æmil. 27,</i> mettre sous son pied, fouler aux pieds, mépriser ;<br><b>      2</b> <i>p. ext</i>. jambe, <i>p. opp. à</i> χείρ, bras, OD. <i>17, 479 ;</i> λαϐεῖν ποδός, OD. <i>18, 100,</i> saisir par la jambe ; ἔχειν ποδός, IL. <i>16, 762,</i> tenir par la jambe ; <i>au plur</i>. IL. <i>23, 772, etc. ;</i> OD. <i>4, 149, etc. ; de même, p. anal</i>. π. ξύλινος, HDT. <i>9, 37,</i> jambe de bois ;<br><b>   II</b> <i>p. anal. :</i><br><b>      1</b> <i>au pl</i>. serres des oiseaux de proie, OD. <i>15, 526 ;</i><br><b>      2</b> <i>au pl</i>. tentacules du poulpe, HÉS. <i>O. 522 ;</i><br><b>      3</b> pied d’un siège, d’une table, <i>etc</i>. XÉN. <i>Cyr. 8, 8, 16 ;</i> AR. <i>fr. 447, etc. ; en parl. des deux traits inférieurs de l’</i>Ω, CALLIAS (ATH. <i>454</i> a) ;<br><b>      4</b> pied d’une montagne (<i>cf. lat. radices montis</i>), IL. <i>2, 824 ; 20, 59 ;</i> PD. <i>N. 4, 88 ; P. 11, 54, etc. ;</i><br><b>      5</b> <i>t. de mar</i>. bouline, <i>cordage pour la manœuvre des voiles,</i> EUR. <i>I.T. 1135 ;</i> AR. <i>Eq. 436 ;</i> A. RH. <i>2, 931 ;</i> Q. SM. <i>9, 438 ; ou sel. qqes-uns,</i> gouvernail d’un navire, OD. <i>13, 22 ;</i><br><b>      6</b> pied d’un vers, AR. <i>Ran. 1322 ;</i> PLAT. <i>Rsp. 400</i> a ; GRAMM. <i>etc. ;</i><br><b>      7</b> pied, <i>mesure de longueur de 4 palmes ou 16 doigts 11 pouces 8 lignes ⁷⁄₁₀ ou, sel. Boeckh, 9 lignes ¹¹⁄₂₅,</i> HDT. <i>2, 149 ; d’où proverb. :</i> ὑπὲρ τὸν πόδα, LUC. <i>Im. 18,</i> au delà du pied, <i>càd</i>. de la mesure ;<br><b>      8</b> son <i>ou</i> cri lancé de toute la force des poumons, <i>en parl. de la flûte, de la trompette ou de la voix (p.-ê</i>. son qui part du fond de la poitrine, <i>p. opp. au son émis du bout des lèvres</i>) GAL. <i>5, 394, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Acc. sg</i>. ποῦν, ES. <i>155 de Furia ; dat. pl. poét</i>. πόδεσι, SOPH. (<i>Cram. t. 4, p. 183) ; épq. et lyr</i>. ποσσί, IL. <i>8, 443 ;</i> CRAT. (POLL. <i>7, 171) et</i> πόδεσσι, IL. <i>16, 809 ; 20, 410 ;</i> OD. <i>13, 261, etc. ;</i> Q. SM. <i>9, 438 ; gén. dat. duel homér</i>. ποδοῖϊν, IL. <i>18, 537. Dor. nomin</i>. πός, POÈT. (EM. <i>635, 22) etc. conservé dans les compos</i>. ἀρτίπος, πώλυπος, <i>etc</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *pod-, pied ; <i>cf</i>. πέδον, πεδίον, πέζα, πεζός, <i>etc. ; lat</i>. pēs, <i>th</i>. ped- ; <i>sscr</i>. pā́t, <i>acc</i>. pā́dam, <i>gén</i>. padás.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πους - πούς</font>\n<br><br>un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n93 fois dans 87 versets de 11 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (6)</li>\n<li>Luc (18)</li>\n<li>Jean (14)</li>\n<li>Actes (19)</li>\n<li>Romains (3)</li>\n<li>1 Corinthiens (4)</li>\n<li>Ephésiens (2)</li>\n<li>1 Timothée (1)</li>\n<li>Hébreux (4)</li>\n<li>Apocalypse (11)</li>\n</ul>\n</td></tr>\n</table>","G4229":"<h1>pragma</h1>\n<p>Strong n° 4229 <i>Prononciation [prag'-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ce qui a été fait, un fait, un fait accompli</li>\n<li>ce qui est fait ou en train de s'accomplir\n<ol type=\"a\">\n<li>spéc. affaire, une transaction commerciale</li>\n</ol>\n</li>\n<li>une question, une affaire, un événement\n<ol type=\"a\">\n<li>spéc. dans un sens judiciaire une matière à légiférer, un cas</li>\n</ol>\n</li>\n<li>ce qui est ou existe, une chose</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρᾶγμα, </b><b>ατος (τὸ) :</b> affaire, <i>càd. :</i><br><b>   I</b> ce qu’on fait : τί σοι πέπρακται πρᾶγμα ; ESCHL. <i>Eum. 125,</i> qu’as-tu fait ? τὸ πρᾶγμ' οὔτ' ἔδρασα, SOPH. <i>Ant. 239,</i> je n’ai pas fait la chose en question ; τὰ πράγματα, DÉM. <i>404, 18, etc</i>. les choses faites, les actions, les actes ;<br><b>   II</b> action de faire, action d’entreprendre, <i>d’où :</i><br><b>      1</b> <i>abs</i>. activité, agissement : ἄνευ πραγμάτων (τὰ χρήματα) λαμϐάνειν, DÉM. <i>14 fin,</i> recevoir (l’argent) sans rien faire pour cela ;<br><b>      2</b> ce qu’on doit faire, tâche, obligation : ἐννοῶν τὸ αὑτοῦ πρᾶγμα, ὅτι ἐπιχειροίη ἄρχειν πολλῶν ἀνθρώπων, XÉN. <i>Cyr. 7, 5, 58,</i> songeant à sa tâche, pensant qu’il entreprendrait de commander à un grand nombre d’hommes ; τὸ σὸν τί ἐστι πρᾶγμα ; PLAT. <i>Ap. 20</i> c, ta tâche, quelle est-elle ? <i>cf</i>. PLAT. <i>Prot. 312</i> c ; DÉM. <i>787, 25 ;</i><br><b>      3</b> ce qu’on se propose de faire, entreprise : ἔρχεσθαι ἐπὶ τὰ πράγματα, THC. <i>1, 89,</i> parvenir à la direction des affaires ; πράγματα πράττειν, ATT. entreprendre des affaires ;<br><b>      4</b> ce qu’on fait, <i>particul</i>. affaire qu’on traite, <i>d’où</i> négociation ; <i>en mauv. part,</i> menées, intrigues : τὰ πρὸς βασιλέα πράγματα πράσσειν, THC. <i>1, 128,</i> former des intrigues avec le roi ;<br><b>      5</b> <i>abs. en mauv. part,</i> affaire désagréable, désagrément : δῆλον ἦν ὅτι πρᾶγμά τι εἴη, XÉN. <i>An. 4, 1, 17,</i> il était évident qu’il y avait qqe difficulté ; οἳ μὲν σὺν πράγμασιν, οἳ δὲ ἄνευ πραγμάτων, XÉN. <i>An. 6, 1, 6,</i> les uns avec des désagréments, les autres sans difficultés ; ἄξιοί ἐσμεν τοῦ γεγενημένου πράγματος τούτου ἀπολαῦσαί τι ἀγαθόν, XÉN. <i>Cyr. 5, 4, 20,</i> nous méritons bien de retirer qqe avantage de ce désagrément qui nous est survenu ; <i>p. suite, en gén</i>. difficulté, embarras : πρήγματα ἔχειν, HDT. <i>7, 147,</i> avoir du tracas ; ὅσα πράγματα ἔχεις, XÉN. <i>Cyr. 1, 3, 4 ;</i> PLAT. <i>Theæt. 174</i> b ; ISOCR. <i>146</i> b, <i>etc</i>. que de tracas tu as ! <i>cf</i>. XÉN. <i>Cyr. 1, 4, 5, etc. ;</i> οἱ πῶλοι ὅταν ἀπειθῶσι πράγματα ἔχουσιν, XÉN. <i>Œc. 13, 7,</i> les jeunes chevaux, lorsqu’il leur arrive d’être indociles, reçoivent une punition ; <i>avec un suj. de chose :</i> τὰ περιττὰ χρήματα πράγματα ἔχουσιν, XÉN. <i>Cyr. 8, 2, 21,</i> les meilleures choses ont des inconvénients ; πράγματα λαμϐάνειν, XÉN. <i>Lac. 2, 10, m. sign. ;</i> πρᾶγμα <i>ou</i> πράγματα παρέχειν τινί, causer à qqn du désagrément, de l’ennui, HDT. <i>7, 239 ;</i> XÉN. <i>An. 1, 1, 11 ; 4, 1, 22, etc. ;</i> PLAT. <i>Phædr. 254</i> a, <i>etc. ; avec l’inf</i>. πράγματα παρέχουσιν οἱ ἵπποι ἐπιμέλεσθαι, XÉN. <i>Cyr. 4, 5, 46,</i> les chevaux donnent du mal à soigner ; <i>particul. au plur</i>. les affaires publiques, le gouvernement, le pouvoir : καταλαμϐάνεσθαι τὰ πράγματα, s’emparer du gouvernement, HDT. <i>6, 39 ; ou</i> arriver au pouvoir, acquérir (par la lutte) la suprématie, la puissance, l’hégémonie, THC. <i>3, 11, 30 ;</i> δέχεσθαι τὰ πρ. PLUT. <i>Pomp. 5,</i> recevoir le pouvoir ; ἅπτεσθαι τῶν πολιτικῶν πραγμάτων, PLUT. <i>Them. 3,</i> s’adonner à l’administration de l’État ; τὰ πρ. κατασχεῖν, THC. <i>4, 2 ;</i> XÉN. <i>Hell. 2, 3, 18,</i> obtenir le pouvoir ; οἱ ἔχοντες τὰ πρ. THC. <i>3, 72 ;</i> XÉN. <i>Hell. 1, 6, 13,</i> les gouvernants, les détenteurs du pouvoir ; οἱ ἐν τοῖς πράγμασι, THC. <i>3, 28 ;</i> ARSTT. <i>Pol. 5, 6, 8, etc. ;</i> οἱ ἐπὶ τῶν πραγμάτων, DÉM. <i>309, 10 ;</i> οἱ ἐπὶ τοῖς πράγμασιν, DÉM. <i>110, 22,</i> ceux qui sont aux affaires, à la tête des affaires ; κοινωνοὶ τῶν πραγμάτων, XÉN. <i>Hell. 2, 3, 17,</i> ceux qui prennent part aux affaires publiques ;<br><b>      6</b> <i>en mauv. part ;</i> νεώτερα πράγματα, HDT. <i>5, 19 ;</i> XÉN. <i>Hell. 5, 2, 9 ;</i> LYS. <i>130, 17, etc</i>. nouveauté dans la direction des affaires, <i>càd</i>. troubles, révolution (<i>cf. lat</i>. res novæ) ;<br><b>   III</b> ce qui est fait, ce qui existe, <i>d’où en gén</i>. événement, chose, affaire, HDT. <i>5, 33 ;</i> ATT. (XÉN. <i>Cyr. 6, 3, 15, etc.) ; particul. :</i><br><b>      1</b> les choses de la nature : τὰ μετέωρα πράγματα, AR. <i>Nub. 228, 1284,</i> les phénomènes et les corps célestes ; εἴ τις ἐξ ἀρχῆς τὰ πράγματα φυόμενα βλέψειεν, ARSTT. <i>Pol. 1, 1, 3,</i> si l’on pouvait voir l’origine première des choses ; <i>joint à</i> τὴν φύσιν, PLUT. <i>Alex. 7 ;</i><br><b>      2</b> <i>en parl. de pers. :</i> ἦν δὲ μέγιστον πρῆγμα Δημοκήδης παρὰ βασιλέϊ, HDT. <i>3, 132,</i> Dèmokèdès était une grande affaire, <i>càd</i>. une personne de grand crédit auprès du roi ; γυναῖκα, ἄμαχον πρᾶγμα, XÉN. <i>Cyr. 6, 1, 36,</i> une femme, être impropre aux combats ; <i>cf</i>. DÉM. <i>385, 5 ; 928, 5 ;</i> LUC. <i>As. 4, etc. ;</i><br><b>      3</b> <i>p. suite, périphr. en parl. de pers. et de choses :</i> οὐκ ἐς τοῦτο θράσεος ἀνήκει τὰ Ἑλλήνων πρήγματα, HDT. <i>7, 9,</i> la politique des Hellènes ne se porta jamais à une pareille témérité ; πρᾶγμα δ' ἐστί μοι μέγα φρέατος, ALEX. (<i>Com. fr. 3, 468</i>) j’ai un grand puits (<i>litt</i>. une grande machine de puits, un grand diable de puits) ; σοὶ δὲ καὶ τούτοισι τοῖσι πρήγμασι τί ἐστι ; HDT. <i>5, 33,</i> mais toi, qu’as-tu à faire de cela ? σφίσι τε καὶ Ἀθηναίοισι εἶναι οὐδὲν πρῆγμα, HDT. <i>5, 84,</i> ils n’avaient aucune affaire avec les Athéniens ;<br><b>      4</b> <i>p. suite, pour résumer ce qui précède par un terme général :</i> ὁρᾶτε τὸ πρᾶγμα, οἷ προελήλυθεν ἀσελγείας ἅνθρωπος, DÉM. <i>42, 25 ;</i> vous voyez la chose et jusqu’où est allée l’impudence de l’homme ; <i>en ce sens par opp. à</i> ὄνομα, DÉM. <i>114, 12 ; à</i> λόγος, DÉM. <i>21, 21 ; 268, 11 ; joint à</i> ἔργον, DÉM. <i>566, 19 ;</i><br><b>      5</b> <i>particul</i>. choses de l’État, <i>càd</i>. puissance de l’État, l’État, HDT. <i>7, 236 ;</i> τὰ Περσικὰ πρ. HDT. <i>3, 137, etc. ;</i> τὰ Περσῶν πράγματα, ESCHL. <i>Pers. 700,</i> la puissance des Perses ; ἐν ταῖς ναυσὶ τῶν Ἑλλήνων τὰ πράγματα ἐγένετο, THC. <i>1, 74,</i> la puissance des Grecs repose sur leur flotte ; <i>cf</i>. THC. <i>1, 110 ;</i> XÉN. <i>Hell. 2, 1, 2 et 19, etc. ;</i> DÉM. <i>42, 16 ; 53, 1, etc. ;</i><br><b>      6</b> l’affaire qui est en question, la chose qui importe ; ἔξω τοῦ πράγματος βλασφημεῖν, DÉM. <i>1308, 22 ;</i> λέγειν, LYCURG. <i>§ 11,</i> déblatérer, parler en dehors de la question ; οἱ ἔξω τοῦ πράγματος, DÉM. <i>519, 21 ; 528, 21,</i> ceux qui sont hors de cause, qui n’ont rien à voir dans la chose en question ; ἐρῶ εἰς αὐτὸ τὸ πρᾶγμα, DÉM. <i>1317, 15,</i> je vais parler en entrant au cœur de la question ; <i>cf</i>. DÉM. <i>1319, 6 ;</i> πρῆγμά ἐστι, <i>avec ou sans dat. de pers., et suivi ou non de l’inf</i>. cela importe, est nécessaire, convenable, sage ; Κῦρος εὕρισκε πρῆγμά οἱ εἶναι ἐλαύνειν ἐπὶ τὰς Σάρδις, HDT. <i>1, 79,</i> Cyrus trouvait que c’était pour lui chose importante de pousser jusqu’à Sardes, <i>cf</i>. HDT. <i>4, 11 ; 7, 103 ; avec la nég</i>. οὐδὲν ἂν εἴη πρῆγμα γνώμας ἐμέ σοι ἀποφαίνεσθαι, HDT. <i>1, 207,</i> il ne servirait de rien que je t’explique mes pensées ; <i>cf</i>. HDT. <i>1, 17 ; 7, 12 ;</i> PLAT. <i>Crat. 396</i> d, <i>etc. ; avec le gén. :</i> οἷς μηδὲν ἦν πρᾶγμα τοῦ πολέμου, PLUT. <i>Pomp. 65,</i> ceux qui ne se souciaient pas de la guerre ; πρῆγμα ποιεῖσθαί τι, HDT. <i>7, 150,</i> faire de qqe ch. une chose d’importance, considérer une chose comme importante ;<br><b>      7</b> <i>p. suite, abs</i>. chose de prix, <i>càd. au plur. c</i>. χρήματα, biens, richesses, PLUT. <i>Ages. 12, Per. 16, etc. ;</i><br><b>      8</b> <i>en gén</i>. circonstances, affaires : κύκλος τῶν ἀνθρωπηΐων πρηγμάτων περιφερόμενος, HDT. <i>1, 207,</i> le cours des choses humaines ; <i>cf</i>. THC. <i>3, 82 ;</i> XÉN. <i>Hell. 3, 5, 1, etc. ; particul. en parl. de conjonctures difficiles ou défavorables,</i> XÉN. <i>An. 2, 1, 16, etc. ;</i> SOPH. <i>Tr. 375, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πρῆγμα, HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. πράσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πραγμα - πρᾶγμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n11 fois dans 11 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>Hébreux (3)</li>\n<li>Jacques (1)</li>\n</ul>\n</td></tr>\n</table>","G4230":"<h1>pragmateia</h1>\n<p>Strong n° 4230 <i>Prononciation [prag-mat-i'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la poursuite de toute affaire\n<ol type=\"a\">\n<li>activité, occupation, affaire (parfois embarrassante)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πραγματεία, </b><b>ας (ἡ)</b> <span>[μᾰ]</span><br><b>   I</b> soin qu’on met à faire qqe ch., <i>d’où</i> poursuite d’une affaire, occupation, application, étude, PLAT. <i>Crat. 408</i> a, <i>etc. ;</i> ISOCR. <i>11</i> d, <i>83</i> e, <i>etc. ;</i><br><b>   II</b> peine, labeur, travail, affaire, <i>en gén</i>. PLAT. <i>Gorg. 453</i> a ; ARSTT. <i>Pol. 3, 1, 1, etc. ; au plur</i>. PLAT. <i>Rsp. 500</i> c ; ANT. <i>120, 14 ;</i><br><b>   III</b> <i>particul. en parl. des travaux de l’esprit :</i><br><b>      1</b> étude d’une question, PLAT. <i>Rsp. 528</i> d ;<br><b>      2</b> manière de traiter un sujet, ARSTT. <i>Rhet. 1, 15, 21 ;</i><br><b>      3</b> résultat d’une étude, <i>particul</i>. doctrine philosophique, ARSTT. <i>Metaph. 1, 6, 1, etc. ;</i><br><b>      4</b> argumentation, ARSTT. <i>Top. 1, 1, 1 ;</i><br><b>      5</b> sujet d’étude, ARSTT. <i>Phys. 2, 7, 3, etc. ;</i><br><b>      6</b> ouvrage d’histoire, <i>particul</i>. histoire politique, diplomatique <i>ou</i> philosophique, POL. <i>1, 1, 4 ; 1, 3, 1 ;</i> LUC. <i>H. conscr. 13 ;</i><br><b>   IV</b> mouvement des affaires, <i>particul</i>. embarras, difficultés, DÉM. <i>1412, 20 ;</i> STR. <i>401</i>.<br><span><b>Étym</b>. πραγματεύομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πραγματεια - πραγματεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4231":"<h1>pragmateuomai</h1>\n<p>Strong n° 4231 <i>Prononciation [prag-mat-yoo'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être occupé à quelque chose</li>\n<li>continuer une affaire</li>\n<li>exercer une activité de banquier ou de commerçant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πραγματεύομαι</b> <span>(<i>f</i>. εύσομαι, <i>ao</i>. ἐπραγματευσάμην <i>et</i> ἐπραγματεύθην, <i>pf</i>. πεπραγμάτευμαι)</span> <span>[μᾰ]</span><br><b>      1</b> se donner de la peine, du tracas, HDT. <i>2, 87 ;</i> ATT. ; πρ. τι, PLAT. <i>Prot. 361</i> d, <i>Hipp. ma. 304</i> c, <i>etc. ;</i> περί τι, XÉN. <i>Mem. 4, 2, 7 ;</i> PLAT. <i>Theæt. 187</i> a ; περί τινος, PLAT. <i>Rsp. 430</i> d, <i>etc. ;</i> ἐπί τινι, XÉN. <i>Mem. 1, 3, 15,</i> se donner de la peine pour qqe ch. ; πρός τι, PLAT. <i>Eryx. 398</i> a, en vue de qqe ch. ; <i>avec un inf</i>. chercher à, s’efforcer de, PLUT. <i>Them. 19 ; avec</i> ὅπως <i>et l’ind. fut</i>. faire effort pour, XÉN. <i>Lac. 14, 5 ; en mauv. part et abs</i>. intriguer, machiner une intrigue, agir avec mauvaise foi, DÉM. <i>980, 26 ; en parl. du travail de l’intelligence :</i> se livrer à l’étude, s’occuper de, <i>avec</i> περί <i>et le gén</i>. ARSTT. <i>Metaph. 1, 8, 18, etc. ; avec</i> περί <i>et l’acc</i>. ARSTT. <i>Metaph. 5, 1, 3, etc. ; p. suite,</i> traiter de, composer, écrire, <i>acc</i>. PLAT. <i>Ap. 22</i> b ; POL. <i>1, 4, 3 ;</i> DL. <i>5, 27, etc. ; abs</i>. composer un ouvrage d’histoire, POL. <i>5, 33, 5, etc. ;</i><br><b>      2</b> s’occuper d’affaires, de négoce, de commerce, PLUT. <i>Syll. 7, 17 ; Cato mi. 59</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. pass. au sens act</i>. ἐπραγματεύθην, ISOCR. <i>249</i> a ; <i>ion</i>. ἐπρηγματεύθην, HDT. <i>2, 87. Pf. au sens act</i>. ISOCR. <i>221</i> a ; PLAT. <i>Phæd. 99</i> d, <i>110</i> b ; DÉM. <i>37, 49 Baiter-Sauppe ; au sens pass</i>. PLAT. <i>Parm. 129</i> e, <i>Ap. 22</i> b ; ESCHN. <i>24, 5 ;</i> LGN <i>26, 3</i>.<br><span><b>Étym</b>. πρᾶγμα.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πραγματευομαι - πραγματεύομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (1)</li>\n</ul>\n</td></tr>\n</table>","G4232":"<h1>praitorion</h1>\n<p>Strong n° 4232 <i>Prononciation [prahee-to'-ree-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>« quartier-général » dans un camp Romain, la tente du commandant en chef</li>\n<li>le palais où réside le gouverneur ou procurateur d'une province, palais déjà existant dont les Romains avaient coutume de s'approprier l'usage, où demeuraient précédemment rois ou princes ; à Jérusalem c'était un magnifique palais que s'était fait construire Hérode le Grand et que les procurateurs Romains semblent avoir occupé toutes les fois qu'ils venaient de Césarée pour traiter les affaires publiques</li>\n<li>le camp de la Garde Prétorienne de Rome, établie par Tibère, soldats chargés de veiller sur le palais impérial (<a class=\"ref\" data-r=\"PHP1.13\">Philippiens 1.13</a>)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πραιτώριον, </b><b>ου (τὸ)</b> = <i>lat</i>. prætōrium, prétoire, palais du prince, NT. <i>Phil. 1, 13 ; ou</i> du gouverneur, NT. <i>Matth. 27, 27 ; Marc. 15, 16 ; Ap. 23, 25, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πραιτωριον - πραιτώριον</font>\n<br><br>origine : Latin 'qui appartient au préteur'</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 7 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Jean (4)</li>\n<li>Actes (1)</li>\n<li>Philippiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4233":"<h1>praktor</h1>\n<p>Strong n° 4233 <i>Prononciation [prak'-tor]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>celui qui fait quelque chose, qui pratique</li>\n<li>celui dont la mission est d'infliger un châtiment ou de venger\n<ol type=\"a\">\n<li>le vengeur du meurtrier</li>\n<li>un officier de justice de second ordre dont le travail est d'infliger la punition</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πράκτωρ, </b><b>ορος (ὁ, ἡ) :<br>      1</b> qui fait, qui accomplit, auteur d’une action, SOPH. <i>Tr. 251 ;</i> ANT. <i>121, 39 ; au fém</i>. SOPH. <i>Tr. 860 ;</i><br><b>      2</b> qui recouvre les créances de l’État, DÉM. <i>778, 18 ;</i> ANT. <i>147, 14 ;</i> AND. <i>10, 36 (décr.) ; p. ext. poét</i>. vengeur de, <i>gén</i>. ESCHL. <i>Eum. 319 ;</i> SOPH. <i>El. 953, etc. ; au fém</i>. ESCHL. <i>Ag. 111 ; p. ext</i>. qui perçoit les taxes, percepteur, NAZ. <i>3, 1060 a Migne ;</i><br><b>      3</b> <i>p. suite,</i> huissier d’un tribunal, NT. <i>Luc. 11, 28</i>.<br><span><b>Étym</b>. πράσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρακτωρ - πράκτωρ</font>\n<br><br>Voir définition </td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4234":"<h1>praxis</h1>\n<p>Strong n° 4234 <i>Prononciation [prax'-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une œuvre, un mode d'action, une affaire, une transaction\n<ol type=\"a\">\n<li>les actes des apôtres</li>\n<li>dans un mauvais sens, mauvaise action, crime, une « pratique » c.à.d. une tromperie)</li>\n</ol>\n</li>\n<li>une chose qui doit être faite, une affaire</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρᾶξις, </b><b>εως (ἡ) :<br>   I</b> action, <i>càd. :</i><br><b>      1</b> le fait d’agir, <i>p. opp. à</i> πάθος, PLAT. <i>Leg. 876</i> d ; <i>à</i> ἕξις, PLAT. <i>Rsp. 434</i> a ; <i>à</i> λόγος, DÉM. <i>66, 7 et 19, etc. ; distingué de</i> θεωρία, « examen », ποίησις « production », προαίρεσης « projet » ARSTT. <i>Nic. 6, 2 ;</i><br><b>      2</b> <i>p. suite,</i> action, acte, <i>en gén</i>. SOPH. <i>O.R. 895, O.C. 560, etc. ;</i> ISOCR. <i>259</i> a, <i>etc. ;</i><br><b>      3</b> mise en activité, action, exercice (d’un membre, d’un organe) PLAT. <i>Lach. 192</i> a ; <i>abs. en parl. de relations sexuelles,</i> ESCHN. <i>22, 35 ;</i> ARSTT. <i>H.A. 5, 2, 2, etc. ;</i><br><b>   II</b> <i>p. suite :</i><br><b>      1</b> exécution, accomplissement : πρ. ἔργου, PLAT. <i>Rsp. 370</i> b, accomplissement d’une œuvre ; τοῦ μισθοῦ, PLAT. <i>Prot. 328</i> b, règlement du salaire ; τελῶν, PLAT. <i>Rsp. 425</i> d, <i>etc</i>. règlement des impôts ; <i>cf</i>. DÉM. <i>607, 13 ; 915, 3, etc. ;</i> ARSTT. <i>Pol. 6, 8 ;</i><br><b>      2</b> entreprise, conduite d’une affaire (de guerre, de politique, <i>etc</i>.) ATT. ; <i>particul. au plur</i>. les affaires publiques : ἡ περὶ τὰς πράξεις ἐπιστήμη, DÉM. <i>1414, 4,</i> la science du gouvernement ; <i>d’où postér. au sg</i>. fonction, charge, HDN <i>5, 1, 2 ; 5, 2, 1, etc. ;</i><br><b>      3</b> <i>particul</i>. commerce, négoce : ἐπὶ πρῆξιν (<i>ion</i>.) πλεῖν, HH. <i>Ap. 397,</i> s’embarquer pour aller faire du commerce, <i>d’où</i> revendication, EUR. <i>I.A. 272 ;</i><br><b>      4</b> <i>en mauv. part :</i> intrigue, menée, POL. <i>2, 7, 8 ;</i> κατά τινος, POL. <i>4, 71, 6 ;</i> ἐπί τινα, POL. <i>5, 96, 4,</i> contre qqn ;<br><b>      5</b> lecture, conférence (d’un orateur) MARIN. <i>V. Procl. 22 ;</i><br><b>   III</b> manière d’agir <i>ou</i> manière d’être :<br><b>      1</b> manière d’agir, conduite, PLAT. <i>Conv. 206</i> b ; <i>d’où</i> expérience acquise, POL. <i>2, 47, 5 ; 4, 77, 7, etc. ;</i><br><b>      2</b> manière d’être, <i>d’où</i> état, situation ; <i>p. suite,</i> sort, fortune, destinée bonne <i>ou</i> mauvaise, PD. <i>O. 12, 11 ;</i> ESCHL. <i>Pr. 695 ;</i> SOPH. <i>Tr. 294, Ant. 790, 792 ;</i> τὴν ἑωυτοῦ πρῆξιν ἀπέκλαιε, HDT. <i>3, 65,</i> il déplorait sa destinée ; <i>au plur</i>. κακαὶ πράξεις, SOPH. <i>Ant. 1304,</i> destinée malheureuse ;<br><b>   IV</b> résultat d’une action, suite, conséquence : χρησμῶν, ESCHL. <i>Pers. 739,</i> accomplissement d’un oracle ; οὔ τις πρῆξις πέλεται γόοιο, IL. <i>24, 524,</i> il ne sert de rien de gémir ; οὔ τις πρῆξις ἐγίγνετο μυρομένοισιν, OD. <i>10, 202, 568,</i> il ne servait de rien de pleurer ; ἄνευ τούτων οὐκ ἂν εἴη πρᾶξις, XÉN. <i>Cyn. 2, 3,</i> sans cela il n’y aurait pas de résultat, ce serait chose inutile.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πρῆξις, HOM. HH. HDT. <i>ll. cc</i>.<br><span><b>Étym</b>. πράσσω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πραξις - πρᾶξις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4235":"<h1>praos</h1>\n<p>Strong n° 4235 <i>Prononciation [prah'-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>doux, gentil, aimable</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρᾷος</b> <i>ou</i> <b>πρᾶος</b>, <i>v</i>. . <i>adj. seul. sg. masc</i>. πρᾷος, PLAT. <i>Rsp. 375</i> c, <i>566</i> e, <i>Phædr. 243</i> c ; EUR. <i>Bacch. 436, etc., et neutre</i> πρᾷον, <i>etc., et pl. m. nom</i>. πρᾷοι, PLAT. <i>Rsp. 562</i> d ; <i>acc</i>. πρᾴους, ISOCR. <i>38</i> b, <i>et neutre</i> πρᾷα, ARSTT. <i>H.A. 1, 1, fin ; pour le fém. on emploie au sg. et au pl. la déclinaison</i> πραεῖα, <i>de</i> πραΰς (<i>v. ce mot) ; ttef. on rencontre, au sg., le nom. f</i>. πρᾷος, PLUT. <i>M. 168</i> d ; <i>en outre sont usités le cp</i>. πρᾳότερος, α, ον, XÉN. <i>Cyr. 2, 1, 29 ;</i> PLAT. <i>Leg. 867</i> b, <i>Crit. 49</i> b, <i>etc. ; et le</i> <i>• Sup</i>. πρᾳότατος, η, ον, XÉN. <i>Eq. 9, 3</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans les inscr. att</i>. πρᾶος (<i>non</i> πρᾷος) CIA. <i>2, 945, 20 (commenc. du 4<sup>e</sup> siècle av. J.C.) ; v. Meisterh. p. 50 ; § 21, 2</i>.<br><span><b>Étym</b>. <i>v</i>. πραΰς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πραος - πρᾶος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Matthieu (1)</li>\n</ul>\n</td></tr>\n</table>","G4236":"<h1>praotes</h1>\n<p>Strong n° 4236 <i>Prononciation [prah-ot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>gentillesse, douceur, amabilité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πραότης</b>, <i>v</i>. πρᾳότης.<br>\n<b>πρᾳότης</b> <i>ou</i> <b>πραότης, ητος (ἡ)</b> <span>[ᾱ]</span> douceur, bonté, facilité de caractère, ATT. ; <i>p. opp. à</i> χαλεπότης, LYS. <i>106, 15 ;</i> PLAT. <i>Rsp. 558</i> a, <i>etc. ; à</i> ἀγριότης, PLAT. <i>Conv. 197</i> d ; <i>à</i> ὀργιλότης, ARSTT. <i>Nic. 4, 5 ; Rhet. 2, 3, 1, etc. ; au plur</i>. ISOCR. <i>106</i> a.<br><span><b>Étym</b>. πρᾷος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πραοτης - πραότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 8 livres bibliques (NT)\n<ul>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (2)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4237":"<h1>prasia</h1>\n<p>Strong n° 4237 <i>Prononciation [pras-ee-ah']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une parcelle de terrain, un carré de jardin</li>\n<li>idiome Hébreu, qui indique ce qui est aligné par rangées ou divisions</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρασιά, </b><b>ᾶς (ἡ)</b> <span>[ᾰσ]</span> <i>propr</i>. planche de poireaux, <i>d’où :</i><br><b>      1</b> plate-bande de potager, <i>p. ext</i>. plate-bande (de légumes, de fleurs, <i>etc</i>.) OD. <i>7, 127 ; 24, 247 ;</i> LGS <i>4, 2 ;</i><br><b>      2</b> <i>fig</i>. division, section, groupe, NT. <i>Marc. 6, 40</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πρασιή, OD. <i>ll. cc</i>.<br><span><b>Étym</b>. πράσον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρασια - πρασιά</font>\n<br><br>vient peut-être de prason (un poireau, et aussi un rang d'oignons)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4238":"<h1>prasso</h1>\n<p>Strong n° 4238 <i>Prononciation [pras'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>exercer, pratiquer, être occupé à, commettre\n<ol type=\"a\">\n<li>entreprendre, faire</li>\n</ol>\n</li>\n<li>accomplir, exécuter\n<ol type=\"a\">\n<li>perpétrer</li>\n</ol>\n</li>\n<li>gérer des affaires publiques, affaire de transaction publique\n<ol type=\"a\">\n<li>prélever le tribut, le revenu, les dettes</li>\n</ol>\n</li>\n<li>agir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πράσσω</b>, <i>att. réc</i>. <b>πράττω</b> <span>(<i>f</i>. πράξω, <i>ao</i>. ἔπραξα, <i>pf.1</i> πέπραχα <span>[ᾱχ]</span>, <i>pf.2 intr</i>. πέπραγα <span>[ᾱγ]</span> ; <i>pass. f. 1</i> πραχθήσομαι, <i>f. 2</i> πραγήσομαι <span>[ᾱ]</span>, <i>ao.1</i> ἐπράχθην, <i>ao.2</i> ἐπράγην <span>[ᾱ]</span>, <i>pf</i>. πέπραγμαι)</span><br><b>   I</b> aller à travers, traverser, parcourir : ἅλα, OD. <i>9, 491,</i> la mer ; κέλευθον, IL. <i>14, 282 ; 23, 501 ;</i> OD. <i>13, 83 ;</i> ὁδόν, HH. <i>Merc. 203, etc</i>. parcourir un chemin, faire un trajet ; <i>avec le gén</i>. ὁδοῖο, IL. <i>24, 264 ;</i> OD. <i>3, 476 ; 15, 47 et 219,</i> aller à travers une route, faire un trajet ;<br><b>   II</b> <i>p. suite,</i> aller jusqu’au bout ; <i>d’où :</i><br><b>      1</b> achever, exécuter, accomplir, faire : τι, IL. <i>1, 562, etc. ;</i> OD. <i>2, 191, etc. ;</i> ATT. qqe ch. ; <i>p. opp. à</i> λέγειν, XÉN. <i>Cyr. 5, 1, 1, etc. ;</i> φόνον, PD. <i>N. 3, 81,</i> accomplir un meurtre ; ὕμνον, PD. <i>N. 9, 7,</i> accorder le don du chant ; ἀρετάς, PD. <i>I. 6, 15,</i> accomplir des actes de vertu, de bonnes actions ; <i>en mauv. part :</i> τὴν πρᾶξιν πρ. ESCHN. <i>11, 4 et 10,</i> faire la chose, <i>càd</i>. commettre une obscénité ; <i>au pass</i>. πέπρακται τοὔργον, ESCHL. <i>Pr. 75,</i> la chose est faite, l’œuvre est accomplie ; <i>en mauv. part :</i> φεῦ φεῦ πέπρακται, EUR. <i>Hipp. 680,</i> hélas ! hélas ! c’en est fait ; <i>abs</i>. τὰ πεπραγμένα, PD. <i>O. 2, 29 ;</i> ATT. (DÉM. <i>12, 19) etc. ;</i> τὰ πραχθέντα, ESCHL. <i>Pr. 683, etc. ;</i> τὸ πραχθέν, PLAT. <i>Prot. 324</i> b, ce qui a été fait, les actions, les actes ;<br><b>      2</b> agir, travailler, s’occuper de, négocier : τινί, THC. <i>4, 110 ;</i> πρός τινα, THC. <i>1, 131 ; 2, 5 ; 4, 73, etc. ;</i> ἔς τινα, THC. <i>1, 132 ;</i> ὑπέρ τινος, DÉM. <i>801, 8,</i> agir pour qqn, travailler en sa faveur ; μετά τινος, IS. <i>52, 3,</i> agir de concert avec qqn, dans l’intérêt de qqn ; πρ. φιλίαν, DÉM. <i>281, 19 ;</i> εἰρήνην, DÉM. <i>30, 16,</i> poursuivre des relations d’amitié, la paix, négocier en vue de relations d’amitié, de la paix ; περὶ εἰρήνης, XÉN. <i>Hell. 6, 3, 3,</i> traiter de la paix ; <i>ou avec un acc. :</i> τὰ ἑαυτοῦ πράσσειν, SOPH. <i>El. 678,</i> s’occuper de ses propres affaires ; τὰ πράγματα, LYS. <i>135, 19, ou</i> τὰ πολιτικά, PLAT. <i>Ap. 31</i> d ; τὰ τῆς πόλεως, PLAT. <i>Prot. 319</i> a, manier les affaires publiques ; τὰ τῶν Ἀθηναίων, PLAT. <i>Conv. 216</i> a, gérer les affaires d’Athènes ; τὰ αὑτοῦ, PLAT. <i>Phædr. 247</i> a, <i>Gorg. 526</i> c, <i>etc</i>. administrer ses propres affaires ; <i>en mauv. part :</i> τὰ αὑτῶν πρ. PLAT. <i>1 Alc. 127</i> b, s’occuper chacun de ses propres affaires, de ses propres intérêts ; <i>abs</i>. ἱκανὸς πράττειν, XÉN. <i>Mem. 1, 2, 15,</i> capable de manier les affaires publiques, d’être un homme d’État ; <i>joint à</i> πολιτεύεσθαι, DÉM. <i>240, 28 ;</i> ARSTT. <i>Pol. 7, 2, 6 ;</i> ἱκανὸς εἰπεῖν τε καὶ πρᾶξαι, XÉN. <i>Mem. 2, 9, 4,</i> capable de parler et d’agir, <i>càd</i>. de proposer et d’exécuter ; <i>en mauv. part :</i> πολλὰ πρ. <i>c</i>. πολυπραγμονεῖν, HDT. <i>5, 33,</i> être très remuant, s’occuper de beaucoup de choses dangereuses pour l’État ; <i>avec un double rég. :</i> τινί, SOPH. <i>Aj. 446,</i> machiner en faveur de qqn ; κάθοδόν τινι, PLUT. <i>Cic. 33,</i> travailler pour assurer le retour de qqn ; <i>avec double acc. :</i> τι πρ. τινά, EUR. <i>Hel. 1394 ;</i> AR. <i>Eccl. 108,</i> faire qqe ch. (du bien, <i>etc</i>.) à qqn ; <i>avec</i> ὅπῃ, THC. <i>1, 129, etc. ; avec</i> ὅπως, THC. <i>1, 56 et 57 ;</i> ὅτῳ τρόπῳ, THC. <i>4, 28 ;</i> ὥστε, ESCHL. <i>Eum. 896 ; avec une prop. inf</i>. DÉM. <i>888, 14 et 19,</i> agir de manière à, faire en sorte que, <i>etc. ;</i><br><b>      3</b> accomplir, achever, réaliser, mener à bien, OD. <i>19, 324 ;</i> κλέος, PD. <i>I. 5, 10,</i> acquérir de la gloire ; ἄκοιτιν, PD. <i>N. 5, 66,</i> obtenir une épouse, une compagne ; <i>abs</i>. δὸς Τηλέμαχον πρήξαντα νέεσθαι, OD. <i>3, 60,</i> fais que Télémaque revienne après avoir réussi dans son entreprise ; <i>avec un adv. ou un adj. adv</i>. réaliser de telle manière, aboutir à telle fin : ὁ στόλος οὕτω ἔπρηξεν, HDT. <i>3, 25,</i> l’expédition maritime se termina ainsi ; <i>cf</i>. HDT. <i>4, 77 ; 6, 44 ; 7, 18 ; 8, 129 ;</i> κατὰ τὴν ναυμαχίαν οὕτως ἐπεπράγεσαν, THC. <i>7, 24,</i> telle avait été l’issue du combat naval ; εὖ πράσσειν, PD. <i>O. 4, 7, etc. ;</i> ESCHL. <i>Sept. 77 ;</i> HDT. <i>1, 24, etc</i>. faire bien ses affaires, réussir, être heureux (<i>ne pas confondre avec</i> εὖ ποιεῖν, faire du bien ; <i>v</i>. ποιέω), <i>particul. dans les formules de lettres, avec une nuance d’ironie amicale :</i> εὖ πρᾶσσε, PLAT. <i>Ep. 315</i> b, bonne chance ! grand bien vous fasse ! (<i>d’ord</i>. χαῖρε) ; πρ. καλῶς, ESCHL. <i>Pr. 979, etc. ;</i> SOPH. <i>fr. 104 Nauck ;</i> EUR. <i>I.T. 668 ;</i> εὐτυχῶς, SOPH. <i>Ant. 701 ;</i> μακαρίως, AR. <i>Pl. 629 ;</i> εὐδαιμόνως, AR. <i>Pl. 802, m. sign. ;</i> ἀγαθόν, XÉN. <i>Cyr. 5, 1, 20,</i> être heureux ; πολλὰ καὶ ἀγαθά, XÉN. <i>An. 6, 4, 8 ; ou</i> τὰ ἄριστα, XÉN. <i>Cyr. 1, 6, 3,</i> être très heureux ; κακῶς, ESCHL. <i>Pr. 265, 981 ;</i> EUR. <i>Alc. 961 ;</i> AR. <i>Av. 605 ;</i> ANT. <i>2, 6, etc</i>. être malheureux ; φλαύρως, HDT. <i>6, 94 ;</i> δυστυχῆ, ESCHL. <i>Sept. 339, m. sign. ;</i> χαλεπώτατα, THC. <i>8, 95,</i> être dans une situation très difficile ; ἄτιμα, ESCHL. <i>Ag. 1443,</i> être dans une situation déshonorée ; ταπεινῶς, ISOCR. <i>95</i> a, être dans une situation humble ; μικρὰ καὶ φαῦλα, DÉM. <i>37, 11,</i> être dans une situation petite et misérable ; κάκιον, XÉN. <i>An. 1, 9, 10,</i> être dans une situation plus mauvaise ; χείρω, THC. <i>7, 71,</i> être dans une situation pire ; <i>avec double rég. :</i> οἱ τὰ γεωργικά, ἰατρικά, πολιτικὰ εὖ πράττοντες, XÉN. <i>Mem. 3, 9, 15,</i> ceux qui s’occupent avec succès d’agriculture, de médecine, de politique ;<br><b>      4</b> faire acquitter, faire payer : τὰς ἐσφοράς, DÉM. <i>617, 24,</i> les impôts ; <i>avec double rég. :</i> τινὰ τόκον, BATR. <i>186 ;</i> τινά τι, HDT. <i>3, 58 ;</i> XÉN. <i>An. 7, 6, 17,</i> faire payer à qqn des intérêts, qqe ch. (une somme d’argent, <i>etc</i>.) ; φόρον παρά τινος, HDT. <i>1, 106,</i> exiger de qqn le paiement d’impôts ; τινά τι ὑπέρ τινος, LUC. <i>V. auct. 18,</i> faire payer à qqn le prix de qqe ch. ; <i>abs</i>. faire payer (des intérêts, des impôts, <i>etc</i>.) PLAT. <i>Leg. 774</i> d : <i>au pass</i>. πράττεσθαι ὑπό τινος, LYS. <i>116, 5,</i> acquitter les contributions <i>ou</i> une amende sur l’ordre de qqn ; <i>abs</i>. τὰ πραττόμενα, POL. <i>1, 72, 2,</i> les impôts ; <i>fig</i>. πρ. τοὐφειλόμενον, ESCHL. <i>Ch. 310,</i> réclamer son dû, <i>en parl. de la justice ;</i> πατρὸς φόνον πρ. ESCHL. <i>Eum. 623,</i> poursuivre l’expiation du meurtre d’un père, le venger ; ἀντίποινα πρ. ESCHL. <i>Pers. 476,</i> prendre sa revanche ;<br><b>      5</b> <i>en mauv. part,</i> achever, <i>càd</i>. faire périr : τινά, ESCHL. <i>Ch. 440,</i> faire périr qqn ;<br><b><i>Moy</i>. πράσσομαι</b> <span>(<i>f</i>. πράξομαι, <i>ao</i>. ἐπραξάμην, <i>pf</i>. πέπραγμαι)</span><br><b>      1</b> faire pour soi, dans son intérêt (<i>seul. au part. pf. chez les Att</i>.) ὃ οὗτοι πεπραγμένοι εἰσὶ παρὰ ἡμᾶς, DÉM. <i>931, 27,</i> ce qu’ils ont fait avec nous, ce qu’ils ont accompli sur nous dans leur intérêt ;<br><b>      2</b> exiger, faire payer pour soi ; <i>avec double rég. :</i> τινὰ χρήματα, THC. <i>4, 65 ;</i> XÉN. <i>Mem. 1, 2, 5 ; 1, 6, 11, etc</i>. exiger de l’argent de qqn ; φόρους ἐκ τῶν πόλεων, THC. <i>8, 37 ; ou</i> ἀπὸ τῶν πόλεων, THC. <i>8, 5,</i> exiger de l’argent des villes ; παρά τινος, LYS. <i>17, 3,</i> exiger de l’argent de qqn ; <i>fig</i>. τινὰ τὴν δίκην πρ. DÉM. <i>845, 4, litt</i>. recouvrer la punition due par qqn, <i>càd</i>. faire punir qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Att</i>. πράττω, <i>ttef. chez les Trag. touj</i>. πράσσω. <i>Act. prés. ind. 1 pl. dor</i>. πράσσομες, THCR. <i>Idyl. 14, 3 ; 3 pl. dor</i>. πράσσοντι, PD. <i>O. 3, 7. Ao. part. dor</i>. πράξαις, PD. <i>O. 8, 73. Fut. moy. au sens pass. 3 sg</i>. πράξεται, PLAT. <i>Rsp. 452</i> a (<i>var</i>. πεπράξ-). <i>Ion</i>. πρήσσω <span>(<i>impf</i>. ἔπρησσον, <i>f</i>. πρήξω, <i>ao</i>. ἔπρηξα, <i>pf</i>. πέπρηχα, <i>pf.2</i> πέπρηγα ; <i>pass. ao</i>. ἐπρήχθην, <i>pf</i>. πέπρηγμαι)</span> IL. <i>11, 552, etc. ;</i> OD. <i>13, 83, etc. ;</i> HDT. <i>ll. cc. Formes poét. prés. sbj. 3 sg. épq</i>. πρήσσῃσι, OD. <i>3, 476 ; impf. iter</i>. πρήσσεσκον, OD. <i>8, 259</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *per(h₂)-, aller à travers, traverser ; <i>cf</i>. πέρα², πείρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρασσω - πράσσω</font>\n<br><br>un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Synonymes</big></td></tr>\n<tr><td> – dénote « faire »,  – « pratiquer » ;  pour désigner une performance,  une réalisation sérieuse, habituelle ;\n<br><br> indique simplement une action productive,  une action dirigée et définie; poieo 4160 s'attache au résultat de l'action,  à la portée et au caractère du résultat.</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n38 fois dans 36 versets de 10 livres bibliques (NT)\n<ul>\n<li>Luc (6)</li>\n<li>Jean (2)</li>\n<li>Actes (13)</li>\n<li>Romains (10)</li>\n<li>1 Corinthiens (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Philippiens (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4239":"<h1>praus</h1>\n<p>Strong n° 4239 <i>Prononciation [prah-ooce']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>douceur de disposition, gentillesse d'esprit, douceur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πραΰς, </b><b>πραεῖα, πραΰ</b>, <i>gén</i>. <b>πραέος, είας, έος</b>, <i>etc. ; pl</i>. πραεῖς, εῖαι, έα, <i>gén</i>. πραέων, <i>dat</i>. πραέσι, <i>acc</i>. πραεῖς, είας, έα :<br><b>      1</b> <i>intr</i>. doux, <i>en parl. de pers</i>. doux, bon, facile, PD. <i>P. 4, 243 ;</i> HDT. <i>2, 181 ;</i> PLAT. <i>Phædr. 243</i> c ; CALL. <i>fr. 131, 1 ; en parl. des dieux,</i> ANTH. <i>6, 271, etc. ;</i> πρ. τινι, PD. <i>P. 3, 125 ;</i> PLAT. <i>Rsp. 354</i> a ; πρός τινα, PLAT. <i>Rsp. 375</i> c, <i>etc</i>. doux à l’égard de qqn ; <i>en parl. d’animaux,</i> doux : τινι, EUR. <i>Bacch. 436 ;</i> πρός τινα, XÉN. <i>Œc. 15, 9,</i> à l’égard de qqn ; <i>abs</i>. apprivoisé, XÉN. <i>An. 1, 4, 9 ;</i> PLAT. <i>Rsp. 493</i> b ; ARSTT. <i>H.A. 1, 1, etc. ; en parl. de choses,</i> doux, indulgent, bénin, HH. <i>7, 10 ;</i> PLAT. <i>Leg. 867</i> b, <i>etc. ;</i> τὰ πραέα, XÉN. <i>Eq. 9, 10,</i> paroles douces, caresses ;<br><b>      2</b> <i>tr</i>. doux, calmant, PD. <i>O. 13, 121</i>.<br><span>•<i> Sup</i>. πραΰτατος, NYSS. <i>3, 421 Migne</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. πρηΰς, HDT. <i>l. c. etc</i>.<br><span><b>Étym</b>. <i>inconnue ; cf</i>. πρᾷος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πραυς - πραΰς</font>\n<br><br>apparemment un mot primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4240":"<h1>prautes</h1>\n<p>Strong n° 4240 <i>Prononciation [prah-oo'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>douceur de disposition, gentillesse de l'esprit, douceur</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πραΰτης, </b><b>ητος (ἡ)</b> <span>[ᾱῠ]</span> <i>c</i>. , SPT. <i>Ps. 44, 5 ; 89, 10 ; Sir. 3, 17, etc. ;</i> NT. <i>Gal. 5, 23, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πραυτης - πραΰτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Jacques (2)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4241":"<h1>prepo</h1>\n<p>Strong n° 4241 <i>Prononciation [prep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se tenir en dehors, être en évidence, être éminent</li>\n<li>être seyant, bienséant, convenable</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρέπω</b> (<i>d’ord. seul. prés. et impf., rar. fut</i>. πρέψω <i>et ao</i>. ἔπρεψα, <i>pf. inus</i>.) :<br><b>   I</b> se faire remarquer, se distinguer : διὰ πάντων, IL. <i>12, 104,</i> entre tous ; <i>ou avec</i> μετά <i>et un dat. plur</i>. OD. <i>8, 172 ;</i> HÉS. <i>Th. 92 ;</i> πρ. τινί (<i>particul. chez les Trag. :</i> ἐσθῆτι καὶ κόσμῳ, EUR. <i>Alc. 1050) ; cf</i>. EUR. <i>Alc. 512, etc</i>. se distinguer par qqe ch. (<i>surt. en parl. de vêtements :</i> par ses vêtements et sa parure, <i>etc.) ; en parl. d’un objet brillant, d’une lumière, etc</i>. être apparent, sensible <i>ou</i> visible, éclater, PD. <i>P. 10, 106 ;</i> ESCHL. <i>Sept. 372, Pers. 239 ; fig</i>. ἐπί τοι πρέπει ὄμμασιν αἰδώς, HH. <i>Cer. 214,</i> la pudeur se montre dans ton regard ; <i>p. anal. en parl. d’un cri,</i> PD. <i>N. 3, 110 ;</i> ESCHL. <i>Ag. 321 ; d’une odeur âcre et pénétrante,</i> ESCHL. <i>Ag. 1311 ;</i><br><b>   II</b> annoncer par son extérieur, avoir l’air de, <i>avec un inf. :</i> τοῦδε γὰρ δράμημα φωτὸς Περσικὸν πρέπει μαθεῖν, ESCHL. <i>Pers. 247,</i> car cet homme qui accourt m’a bien l’air, autant qu’on en peut juger, d’un Perse ; <i>ou avec</i> ὡς <i>et l’inf. :</i> πρέπει ὡς τύραννος εἰσορᾶν, SOPH. <i>El. 664,</i> elle a bien l’air d’une reine ; <i>avec</i> ὥστε, EUR. <i>Bacch. 118 ; avec un part. :</i> ὁ φρυκτὸς ἀγγέλλων πρέπει, ESCHL. <i>Ag. 30,</i> le feu de broussailles annonce clairement, <i>etc. ; avec double rég. :</i> πρ. τινὶ εἶδος, PD. <i>P. 2, 70, ou</i> τινὶ μορφῇ, EUR. <i>Bacch. 917,</i> ressembler par les traits à qqn ; πρ. ταύρῳ δέμας, ESCHL. <i>Suppl. 301,</i> ressembler par le corps à un taureau ;<br><b>   III</b> <i>p. suite,</i> avoir quelque rapport avec, convenir à :<br><b>      1</b> <i>avec un suj. de chose, avec le dat. :</i> θνατὰ θνατοῖσι πρέπει, PD. <i>I. 5, 18,</i> ce qui est mortel convient à des mortels ; τὸ σοφὸν μόνῳ θεῷ πρέπει, PLAT. <i>Phædr. 278</i> d, la sagesse convient à la divinité seule ;<br><b>      2</b> <i>rar. avec un suj. de pers</i>. πρέπων ἔφυς πρὸ τῶνδε φωνεῖν, SOPH. <i>O.R. 9,</i> il convient que tu parles plutôt que ceux-ci ; ἀνδρὸς φίλου μᾶλλον ἢ πολεμίου εἶναι πρέποντος, PLUT. <i>Popl. 17,</i> homme plus digne d’être ami qu’ennemi ; Πομπήϊος πάνυ τοῖς ἔπεσι πρέπων, PLUT. <i>Pomp. 72,</i> Pompée auquel les vers étaient tout à fait appropriés ; <i>avec</i> ἐν <i>et le dat</i>. EUR. <i>Her. 511 ; avec</i> εἰς <i>et l’acc</i>. XÉN. <i>Cyr. 2, 1, 24 ;</i> ANTH. <i>6, 260 ; avec un part</i>. ὅ τι γιγνόμενον ἂν πρέποι, PLAT. <i>Epin. 976</i> c, ce qu’il conviendrait qu’il arrivât ; <i>part</i>. πρέπων, ουσα, ον, qui convient à, approprié à, <i>avec le dat</i>. PLAT. <i>Rsp. 460</i> a ; ISOCR. <i>212</i> d, <i>etc. ; par périphr</i>. πρέπον εἶναι, convenir, <i>c</i>. πρέπειν : <i>joint à</i> ἁρμόττειν, PLAT. <i>Gorg. 503</i> e ; <i>rar. avec le gén. :</i> πρέπον γέ τἂν ἦν δαίμονος τοὐμοῦ τόδε, SOPH. <i>Aj. 534,</i> c’eût été digne du dieu qui m’inspire ; <i>abs</i>. τὸ πρέπον, ce qui convient, la bienséance (<i>lat</i>. decorum) PLAT. <i>Hipp. ma. 294</i> a ; κατὰ τὸ πρέπον, PLAT. <i>Leg. 828</i> d, comme il convient ;<br><b>      3</b> <i>impers</i>. πρέπει, il convient ; <i>abs</i>. PLAT. <i>Soph. 229</i> c ; <i>avec un dat</i>. XÉN. <i>Hell. 4, 1, 37 ; avec l’inf. :</i> οὐ κλαίειν πρέπει, ESCHL. <i>Sept. 656,</i> il ne convient pas de pleurer ; <i>avec une prop. inf</i>. PD. <i>O. 2, 83 ;</i> ESCHL. <i>Suppl. 203 ;</i> SOPH. <i>Tr. 728 ;</i> THC. <i>1, 86, etc. ; avec attraction :</i> ἐμοὶ πρέποι ἂν ἐπιμελομένῳ (<i>p</i>. ἐπιμέλεσθαι) XÉN. <i>Œc. 4, 1,</i> il me conviendrait de m’occuper de, <i>etc. ; avec un inf. s.-e. :</i> τίσασθαι οὕτω ὡς ἐκείνους (<i>s.-e</i>. τίσασθαι) πρέπει, HDT. <i>4, 139,</i> les punir comme il convient ; <i>cf</i>. HDT. <i>8, 68 ;</i> ESCHL. <i>Suppl. 195 ;</i> PLAT. <i>Prot. 312</i> b, <i>etc</i>.<br><span><b>Étym</b>. <i>R. indo-europ</i>. *prep-, apparaître distinctement ; <i>ou</i> *k<sup>w</sup>rep-, corps, forme ; <i>cf</i>. πραπίς, <i>lat</i>. corpus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρεπω - πρέπω</font>\n<br><br>apparemment un mot racine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n7 fois dans 7 versets de 6 livres bibliques (NT\n<ul>\n<li>Matthieu (1)</li>\n<li>1 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n<li>1 Timothée (1)</li>\n<li>Tite (1)</li>\n<li>Hébreux (2)</li>\n</ul>\n</td></tr>\n</table>","G4242":"<h1>presbeia</h1>\n<p>Strong n° 4242 <i>Prononciation [pres-bi'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>âge, dignité, droit du premier né</li>\n<li>affaire normalement impartie aux anciens, spéc. la fonction d'un ambassadeur, une ambassade</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρεσϐεία, </b><b>ας (ἡ) :<br>   I</b> (πρεσϐεύω, être âgé) :<br><b>      1</b> ancienneté, droit d’ancienneté <i>ou</i> d’aînesse, <i>seul. dans</i> ARSTT. <i>Pol. 1, 12, 3 ;</i><br><b>      2</b> <i>p. suite,</i> dignité, rang élevé, PLAT. <i>Rsp. 509</i> b ;<br><b>   II</b> (πρεσϐεύω, être ambassadeur) :<br><b>      1</b> députation, ambassade, THC. <i>4, 118 ;</i> PLAT. <i>Rsp. 422</i> d, <i>etc. ;</i><br><b>      2</b> les députés <i>ou</i> ambassadeurs, la légation, THC. <i>1, 72 ;</i> XÉN. <i>Cyr. 2, 4, 2 ;</i> AR. <i>Ach. 647, etc</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dans une inscr. att</i>. πρεσϐήα, CIA. <i>2, 488, d, 21 (envir. 30 av. J.C.) ; v. Meisterh. p. 37, 20</i>.<br><span><b>Étym</b>. πρεσϐεύω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρεσβεια - πρεσβεία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Luc (2)</li>\n</ul>\n</td></tr>\n</table>","G4243":"<h1>presbeuo</h1>\n<p>Strong n° 4243 <i>Prononciation [pres-byoo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>être plus vieux, antérieur par la naissance ou en âge</li>\n<li>être un ambassadeur, agir comme un ambassadeur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρεσϐεύω</b> <span>(<i>ao</i>. ἐπρέσϐευσα, <i>pf</i>. πεπρέσϐευκα, <i>pf. pass</i>. πεπρέσϐευμαι)</span><br><b>A</b> (πρέσϐυς, vieillard) :<br><b>   I <i>intr</i>.<br>      1</b> être très âgé <i>ou</i> le plus âgé, SOPH. <i>O.C. 1422 ;</i> PLAT. <i>Leg. 951</i> e, <i>etc. ;</i> τινός, HDT. <i>7, 2,</i> être plus âgé que qqn ; ἀπό τινος, THC. <i>6, 55,</i> être le fils aîné de qqn ; <i>en parl. de choses</i> (légendes, ATH. <i>19</i> a ; vin, ARCHESTR. <i>dans</i> ATH. <i>29</i> c, <i>etc</i>.) ;<br><b>      2</b> <i>p. suite,</i> être plus respectable, être supérieur par le rang <i>ou</i> le mérite, SOPH. <i>Ant. 720 ;</i> τινός, PLAT. <i>Leg. 752</i> e, être supérieur à qqn <i>ou</i> à qqe ch. ; <i>d’où</i> être le maître de, dominer sur, <i>gén</i>. SOPH. <i>Aj. 1369 ; abs</i>. être dominant, s’accréditer, <i>en parl. d’un bruit,</i> ARR. <i>An. 4, 13, 2 ;</i><br><b>   II <i>tr</i>.<br>      1</b> respecter comme le plus âgé, <i>d’où en gén</i>. respecter, vénérer, <i>acc</i>. ESCHL. <i>Eum. 1, etc. ;</i> SOPH. <i>Tr. 1067 ;</i> PLAT. <i>Conv. 186</i> b, <i>etc. ; joint à</i> τιμᾶν, PLAT. <i>Crit. 46</i> b ; πρ. τι πρό τινος, PLUT. <i>Luc. 3,</i> estimer une chose plus qu’une autre, préférer une chose à une autre ; <i>au pass</i>. être considéré, occuper la première place, ESCHL. <i>Ag. 1300, Eum. 21, etc. ;</i> PLUT. <i>M. 228</i> c ; <i>avec le gén</i>. être préféré à, PLAT. <i>Leg. 879</i> b ;<br><b>      2</b> <i>p. suite,</i> prendre soin de, s’occuper avec sollicitude de, <i>acc</i>. DL. <i>1, 18 ;</i> SYN. <i>35</i> b ; PHILSTR. <i>484 ;</i><br><b>B</b> (πρέσϐυς, envoyé) :<br><b>      1 <i>intr.</i></b> être ambassadeur <i>ou</i> député, AR. <i>Ach. 610 ;</i> ἀπὸ Κορίνθου, HDT. <i>5, 93,</i> être envoyé de Corinthe ; τινός, EUR. <i>Her. 479,</i> pour qqn ; πρός τινα, XÉN. <i>Cyr. 5, 1, 3 ; ou</i> παρά τινα, PLAT. <i>Charm. 158</i> a, auprès de qqn ; εἰς τόπον, AND. <i>34, 25,</i> dans un lieu ; πρεσϐείαν πρ. DIN. <i>92, 11,</i> être chargé d’une ambassade ;<br><b>      2 <i>tr.</i></b> traiter en qualité d’ambassadeur, négocier comme député, <i>acc</i>. DÉM. <i>400, 12 et 14, etc. ;</i> τὴν εἰρήνην, AND. <i>26, 21 ;</i> DÉM. <i>382, 17, etc</i>. la paix ; τὰ πεπρεσϐευμένα, DÉM. <i>347, 5 et 16,</i> les affaires traitées dans une ambassade, les négociations ;<br><b><i>Moy.</i></b> :<br><b>      1</b> être député <i>ou</i> ambassadeur, THC. <i>5, 39 ; 8, 89 ;</i><br><b>      2</b> envoyer une ambassade, THC. <i>1, 67 ;</i> AR. <i>Ach. 62 ;</i> PLAT. <i>Leg. 698</i> d ; DÉM. <i>16, 6, etc. ;</i> παρά τινα, THC. <i>1, 91 ;</i> πρός τινα, THC. <i>1, 126,</i> vers qqn ; ἐς πόλιν, <i>etc</i>. THC. <i>1, 92 ; 2, 7, etc</i>. dans une ville, <i>etc</i>.<br><span><b>Étym</b>. πρέσϐυς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρεσβευω - πρεσβεύω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4244":"<h1>presbuterion</h1>\n<p>Strong n° 4244 <i>Prononciation [pres-boo-ter'-ee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>corps des anciens, « presbytère », sénat, conseil\n<ol>\n<li>Anciens chez les Juifs</li>\n<li>les anciens de tout corps (assemblée) de Chrétiens</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρεσϐυτέριον, </b><b>ου (τὸ)</b> <span>[ῠ]</span> le conseil des Anciens, NT. <i>Luc. 22, 66 ; Ap. 22, 5 ; 1Tim. 4, 14</i>.<br><span><b>Étym</b>. πρεσϐύτερος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρεσβυτεριον - πρεσβυτέριον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4245":"<h1>presbuteros</h1>\n<p>Strong n° 4245 <i>Prononciation [pres-boo'-ter-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>ancien, ayant de l'âge\n<ol type=\"a\">\n<li>le plus ancien de deux peuples</li>\n<li>avancé dans la vie, un aîné, un senior\n<ol>\n<li>les ancêtres</li>\n</ol>\n</li>\n</ol>\n</li>\n<li>un terme de rang ou de fonction\n<ol type=\"a\">\n<li>parmi les Juifs\n<ol>\n<li>membres du grand conseil ou Sanhédrin (car dans les premiers temps les dirigeants du peuple, juges, etc. étaient sélectionnés parmi les hommes les plus anciens)</li>\n<li>de ceux qui géraient les affaires publiques et administraient la justice dans les villes séparées</li>\n</ol>\n</li>\n<li>parmi les Chrétiens, ceux qui présidaient sur les assemblées (ou églises) le N.T utilisant le terme évêques, anciens, et presbytère indifféremment</li>\n<li>les vingt quatre membres du Sanhédrin céleste assis sur des trônes autour du trône de Dieu</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρεσϐύτερος</b>, <i>v</i>. πρέσϐυς.<br>\n<b>πρέσϐυς<br></b><b>   I</b> <i>adj. :</i><br><b>      1</b> vieux, âgé, ancien, AR. <i>Av. 255 ; joint à un subst</i>. SOPH. <i>Ph. 665 ; O.R. 941 ; au voc</i>. ô vieillard, SOPH. <i>O.R. 1013, 1121, etc. ;</i> ἐν βουλαῖς πρέσϐυς, PD. <i>P. 4, 502,</i> vieux dans le conseil, <i>càd</i>. expérimenté ; <i>au plur</i>. οἱ πρέσϐεις, les anciens, <i>d’où</i> les chefs, HÉS. <i>Sc. 245 ;</i> ESCHL. <i>Pers. 840 ;</i> SOPH. <i>O.R. 1111 ; cp</i>. πρεσϐύτερος, le plus âgé des deux, IL. <i>11, 787 ; 15, 204 ; p. opp. à</i> νεώτερος, PLAT. <i>Rsp. 380</i> c, <i>etc. ;</i> οἱ πρεσϐύτεροι, les Anciens du peuple <i>chez les Juifs,</i> NT. <i>Matth. 16, 21, etc. ; ou</i> les premiers chrétiens, NT. <i>1Tim. 5, 19, etc. ; Ap. 11, 30, etc. ; postér</i>. les prêtres, ECCL. ; <i>en parl. d’animaux,</i> ARSTT. <i>H.A. 5, 14, 19, etc. ; en parl. de choses</i> (arbre, TH. <i>C.P. 5, 13, 8 ;</i> avis, PD. <i>P. 2, 122 ;</i> prudence, DH. <i>5, 30, etc.) ; sup</i>. πρεσϐύτατος, IL. <i>4, 59 ; 6, 24 ; 11, 740, etc. ;</i> HÉS. <i>Th. 234, etc</i>. très âgé ;<br><b>      2</b> <i>p. suite,</i> expérimenté, PD. <i>P. 4, 503 ;</i><br><b>      3</b> <i>p. ext</i>. digne de respect, respectable, vénérable, précieux, cher, considérable (<i>cf. lat</i>. nihil antiquius habere, <i>etc</i>.) : πρεσϐύτατον κρίνειν τι, THC. <i>4, 61,</i> juger qqe ch. comme très important ; ἐμοὶ οὐδέν ἐστι πρεσϐύτερον, PLAT. <i>Conv. 218</i> d, rien n’est plus important pour moi ; τὰ τοῦ θεοῦ πρεσϐύτερα ποιεῖσθαι ἢ τὰ τῶν ἀνδρῶν, HDT. <i>5, 63,</i> mettre les choses divines au-dessus des choses humaines ; πρεσϐύτερον κακόν, SOPH. <i>O.R. 1365,</i> mal plus considérable, plus grave ;<br><b>   II</b> <i>subst. :</i><br><b>      1</b> envoyé, député, ambassadeur, <i>en ce sens seul. nom. sg</i>. ESCHL. <i>Suppl. 708 dout. ;</i> POÈT. (SCH.-IL. <i>4, 394) ; gén</i>. πρέσϐεως, AR. <i>Ach. 93 ; pl</i>. πρέσϐεις, THC. <i>4, 118 (traité</i>) ; XÉN. <i>Hell. 4, 8, 13 ;</i> AR. <i>Ach. 61 ;</i> AND. <i>28, 37, etc. ; gén</i>. πρέσϐεων, AR. <i>Ach. 76 ; dat</i>. πρέσϐεσι, AR. <i>Ach. 62 ;</i><br><b>      2</b> roitelet, <i>oiseau,</i> ARSTT. <i>H.A. 9, 11, 5</i>.<br><span>•<i> Cp</i>. πρεσϐύτερος <span>[ῠ]</span> IL. <i>11, 787, etc. ;</i> PD. <i>P. 2, 122 ;</i> HDT. <i>5, 63 ;</i> PLAT. <i>Conv. 218</i> d, <i>etc.</i> <i>• Sup</i>. πρεσϐύτατος <span>[ῠ]</span> IL. <i>4, 59, etc. ;</i> HÉS. <i>Th. 234, etc. ;</i> THC. <i>4, 61 ;</i> PLAT. <i>Leg. 717</i> d, <i>etc. ; sup. poét</i>. πρέσϐιστος, HH. <i>30, 2 ;</i> ESCHL. <i>Sept. 390 ;</i> SOPH. <i>fr. 523, 539, etc. ; dor. fém</i>. πρεσϐίστα, T. LOCR. <i>104</i> b ; <i>d’où</i> <i>• Sup</i>. πρεσϐίστατος, NIC. <i>Th. 344</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Us. seul. aux formes suiv. : sg. nom</i>. πρέσϐυς, SOPH. <i>O.R. 941, Ph. 562, etc. ; voc</i>. -υ, SOPH. <i>O.R. 1013, 1121 ;</i> EUR. <i>Or. 476 ;</i> AR. <i>Th. 146, etc. ; acc</i>. -υν, SOPH. <i>Ph. 665 ; pl. nom</i>. -εις, ESCHL. <i>Pers. 840 ; épq</i>. -ηες, HÉS. <i>Sc. 245 ; duel</i> -η <i>ou mieux</i> -ῆ, AR. <i>fr. 495 ; Dans les inscr. att. au sens de</i> « envoyé », <i>on trouve le plur</i>. πρέσϐεις <i>jusqu’en 250 av. J.C. ; à partir de cette date,</i> πρεσϐευταί ; <i>v. Meisterh. p. 112, 9</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *pres-g<sup>w</sup>eu-, *preis-g<sup>w</sup>eu- « qui va en tête » ; <i>pour</i> *pres- <i>cf</i>. πρός ; *g<sup>w</sup>eu- <i>p.-ê. var. de</i> *g<sup>w</sup>em-, aller, <i>cf</i>. βαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρεσβυτερος - πρεσβύτερος</font>\n<br><br>comparatif de presbus (plus âgé)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n66 fois dans 66 versets de 13 livres bibliques (NT)\n<ul>\n<li>Matthieu (12)</li>\n<li>Marc (7)</li>\n<li>Luc (5)</li>\n<li>Jean (1)</li>\n<li>Actes (18)</li>\n<li>1 Timothée (4)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (1)</li>\n<li>1 Pierre (2)</li>\n<li>2 Jean (1)</li>\n<li>3 Jean (1)</li>\n<li>Apocalypse (12)</li>\n</ul>\n</td></tr>\n</table>","G4246":"<h1>presbutes</h1>\n<p>Strong n° 4246 <i>Prononciation [pres-boo'-tace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un vieil homme, un vieillard, un homme âgé</li>\n<li>un ambassadeur</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρεσϐύτης, </b><b>ου</b> <span>[ῡ]</span><br><b>      1</b> <i>adj. m</i>. ancien, vieux, ESCHL. <i>Eum. 964, etc. ;</i> EUR. <i>Ph. 847, etc. ;</i> ὁ π. vieillard, AR. <i>Ach. 707, etc. ;</i> PLAT. <i>Rsp. 608</i> c, <i>etc. ; en parl. d’animaux,</i> vieux, ARSTT. <i>H.A. 9, 44, 6 ;</i><br><b>      2</b> presbyte, <i>dont la vue porte loin, comme souvent chez les vieillards,</i> ARSTT. <i>Probl. 31, 25, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῠ]</span> ANTH. <i>1, 46</i>.<br><span><b>Étym</b>. πρέσϐυς.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρεσβυτης - πρεσβύτης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Tite (1)</li>\n<li>Philémon (1)</li>\n</ul>\n</td></tr>\n</table>","G4247":"<h1>presbutis</h1>\n<p>Strong n° 4247 <i>Prononciation [pres-boo'-tis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>une femme âgée, vieille femme</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρεσϐῦτις, </b><b>ιδος (ἡ)</b> <span>[ῡῐδ]</span> femme âgée, ESCHL. <i>Eum. 731, 1027 ;</i> EUR. <i>Hec. 842 ;</i> PLAT. <i>Hipp. ma. 286</i> a ; ESCHN. <i>76, 4 ; joint à</i> ἄνθρωπος, LYS. <i>93, 7</i>.<br><span><b>Étym</b>. <i>fém. de</i> πρεσϐύτης.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρεσβυτις - πρεσβῦτις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Tite (1)</li>\n</ul>\n</td></tr>\n</table>","G4248":"<h1>prenes</h1>\n<p>Strong n° 4248 <i>Prononciation [pray-nace']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>la tête la première, précipitamment, précipité</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρηνής</b>, <i>att</i>. <b>πρανής, ής, ές</b> <span>[ᾱ]</span> qui penche en avant ; <i>en parl. de pers</i>. penché, incliné, qui penche <i>ou</i> tombe la tête en avant, IL. <i>6, 43 ; 16, 413 ; 21, 118 :</i> HÉS. <i>Sc. 365 ; p. opp. à</i> ὕπτιος, IL. <i>11, 179 ;</i> κατὰ πρηνὲς βαλέειν, IL. <i>2, 414,</i> précipiter, renverser (une maison) ; ἐπὶ τὸ πρηνὲς ῥέπειν, HPC. <i>750</i> b, glisser en avant ; <i>en parl. d’animaux :</i> τὰ πρηνῆ, ARSTT. <i>P.A. 2, 14, 2, etc</i>. la partie antérieure du corps ; <i>en parl. de choses (colline, hauteur, etc</i>.) qui va en pente, incliné, XÉN. <i>An. 1, 5, 8, etc. ; p. opp. à</i> ὄρθιος, XÉN. <i>Cyr. 2, 2, 24 ;</i> τὸ πρανές, XÉN. <i>Eq. 3, 7 ;</i> τὰ πρανῆ, XÉN. <i>Eq. 8, 6,</i> pente, inclinaison.<br><span><b>Étym</b>. πρό ; <i>cf. lat</i>. prōnus.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πρηνης - πρηνής</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4249":"<h1>prizo</h1>\n<p>Strong n° 4249 <i>Prononciation [prid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>scier, couper en deux avec une scie</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρίζω</b> <span>(<i>f. moy. 3 sg</i>. πριεῖται)</span> <i>c</i>. πρίω, PLAT. <i>Theag. 124</i> a ; PLUT. <i>M. 1099</i> c.<br>\n<b>πρίω</b><br>\n➀ <span>(<i>impér</i>. πρῖε, <i>f</i>. πρίσω, <i>ao</i>. ἔπρισα <span>[ῑ]</span>, <i>pf</i>. πέπρικα <i>en compos. ; pass. ao</i>. ἐπρίσθην, <i>pf</i>. πέπρισμαι)</span> <span>[ῑ]</span><br><b>   I</b> scier, THC. <i>4, 100 ;</i> LUC. <i>H. conscr. 51 ; au pass</i>. PLUT. <i>M. 953</i> b, <i>etc. ; particul</i>. trépaner, HPC. <i>V.C. 904 ;</i><br><b>   II</b> <i>p. ext. :</i><br><b>      1</b> frotter comme pour scier, faire grincer : ὀδόντας, HPC. <i>Progn. 37 ;</i> τοὺς ὀδόντας, AR. <i>Ran. 927, ou</i> σιαγόνας, BABR. <i>96, 3,</i> les dents, les mâchoires ; <i>fig. :</i> χόλον ἐπί τινι, A. RH. <i>4, 1671,</i> grincer les dents de colère contre qqn ;<br><b>      2</b> mordre, SOPH. <i>fr. 777 ;</i> OPP. <i>H. 2, 575 ;</i><br><b>      3</b> serrer comme pour scier, <i>d’où</i> serrer fortement, serrer, fixer, SOPH. <i>Aj. 1030 ;</i><br><b><i>Moy.</i></b> grincer des dents, <i>d’où :</i><br><b>      1</b> s’irriter, se dépiter : τινι, ANTH. <i>9, 77,</i> de qqe ch. ;<br><b>      2</b> se tourmenter : μὴ πρίου, BABR. <i>28, 8,</i> ne te tourmente pas, ne te fais pas tant de souci.<br><span><b><span class=\"arrow\"></span></b> <i>Ao</i>. <span>[ῐ]</span> ANTH. <i>11, 14</i>.</span><br><br>\n➁ <b>πρίω</b>, <i>contr. p</i>. πρίασο, <i>impér. de</i> πρίαμαι, <i>ou poét. c</i>. ἐπρίασο, <i>2 sg. impf. du même</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πριζω - πρίζω</font>\n<br><br>forme renforcée d'un mot primaire : prio (scier)</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4250":"<h1>prin</h1>\n<p>Strong n° 4250 <i>Prononciation [prin]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>avant, auparavant, jadis</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρίν</b> <span>[ῐ HOM. ; ῑ̆ ATT.]</span> <i>particule invar. : adv., prép. et conj. :</i><br><b>   I</b> <i>adv</i>., auparavant, avant, IL. <i>2, 112 ; 7, 144, etc. ;</i> OD. <i>4, 212, 724, 814, etc. ;</i> ESCHL. <i>Suppl. 398 ;</i> SOPH. <i>O.R. 259 ; en prose seul. entre l’art. et un subst. avec ou sans part. :</i> τὸ πρὶν γενόμενον τέρας, HDT. <i>8, 37,</i> le prodige arrivé précédemment ; ἐν τῷ πρὶν χρόνῳ, SOPH. <i>Ph. 1224,</i> antérieurement ; <i>abs</i>. τὸ πρίν, dans le temps passé, autrefois, IL. <i>5, 54 ; 6, 125, etc. ;</i> OD. <i>3, 265, etc. ;</i> HDT. <i>1, 129 ;</i> ESCHL. <i>Pr. 441 ;</i> PLAT. <i>Criti. 112</i> a, <i>etc. ; après une nég. :</i> τὴν δ' ἐγὼ οὐ λύσω πρίν μιν καὶ γῆρας ἔπεισιν, IL. <i>1, 29,</i> je ne la relâcherai pas avant que la vieillesse ne l’atteigne, <i>litt</i>. la vieillesse l’atteindra auparavant ; <i>au sens de</i> plutôt : πρὶν καὶ κακὸν ἄλλο πάθῃσθα, IL. <i>24, 551,</i> il pourrait plutôt t’arriver un autre malheur ; πρίν κεν ἀνιηθεὶς σὴν πατρίδα γαῖαν ἵκοιο, OD. <i>3, 117,</i> tu retournerais plutôt plein de dégoût dans ta patrie ;<br><b>   II</b> <i>prép. avec le gén</i>. avant : πρὶν ὥρας, PD. <i>P. 4, 76,</i> avant le temps ; πρὶν φάους, ARR. <i>An. 3, 18, 12,</i> avant le jour, <i>etc. ;</i><br><b>   III</b> <i>conj</i>. avant que, avant de ; <i>en ce sens construit :</i><br><b>      1</b> <i>soit seul avec les différents modes selon les nuances de la pensée</i> (affirmation, doute, subordination, <i>etc.), et dans ces différents cas avec ou sans</i> ἄν (<i>v. ci-dessous</i>) ;<br><b>      2</b> <i>soit avec une conj., d’ord</i>. ἤ : πρὶν ἤ, IL. <i>22, 266, etc. ;</i> HDT. <i>1, 19 ; 6, 45, etc. ; avec</i> ὅτε : πρίν γ' ὅτε, OD. <i>13, 322,</i> jusqu’à ce que ; <i>seul ou avec une conj., qqf. précédé d’un adv. de même signif. :</i> πρίν, πρόσθεν, πάρος, πρότερον, <i>etc. ;</i> πρὶν… πρίν, IL. <i>2, 348 ; 8, 452, etc. ;</i> OD. <i>19, 585, etc</i>. avant que ; οὐ πρὶν… πρίν, IL. <i>1, 97 ; 7, 481 ; 9, 650, etc. ;</i> OD. <i>19, 475, etc. ;</i> HDT. <i>1, 165, etc. ;</i> μὴ πρὶν… πρίν, IL. <i>2, 354, etc. ;</i> pas avant que, <i>etc. ;</i> τὸ πρὶν… πρὶν… γε, IL. <i>15, 72 ;</i> πρίν γε… πρίν γ' ἤ, IL. <i>5, 288, m. sign. ; de même :</i> οὐ πάρος… πρίν γε, IL. <i>5, 218 ;</i> OD. <i>2, 128 ; 18, 289 ;</i> οὐ πρόσθεν… πρίν, OD. <i>17, 7 ; 23, 138, etc. ;</i> μὴ πρόσθεν… πρίν, XÉN. <i>An. 1, 1, 10 ;</i> οὐ πρόσθεν… πρὶν ἤ, XÉN. <i>An. 3, 2, 29 ; Cyr. 1, 4, 23 ;</i> πρότερον… πρίν, XÉN. <i>Cyr. 5, 2, 9 ;</i> οὐ πρότερον… πρίν, HDT. <i>6, 45 ;</i> AR. <i>Eccl. 620 ;</i> PLAT. <i>Lach. 187</i> c ; οὐ πρότερον,… πρίν, XÉN. <i>An. 3, 1, 16, etc. ;</i> μὴ πρότερον… πρίν, SOPH. <i>Ph. 197 ;</i> PLAT. <i>Phæd. 62</i> c, <i>m. sign. ; rar</i>. πρὶν… τόφρα, IL. <i>21, 100, m. sign. ; — construit :</i><br><b>      1</b> <i>avec l’inf. d’ord. avec l’inf. ao</i>. πρὶν ἐλθεῖν υἷας Ἀχαιῶν, IL. <i>13, 172,</i> avant que les fils des Grecs ne fussent venus ; πρὶν πόλεμον ἰδέειν, IL. <i>8, 453,</i> avant d’avoir vu le combat ; <i>cf</i>. IL. <i>6, 81 ; 15, 588 ; 16, 322, etc. ;</i> OD. <i>1, 210 ; 4, 668 ; 5, 207, etc. ; de même en prose,</i> HDT. <i>2, 2 ; 4, 167 ; 8, 144, etc. ;</i> THC. <i>2, 12 ;</i> XÉN. <i>Cyr. 3, 3, 60, etc. ; particul. après une propos. négative :</i> οὐ λήξω, πρὶν Τρῶας ἄδην ἐλάσαι πολέμοιο, IL. <i>19, 423,</i> je ne cesserai pas avant d’avoir battu complètement les Troyens ; <i>cf</i>. IL. <i>1, 97 ; 7, 481 ; 9, 650, etc. ;</i> OD. <i>2, 128 ; 4, 823 ; 9, 148, etc. ; avec deux propos. consécut. l’une à l’inf. l’autre au sbj. avec</i> κέ : οὐ γὰρ ἔγωγε Ἕκτορα σχήσεσθαι ὀΐω, πρίν γ' ἐπ' Ἀχιλλῆος καλλίτριχε βήμεναι ἵππω, ἤ κ' αὐτὸς ἐνὶ πρώτοισιν ἁλῴη, IL. <i>17, 504,</i> car pour moi, je ne pense pas qu’Hector s’arrête avant d’être monté sur le char d’Achille aux deux chevaux parés d’une belle crinière, ou avant que lui-même combattant parmi les premiers n’ait été pris ; <i>qqf. avec l’inf. prés. pour marquer l’idée d’une action qui pourrait être faite immédiatement :</i> πρὶν λέγειν, AR. <i>Th. 380,</i> avant de parler ; πρὶν ἱστορεῖν, SOPH. <i>O.C. 36,</i> avant de raconter, <i>etc. ; cf</i>. HDT. <i>8, 3 ;</i> THC. <i>3, 24 ;</i> XÉN. <i>Cyr. 2, 4, 25, etc. ; avec l’inf. pf</i>. πρὶν ἐξηντληκέναι, EUR. <i>Med. 79,</i> avant d’avoir épuisé, <i>etc. ; cf</i>. HDT. <i>3, 25 ;</i> XÉN. <i>An. 4, 1, 21, etc. ;</i><br><b>      2</b> <i>avec l’ind. :</i> πρίν γ' ὅτε ; <i>dans cette construct</i>. πρίν γ' ὅτε, IL. <i>12, 437 ; 13, 322 ;</i> OD. <i>23, 43 ; ou</i> πρίν γ' ὅτε δή, IL. <i>9, 588 ;</i> OD. <i>4, 180 ;</i> πρίν γε, PD. <i>O. 13, 92 ;</i> πρίν, SOPH. <i>O.R. 776 ;</i> HDT. <i>6, 45 ;</i> XÉN. <i>An. 1, 2, 26, etc. ;</i> PLAT. <i>Phædr. 266</i> a, <i>etc. ;</i><br><b>      3</b> <i>avec le sbj. quand il s’agit d’événements futurs, d’ord. après une propos. nég. renfermant un présent ou un futur, ou une propos. interr. équivalant à une propos. négat. ; dans ces diverses construct</i>. πρίν <i>peut être suivi de</i> ἄν : φράσῃς μοι μὴ πέρα, πρὶν ἂν μάθω πρῶτον τόδε, SOPH. <i>Ph. 332,</i> ne me dis rien de plus avant que je sache d’abord ceci ; <i>cf</i>. HDT. <i>1, 32, 140 ; 3, 109 ;</i> ESCHL. <i>Pr. 165 ;</i> SOPH. <i>O.C. 913, 1045, etc. ;</i> XÉN. <i>Cyr. 1, 2, 8, etc. ; de même après un optatif avec</i> ἄν, <i>équivalant à un ind</i>. SOPH. <i>Tr. 2 ; après un ao</i>. XÉN. <i>An. 1, 1, 10 ; de même</i> πρίν γ' ὅταν <i>avec le sbj</i>. OD. <i>4, 477 ; ttef. il est souv. construit sans</i> ἄν : μὴ στέναζε, πρὶν μάθῃς, SOPH. <i>Ph. 917,</i> ne te lamente pas avant de savoir ; <i>cf</i>. OD. <i>10, 175 ;</i> SOPH. <i>Ant. 620, etc. ;</i> PLAT. <i>Phæd. 62</i> c, <i>etc. ; en s.-e</i>. ᾖ <i>ou</i> γένηται : πρὶν ὥρη, OD. <i>15, 394,</i> avant qu’il ne soit temps ; <i>de même que</i> πρὶν ἄν, πρίν <i>peut se construire avec le sbj. même après un inf. dépendant d’un temps secondaire :</i> ἐπέτελλε μὴ πρὶν πημανέειν, πρὶν δωδεκάτη μόλῃ ἠώς, IL. <i>24, 781,</i> il m’a promis de ne pas nous attaquer avant que la douzième aurore ne soit venue ; <i>cf</i>. HDT. <i>1, 19 ; 6, 82 ;</i> THC. <i>8, 9, etc. ;</i><br><b>      4</b> <i>avec l’opt. quand la prop. annoncée par</i> πρίν <i>exprime une opinion non de la pers. qui parle, mais de celle dont on parle :</i> οὐκ ἔθελεν φεύγειν, πρὶν πειρήσαιτ' Ἀχιλῆος, IL. <i>21, 580,</i> il ne voulait pas fuir avant de s’être attaqué à Achille ; <i>de même avec</i> πρίν γ' ὅτε δή, IL. <i>9, 488 ; particul. dans le disc. indir. :</i> ἀπηγόρευε μηδένα βάλλειν, πρὶν Κῦρος ἐμπλησθείη θηρῶν, XÉN. <i>Cyr. 1, 4, 14,</i> il défendait que personne ne frappât une bête avant que Cyrus ne fût rassasié de chasser ; <i>cf</i>. SOPH. <i>Aj. 742, etc. ; ou quand la propos. annoncée par</i> πρίν <i>dépend d’une propos. subordonnée :</i> ὑποσχόμενος αὐτοῖς μὴ πρόσθεν παύσασθαι, πρὶν αὐτοὺς καταγάγοι οἴκαδε, XÉN. <i>An. 1, 2, 2,</i> leur ayant promis de ne pas s’arrêter avant de les avoir ramenés dans leur pays : <i>cf</i>. SOPH. <i>Ph. 551 ;</i> PLAT. <i>Ap. 36</i> c ; <i>après une propos. exprimant un souhait et construite à l’opt. :</i> ὄλοιο μήπω, πρὶν μάθοιμι, SOPH. <i>Ph. 961,</i> je ne souhaite pas encore que tu meures avant que je sache, <i>etc. ; cf</i>. SOPH. <i>Tr. 657, etc. ; de même après une propos. exprimant une hypothèse, par ex. après une propos. construite avec</i> εἰ μή, PLAT. <i>Rsp. 515</i> e, <i>etc. ; après une propos. principale exprimant une éventualité incertaine et construite à l’opt. avec</i> ἄν, SOPH. <i>O.R. 505 ; ou quand la propos. commençant par</i> πρίν <i>marque une idée de répétition,</i> XÉN. <i>An. 4, 5, 30</i>.<br><span><b><span class=\"arrow\"></span></b> <span>[ῐ]</span> IL. <i>2, 344, 354, etc. ; ttef</i>. <span>[ῑ]</span> <i>à l’arsis du premier ou du second pied,</i> IL. <i>2, 348 ; 16, 839 ; 21, 179, etc. ;</i> OD. <i>4, 254 ; 13, 192 ; 15, 210, etc. ; à l’arsis du 4<sup>e</sup> pied,</i> IL. <i>17, 5 ; à la thésis du 3<sup>e</sup> pied après la césure,</i> IL. <i>6, 81 ; 9, 403 ; 13, 172, etc. ;</i> OD. <i>4, 668, etc</i>.<br><span><b>Étym</b>. πρό.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">πριν - πρίν</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n14 fois dans 14 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (3)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n<li>Jean (3)</li>\n<li>Actes (3)</li>\n</ul>\n</td></tr>\n</table>","G4251":"<h1>Priska</h1>\n<p>Strong n° 4251 <i>Prononciation [pris'-kah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Prisca = « vieille »\n<ol><li>femme chrétienne, épouse d'Aquilas. Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πρισκα - Πρίσκα</font>\n<br><br>origine latine</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4252":"<h1>Priscilla</h1>\n<p>Strong n° 4252 <i>Prononciation [pris'-cil-lah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>Priscille, Prisca (Angl. Priscilla) = « petite vieille »\n<ol><li>femme chrétienne, épouse d'Aquilas</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">Πρισκιλλα - Πρίσκιλλα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom propre féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4253":"<h1>pro</h1>\n<p>Strong n° 4253 <i>Prononciation [pro]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>devant, avant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρό</b>, <i>adv. et prép. ;</i><br><b>A</b> <i>adv. :</i><br><b>   I</b> (<i>avec idée de lieu</i>) :<br><b>      1</b> devant, <i>p. opp. à</i> ἐπί : ἐν δέ τε πολλὰ κύματα, πρὸ μέν τ' ἀλλ', αὐτὰρ ἐπ' ἄλλα, IL. <i>13, 799,</i> et alors il y a beaucoup de vagues, les unes en avant, puis d’autres à la suite ; ὣς Τρῶες πρὸ μὲν ἄλλοι ἀρηρότες, αὐτὰρ ἐπ' ἄλλοι ἕποντο, IL. <i>13, 800,</i> ainsi les Troyens s’avançaient en rangs serrés, les uns en avant, puis d’autres à la suite ; <i>cf</i>. HÉS. <i>Sc. 303 ;</i><br><b>      2</b> en s’avançant, en avant, <i>sans mouv</i>. IL. <i>15, 360 ;</i><br><b>      3</b> en avant, <i>càd</i>. au dehors, <i>avec mouv</i>. IL. <i>19, 118 ;</i><br><b>   II</b> (<i>avec idée de temps</i>) :<br><b>      1</b> auparavant, d’abord, avant ; OD. <i>1, 37 ;</i><br><b>      2</b> antérieurement, primitivement, HÉS. <i>Th. 32, 38 ;</i><br><b>      3</b> prématurément, ESCHL. <i>Pr. 696 ;</i><br><b>B</b> <i>prép. avec le gén. :</i><br><b>   I</b> (<i>avec idée de lieu</i>) devant : πρὸ ἄστεος, IL. <i>15, 351 ;</i> OD. <i>24, 468 ;</i> πρὸ πτόλιος, IL. <i>19, 292 ;</i> πρὸ πόληος, IL. <i>22, 110,</i> devant la ville ; πρὸ τειχέων, ESCHL. <i>Suppl. 740,</i> devant les murs ; πρὸ πυλάων, IL. <i>10, 126 ;</i> πρὸ θυρῶν, SOPH. <i>El. 109,</i> devant les portes ; πρὸ νεῶν, IL. <i>18, 172,</i> devant les vaisseaux ; πρὸ ἄνακτος, IL. <i>24, 734,</i> devant le maître, sous les yeux du maître ; πρὸ βασιλέως, XÉN. <i>An. 1, 7, 11,</i> devant le grand-roi ; πρὸ τῶν ὀφθαλμῶν, ESCHN. <i>47, 42,</i> devant les yeux, sous les yeux ; πρὸ ποδῶν, XÉN. <i>An. 4, 6, 12 ;</i> πρὸ τῶν ποδῶν, EL. <i>N.A. 3, 16,</i> à portée, tout près (<i>propr</i>. devant les pieds) ; πρὸ χειρῶν, SOPH. <i>Ant. 1279 ;</i> EUR. <i>Tr. 1207, etc</i>. à portée, sous la main (<i>propr</i>. devant les mains) ; <i>précédé d’un gén. épq. adv. en</i> -θι : Ἰλιόθι πρό, IL. <i>8, 561 ; 10, 12 ; 13, 349 ;</i> OD. <i>8, 581,</i> en avant d’Ilion, devant Ilion ; οὐρανόθι πρό, IL. <i>3, 3,</i> en avant du ciel, jusqu’au ciel ; <i>postér</i>. pour marquer l’éloignement, la distance : πρὸ τριάκοντα σταδίων, STR. <i>382,</i> à une distance de trente stades ; πρὸ πολλοῦ τῆς πόλεως, DH. <i>9, 35,</i> à une grande distance de la ville ; <i>particul. dans la locut</i>. πρὸ ὁδοῦ, en avant sur le chemin : πρὸ ὁδοῦ γίγνεσθαι, être venu en avant sur le chemin, IL. <i>4, 382 ; ou</i> aller en avant, <i>càd</i>. s’en aller, EL. <i>N.A. 3, 16 ;</i> πρὸ ὁδοῦ εἶναι, EL. <i>N.A. 7, 29,</i> être allé à qqe distance ; <i>avec un verbe de mouv. :</i> ἄγετε πρὸ δόμων, EUR. <i>Hec. 59,</i> menez-la devant la maison ; <i>cf</i>. IL. <i>10, 286, etc. ;</i> OD. <i>19, 435, etc. ;</i> SOPH. <i>Tr. 960, etc. À ce sens se rattachent les sens figurés suiv. :</i><br><b>      1</b> pour la défense de, pour (<i>propr</i>. en se plaçant devant, en protégeant) : στῆναι πρὸ Τρώων, IL. <i>24, 215,</i> se poster devant les Troyens, les protéger ; μάχεσθαι πρό <i>et le gén</i>. IL. <i>4, 156, 373 ; 8, 57, etc. ;</i> HDT. <i>8, 74 ; 9, 48, etc</i>. combattre pour ; πρὸ τῆς Ἑλλάδος ἀποθνῄσκειν, HDT. <i>9, 72,</i> mourir pour la Grèce ; πρό τινος πράττειν, XÉN. <i>Cyr. 4, 5, 44 ;</i> βουλεύεσθαι, XÉN. <i>An. 7, 6, 27,</i> agir, délibérer dans l’intérêt de qqn ; πρὸ αὑτοῦ ἐργάζεσθαι, XÉN. <i>Mem. 2, 4, 17,</i> travailler dans son propre intérêt ; ἐρεῖν πρό τινος, SOPH. <i>O.C. 811,</i> parler au nom de qqn ;<br><b>      2</b> de préférence à (<i>propr</i>. en mettant une personne <i>ou</i> une chose devant une autre) : πρὸ πάντων θεῶν τῇ Ἑστίᾳ πρώτῃ προθύειν, PLAT. <i>Crat. 401</i> d, sacrifier à Hestia d’abord avant toutes les autres divinités ; κέρδος πρὸ δίκας αἰνῆσαι, PD. <i>P. 4, 140,</i> préférer le gain à la justice ; ἐπαινεῖν πρὸ δικαιοσύνης ἀδικίαν, PLAT. <i>Rsp. 361</i> e, vanter l’injustice de préférence à la justice ; πρὸ πολλοῦ ποιεῖσθαι, ISOCR. <i>110</i> b, faire grand cas de ; κρίνειν τι πρό τινος, PLAT. <i>Phil. 57</i> e ; αἱρεῖσθαί τι πρό τινος, THC. <i>5, 36 ;</i> PLAT. <i>Rsp. 366</i> b, <i>etc</i>. préférer une chose à une autre ; πρὸ πολλῶν χρημάτων τιμᾶσθαι, THC. <i>1, 33,</i> estimer plus que de grandes sommes d’argent ; <i>particul. après un cp</i>. οἷσι ἡ τυραννὶς πρὸ ἐλευθερίης ἦν ἀσπαστότερον, HDT. <i>1, 62,</i> auxquels la tyrannie était plus chère que la liberté ; περὶ πλείονος ποιεῖσθαί τινα <i>ou</i> τι πρό τινος, PLAT. <i>Crit. 54</i> b, <i>etc</i>. préférer une personne <i>ou</i> une chose à une autre ; <i>de même après</i> ἄλλος : βασιλεὺς οὐδεὶς ἄλλος πρὸ σεῦ ἔσται, HDT. <i>3, 85,</i> aucun autre que toi ne deviendra roi ; <i>cf</i>. HDT. <i>7, 3 ; ou avec</i> πᾶς, ESCHL. <i>Sept. 928, 996 ;</i> PLAT. <i>Menex. 249</i> e, <i>etc. (cf. ci-dessus,</i> PLAT. <i>Crat. 401</i> d) ;<br><b>      3</b> <i>p. suite,</i> au lieu de, à la place de, en échange de, pour : πρὸ ἑωυτοῦ, HDT. <i>7, 3,</i> à sa propre place ; <i>avec idée de succession :</i> γῆν πρὸ γῆς ἐλαύνεσθαι, ESCHL. <i>Pr. 682,</i> échanger une terre pour une autre, aller de l’une dans l’autre ; <i>cf</i>. AR. <i>Ach. 235 ;</i><br><b>      4</b> pour, à cause de, par suite de : πρὸ φόϐοιο, IL. <i>17, 667,</i> par suite de leur épouvante ;<br><b>   II</b> (<i>avec idée de temps</i>) avant : ἠῶθι πρό, OD. <i>5, 469,</i> avant l’aube ; πρὸ ἡμέρας, XÉN. <i>Cyr. 4, 5, 14,</i> avant le jour ; πρὸ δείπνου, XÉN. <i>Cyr. 5, 5, 39,</i> avant le souper ; πρὸ τῶν Τρωϊκῶν, THC. <i>1, 3,</i> avant la guerre de Troie ; πρὸ τῶν Περσικῶν, PLAT. <i>Leg. 642</i> d, avant les guerres médiques ; πρὸ τοῦ θανεῖν, SOPH. <i>Ant. 874,</i> avant de mourir ; πρὸ τοῦ θανάτου, PLAT. <i>Phæd. 57</i> a, <i>etc.,</i> avant la mort ; πρὸ δίκης, PLUT. <i>Fab. 9,</i> avant la sentence ; <i>adv</i>., πρὸ πολλοῦ, HDT. <i>7, 130,</i> avant un long temps, <i>càd</i>. il y a longtemps ; πρὸ μικροῦ, PLUT. <i>Pomp. 73 ;</i> πρὸ ὀλίγου, APP. <i>Civ. 2, 116,</i> avant peu, <i>càd</i>. il y a peu de temps ; ὁ πρὸ τοῦ χρόνος, ESCHL. <i>Eum. 462 ;</i> POL. <i>1, 72, 5, etc</i>. le temps d’avant ; <i>abs</i>. πρὸ τοῦ <i>ou</i> προτοῦ, HDT. <i>1, 122 ; 3, 62 ;</i> ESCHL. <i>Ag. 1177,</i> auparavant, avant ; τὸ πρὸ τούτου, THC. <i>2, 15,</i> auparavant (<i>propr</i>. avant cela) ; πρὸ τούτων, THC. <i>2, 8,</i> avant ces choses-ci, précédemment, antérieurement ; οἱ πρὸ ἡμῶν γενόμενοι, ISOCR. <i>295</i> a ; <i>abs</i>. οἱ πρὸ ἡμῶν, PLUT. <i>M. 2</i> a, <i>1143</i> f, nos prédécesseurs ; οἱ πρὸ ἐμοῦ, THC. <i>1, 97,</i> mes prédécesseurs ; πρὸ πολλοῦ τῆς ἑορτῆς, LUC. <i>Cron. 14,</i> longtemps avant la fête ; πρὸ ἐνιαυτοῦ, PLUT. <i>Syll. 37, Cæs. 63, M. 147</i> f, une année avant ; πρὸ μιᾶς ἡμέρας, PLUT. <i>M. 319</i> b, un jour avant, la veille. — <i>Rem. :</i><br><b>      1</b> <i>en composition,</i> πρό <i>signifie :</i> en avant (προάστειον, πρόδομος, πρόθυρον, πρόχειρος, προάγω, προϐαίνω, προέρχομαι, <i>etc.) ; p. suite,</i> vers, en inclinant vers (πρόθυμος, πρόφρων, <i>etc.) ; ou</i> au dehors (προαιρέω, προέλκω, προφέρω, <i>etc</i>.) ; pour la défense de, en faveur de (προκινδυνεύω, προμάχομαι, προνοέω, προοράω) ; de préférence à, plutôt que (προαιρέομαι, προτιμάω) ; auparavant, avant (προπάτωρ, προειπεῖν) ; d’avance (προαγγέλλω, πρόμαντις) ; tout à fait, <i>avec un adj. ou un adv</i>. (πρόπαρ, προπάροιθε) ;<br><b>      2</b> πρό <i>peut être séparé de son régime par plus. mots ; il ne se place après le rég. que si celui-ci est un gén. épq. adv</i>. Ἰλιόθι πρό, οὐρανόθι πρό, ἠῶθι πρό, IL. <i>23, 115</i>.<br><span><b>Étym</b>. <i>indo-europ</i>. *pro, en avant ; <i>cf. lat</i>. pro, <i>sscr</i>. prá.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ - πρό</font>\n<br><br>une préposition primaire</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Préposition</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n48 fois dans 48 versets de 16 livres bibliques (NT)\n<ul>\n<li>Matthieu (5)</li>\n<li>Marc (1)</li>\n<li>Luc (8)</li>\n<li>Jean (9)</li>\n<li>Actes (8)</li>\n<li>Romains (1)</li>\n<li>1 Corinthiens (2)</li>\n<li>2 Corinthiens (1)</li>\n<li>Galates (3)</li>\n<li>Ephésiens (1)</li>\n<li>Colossiens (1)</li>\n<li>2 Timothée (2)</li>\n<li>Tite (1)</li>\n<li>Hébreux (1)</li>\n<li>Jacques (2)</li>\n<li>1 Pierre (2)</li>\n</ul>\n</td></tr>\n</table>","G4254":"<h1>proago</h1>\n<p>Strong n° 4254 <i>Prononciation [pro-ag'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mener en avant, mettre en vue\n<ol type=\"a\">\n<li>celui qui vient d'un endroit dans lequel il a été gardé caché à la vue, comme venant d'une prison</li>\n<li>dans un sens judiciaire, faire comparaître pour éprouver</li>\n</ol>\n</li>\n<li>aller devant\n<ol type=\"a\">\n<li>précédent, précédemment, antérieur dans le temps</li>\n<li>procéder, aller de l'avant\n<ol>\n<li>dans un mauvais sens, aller plus loin que ne l'admet le droit</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·άγω</b> <span>(<i>f</i>. -άξω, <i>ao.2</i> -ήγαγον, <i>pf. rare</i> -ῆχα)</span><br><b>A <i>tr</i>.<br>   I</b> mener en avant, faire avancer, XÉN. <i>Œc. 11, 15 ;</i> PLAT. <i>Rsp. 415</i> d, <i>etc. ;</i> εἰς τὸ φανερόν, PLAT. <i>Leg. 960</i> a, produire au grand jour ; εἰς φῶς, PLUT. <i>M. 552</i> d, produire à la lumière ; <i>p. suite :</i><br><b>      1</b> prolonger (une haie, <i>etc</i>.) DÉM. <i>1279, 13 ;</i><br><b>      2</b> porter au dehors, produire (des fruits, <i>etc</i>.). ARSTT. <i>Plant. 1, 4, 1 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> faire avancer, promouvoir élever en puissance <i>ou</i> en dignité, <i>acc</i>. THC. <i>1, 144 ;</i> POL. <i>12, 13, 6 ; 15, 21, 4 ;</i> τινὰ εἰς δόξαν, PLUT. <i>Them. 7,</i> élever qqn en crédit, en réputation ; ἐφ' ἡγεμονίας, PLUT. <i>Galb. 20,</i> élever qqn jusqu’au commandement ; <i>au pass</i>. avoir grandi : ἐπὶ μέγα, LUC. <i>Alex. 55,</i> en puissance ;<br><b>      2</b> pousser, exciter : τινὰ ἐπί τι, XÉN. <i>Mem. 1, 4, 1 ;</i> ISOCR. <i>111</i> a ; <i>ou</i> εἴς τι, XÉN. <i>Eq. 9, 3 ;</i> ARSTT. <i>Rhet. 3, 14, etc</i>. pousser qqn à qqe ch. (à la vertu, à la colère, <i>etc</i>.) ; τινά, <i>avec l’inf</i>. DÉM. <i>296, 24,</i> pousser qqn à faire qqe ch. ; <i>au pass</i>. προήχθην γράφειν, POL. <i>3, 4, 13 ;</i> εἰπεῖν, POL. <i>5, 33, 8 ;</i> j’ai été porté à écrire, à dire <i>ou</i> je me suis laissé aller à écrire, à dire ; <i>d’où au pass</i>. se laisser aller ; <i>particul. en mauv. part,</i> se laisser entraîner, se laisser égarer <i>ou</i> tromper, DÉM. <i>316, 12 ;</i><br><b>B <i>intr</i>.<br>      1</b> aller auparavant ; <i>fig</i>. προάγων λόγος, PLAT. <i>Leg. 719</i> a, le discours précédent ; αἱ προάγουσαι γραφαί, JOS. <i>A.J. 19, 6, 2,</i> les écrits précédents ;<br><b>      2</b> s’avancer, avancer, XÉN. <i>An. 6, 5, 6 et 11 ;</i> PLAT. <i>Phæd. 90</i> b ; πρόαγε δή, PLAT. <i>Phædr. 227</i> c, avance donc ! πρ. ἐπὶ τὴν θάλατταν, POL. <i>14, 10, 1,</i> s’avancer jusqu’à la mer ; <i>en parl. du temps,</i> POL. <i>17, 8, 1 ; fig</i>. ἐπὶ πολὺ τῇ τε βίᾳ καὶ τῇ ὠμότητι, DÉM. <i>289, 2,</i> se porter aux derniers excès de violence et de cruauté ; πόρρω πρ. ὕϐρεως, CLÉARQ. (ATH. <i>515</i> f), se laisser aller à un excès d’orgueil ;<br><b>      3</b> <i>fig</i>. marcher avant, <i>càd</i>. être supérieur à, se distinguer plus que, <i>gén</i>. DIOSC. <i>1, 91 ;</i> JOS. <i>c. Ap. 2, 15 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> pousser en avant : ἐς τοῦτο, HDT. <i>7, 50,</i> jusqu’à ce degré ; τινα εἴς τι, HDT. <i>2, 121, etc</i>. pousser <i>ou</i> amener qqn à qqe ch. (au rire, à la pitié, <i>etc</i>.) ; τινα <i>avec l’inf</i>. XÉN. <i>Hipp. 5, 15,</i> pousser qqn à, <i>etc. ;</i><br><b>      2</b> <i>fig</i>. élever : παῖδας, DÉM. <i>1264, 3,</i> des enfants.<br><span><b><span class=\"arrow\"></span></b> <i>Pf</i>. προῆχα, DÉM. <i>346, 24 ; 772, 5 ;</i> PAUS. <i>3, 11, 8 ; 4, 36, 4</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-αγω - προάγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n18 fois dans 18 versets de 6 livres bibliques (NT)\n<ul>\n<li>Matthieu (6)</li>\n<li>Marc (5)</li>\n<li>Luc (1)</li>\n<li>Actes (3)</li>\n<li>1 Timothée (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4255":"<h1>proaireomai</h1>\n<p>Strong n° 4255 <i>Prononciation [pro-ahee-reh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>mettre en avant, apporter depuis des réserves</li>\n<li>apporter pour soi-même, choisir pour soi-même avant un autre, préférer</li>\n<li>avoir résolu, faire le projet de, avoir le dessein</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·αιρέω-ῶ</b> <span>(<i>f</i>. ήσω, <i>ao.2</i> προεῖλον)</span> tirer de, <i>particul. des provisions</i> (blé, farine, <i>etc</i>.) THC. <i>8, 90 ;</i> AR. <i>Th. 419 ;</i> ἐκ τοῦ ταμιείου, TH. <i>Char. 4,</i> prendre à l’office, <i>etc. ; cf</i>. LUC. <i>Rh. præc. 17, etc. ;</i><br><b><i>Moy</i>. προαιρέομαι-οῦμαι</b> <span>(<i>ao.2</i> προειλόμην, <i>pf</i>. προῄρημαι)</span><br><b>      1</b> tirer d’abord pour soi, prendre pour soi : τι ἔκ τινος, PLAT. <i>Lys. 206</i> e, une chose d’une autre ;<br><b>      2</b> choisir de préférence, préférer, <i>acc</i>. XÉN. <i>Mem. 3, 4, 5 ;</i> PLAT. <i>Crit. 52</i> e, <i>etc. ;</i> τὰ τοῦ δήμου προελέσθαι, DÉM. <i>1482, 1,</i> préférer le parti du peuple ; τι ἐκ τῶν ἄλλων, PLAT. <i>Hipp. ma. 299</i> d, <i>etc</i>. choisir une chose entre d’autres ; τί τινος, PLAT. <i>Lach. 200</i> e, <i>etc. ;</i> τι ἀντί τινος, XÉN. <i>Lac. 9, 6 ; Cyr. 5, 2, 12 ;</i> τι πρό τινος, PLAT. <i>Phædr. 245</i> b, préférer une chose à une autre ; <i>avec l’inf</i>. PLAT. <i>Demod. 381</i> a ; ARSTT. <i>Pol. 5, 11, 30, etc. ; abs</i>. DH. <i>Thuc. 1, 2 ;</i> μᾶλλον προαιρεῖσθαι, XÉN. <i>Mem. 2, 1, 2 ; ou</i> μάλιστα πρ. LUC. <i>Anach. 14,</i> préférer de beaucoup ; <i>avec l’inf</i>. XÉN. <i>l. c. ; p. suite,</i> s’attacher de préférence à, <i>acc</i>. DÉM. <i>320, 23 ;</i> ARSTT. <i>Pol. 7, 2, 4, etc. ; d’où</i> se proposer, se charger de, entreprendre : τι, LYCURG. <i>148, 23,</i> qqe ch. ; <i>avec l’inf</i>. λέγειν, PLAT. <i>Phil. 28</i> b, se proposer de dire ; <i>cf</i>. DÉM. <i>286, 25 ; 327, 28 ;</i> ARSTT. <i>Pol. 4, 4, 8, etc. ;</i><br><b>      3</b> prendre d’avance <i>ou</i> le premier, prévenir, <i>acc</i>. POL. <i>16, 29, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-αιρεομαι - προαιρέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4256":"<h1>proaitiaomai</h1>\n<p>Strong n° 4256 <i>Prononciation [pro-ahee-tee-ah'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>apporter une charge contre (c.à.d. dans ce qui a été dit antérieurement) prouver, établir auparavant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·αιτιάομαι-ῶμαι</b>, accuser auparavant, NT. <i>Rom. 3, 9</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-αιτιαομαι - προαιτιάομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4257":"<h1>proakouo</h1>\n<p>Strong n° 4257 <i>Prononciation [pro-ak-oo'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>entendre avant\n<ol type=\"a\">\n<li>l'espérance du salut avant sa réalisation</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ακούω</b> <span>(<i>ao</i>. προήκουσα, <i>pf</i>. προακήκοα, <i>etc</i>.)</span> <span>[ᾰκ]</span> entendre <i>ou</i> apprendre d’avance, <i>acc</i>. HDT. <i>2, 5 ; 5, 86, etc. ;</i> XÉN. <i>Cyr. 4, 3, 21 ;</i> τινός, POL. <i>10, 5, 5,</i> qqe ch. ; περί τινος, DÉM. <i>604, 7,</i> entendre dire auparavant au sujet de qqe ch. ; <i>avec</i> ὅτι, HDT. <i>8, 79 ; avec</i> ὡς, HDT. <i>6, 16</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-ακουω - προακούω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Colossiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4258":"<h1>proamartano</h1>\n<p>Strong n° 4258 <i>Prononciation [pro-am-ar-tan'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>pécher avant\n<ol type=\"a\">\n<li>de ceux qui ont été coupables de vices particulièrement communs parmi les Gentils, avant de recevoir le baptême</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·αμαρτάνω</b> <span>(<i>ao.2</i> -ήμαρτον, <i>etc</i>.)</span> <span>[ᾰμ]</span> pécher auparavant, NT. <i>2Cor. 12, 21 ; 13, 2 ;</i> τὰ προημαρτημένα, HDN <i>3, 14,</i> les fautes antérieures.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-αμαρτανω - προαμαρτάνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4259":"<h1>proaulion</h1>\n<p>Strong n° 4259 <i>Prononciation [pro-ow'-lee-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>porche, vestibule</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·αύλιον, ου (τὸ)</b> prélude sur la flûte, PLAT. <i>Crat. 417</i> e ; ARSTT. <i>Rhet. 3, 14, 1 ; fig</i>. THÉM. <i>367</i> a.<br><span><b>Étym</b>. π. αὐλός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προαυλιον - προαύλιον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Marc (1)</li>\n</ul>\n</td></tr>\n</table>","G4260":"<h1>probaino</h1>\n<p>Strong n° 4260 <i>Prononciation [prob-ah'-ee-no]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aller en avant, être avancé (en âge)</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ϐαίνω</b> <span>(<i>f</i>. προϐήσομαι, <i>ao.2</i> προέϐην, <i>par contr</i>. προὔϐην, <i>pf</i>. προϐέϐηκα)</span><br><b>A <i>intr</i>.<br>   I</b> marcher en avant, s’avancer :<br><b>      1</b> <i>au pr. :</i> εὐθέσι τοῖς σκέλεσι, ARSTT. <i>H.A. 8, 24, 3,</i> s’avancer les jambes droites ; <i>avec l’acc. :</i> κῶλον δεξιόν, EUR. <i>Ph. 1412,</i> s’avancer de la jambe droite ; ἐκ Κορίνθου, LUC. <i>H. conscr. 29,</i> sortir de Corinthe ; <i>en parl. de choses :</i> ἄστρα προϐέϐηκε, IL. <i>10, 252,</i> les astres se sont avancés dans leur course, <i>càd</i>. il est minuit passé ; <i>p. anal. en parl. du temps :</i> χρόνου προϐαίνοντος, HDT. <i>3, 53,</i> le temps s’avançant ; ἡ νὺξ προϐαίνει, XÉN. <i>An. 3, 1, 13,</i> la nuit s’avance ; <i>en parl. de l’âge :</i> προϐήσεται ἡ ἡλικία, XÉN. <i>Ap. 6,</i> l’âge avancera ; <i>avec un suj. de pers. :</i> προϐεϐηκὼς τῇ ἡλικίᾳ, LYS. <i>169, 38,</i> avancé en âge ; πρ. εἰς πεντήκοντα ἔτη, DC. <i>68, 4,</i> arriver à l’âge de cinquante ans ; οἱ ἤδη προϐεϐηκότες, PLUT. <i>Cam. 34,</i> ceux qui sont déjà avancés en âge, les vieillards ; <i>abs</i>. s’être écoulé, être passé, THGN. <i>583 ;</i><br><b>      2</b> <i>fig</i>. faire des progrès, croître : ἐπ' ἔσχατον θράσους προϐαίνειν, SOPH. <i>Ant. 853,</i> en venir au comble de la hardiesse ; εἰς τοῦτο ἔχθρας, DÉM. <i>162, 2,</i> en venir à ce degré de haine ; τοσοῦτον προϐεϐήκαμεν ὥστε, PLAT. <i>Theæt. 187</i> a, nous en sommes arrivés à ce point que, <i>etc. ; impers</i>. εἰς τοῦτο προϐέϐηκε ὥστε, PLAT. <i>Leg. 839</i> c, les choses en sont venues à ce point que, <i>etc. ;</i> πρ. μέχρι τινός, POL. <i>2, 1, 3,</i> aller jusqu’à qqe ch. ; ἐπὶ τὸ χεῖρον προϐαίνει τὰ πράγματα, POL. <i>5, 30, 6,</i> les affaires vont de mal en pis ;<br><b>   II</b> marcher avant, dépasser, surpasser : τινός τινι, IL. <i>6, 125,</i> surpasser qqn en qqe ch. ; <i>p. suite,</i> dominer : δυνάμει τε καὶ αἰδοῖ Τρηχῖνος προϐέϐηκε, HÉS. <i>Sc. 455,</i> il régnait sur Trakhis par sa puissance et le respect qu’il inspirait ;<br><b>B</b> <i>tr. (seul. fut</i>. προϐήσω) faire avancer, promouvoir, <i>fig</i>. PD. <i>O. 8, 63</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Fut. dor. 3 sg</i>. προϐάσει <span>[ᾱ]</span> PD. <i>l. c. ; ao. impér. 2 sg. poét</i>. πρόϐα <span>[ᾱ]</span> <i>c</i>. πρόϐηθι, EUR. <i>Alc. 872 ;</i> AR. <i>Ach. 262 ; 2 pl</i>. προϐᾶτε, SOPH. <i>O.C. 841, etc. ; cf</i>. προϐάω, προϐίϐημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προβαινω - προβαίνω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (3)</li>\n</ul>\n</td></tr>\n</table>","G4261":"<h1>proballo</h1>\n<p>Strong n° 4261 <i>Prononciation [prob-al'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>jeter en avant\n<ol type=\"a\">\n<li>d'arbres, qui poussent, qui se recouvrent de feuilles</li>\n<li>germer</li>\n<li>pousser en avant (une foule)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ϐάλλω</b> <span>(<i>f</i>. προϐαλῶ, <i>ao.2</i> προέϐαλον, <i>par contr</i>. προὔϐαλον, <i>pf</i>. προϐέϐληκα)</span><br><b>   I</b> jeter devant : νότος βορέῃ προϐάλεσκε φέρεσθαι, OD. <i>5, 331,</i> le notos poussait (le radeau) en avant pour qu’il fût emporté par le vent du nord ; πρ. τρωγάλια τοῖς θεωμένοις, AR. <i>Pl. 789,</i> jeter des friandises aux spectateurs ; χόρτον, PLUT. <i>M. 1096</i> c, jeter du fourrage (à un cheval) ; <i>fig. càd. :</i><br><b>      1</b> lancer, donner le signal de, mettre la main à : κακὴν ἔριδα, IL. <i>11, 529,</i> engager une querelle funeste ;<br><b>      2</b> jeter devant soi, <i>càd</i>. mettre en avant comme argument <i>ou</i> prétexte, <i>acc</i>. SOPH. <i>Tr. 810 ;</i> EUR. <i>Hec. 825 ;</i> DÉM. <i>112, 26, etc. ;</i> προϐαλλόμενος λόγος, THC. <i>6, 92,</i> parole qu’on met en avant, <i>càd</i>. proverbe qui est dans toutes les bouches ;<br><b>      3</b> proposer (une question, une tâche, <i>etc.) acc</i>. AR. <i>Nub. 757 ;</i> PLAT. <i>Crat. 407</i> d, <i>Hipp. ma. 290</i> d, <i>Soph. 245</i> b, <i>etc. ;</i> τινὶ σκέψιν τινός, PLAT. <i>Phil. 65</i> d, <i>etc</i>. soumettre à qqn l’examen de qqe ch. ; <i>avec un pron. d’interrog. indir</i>. πρόϐαλε σεαυτῷ τί, EPICT. <i>Ench. 4,</i> demande-toi ce que, <i>etc. ; avec</i> πότερον, ARSTD. <i>t. 1, 41 ;</i><br><b>   II</b> jeter en avant, précipiter, PLUT. <i>Per. 28 ; fig</i>. πρ. ψυχὴν ἐν κύϐοισι, EUR. <i>Rhes. 183,</i> exposer sa vie sur un coup de dé ; πρ. ἑαυτόν, HDT. <i>7, 141,</i> s’abandonner soi-même, perdre courage ;<br><b>   III</b> produire au dehors, <i>d’où :</i><br><b>      1</b> produire : καρπόν, JOS. <i>A.J. 4, 8, 19,</i> produire un fruit ;<br><b>      2</b> émettre : ὀσμήν, DIOSC. <i>4, 50,</i> exhaler une odeur forte ; φωνὴν ὀξεῖαν, DS. <i>3, 8,</i> faire entendre une voix aiguë ; <i>cf</i>. DS. <i>5, 30 ;</i><br><b>   IV</b> proposer pour une fonction : προϐληθεὶς πυλαγόρας, DÉM. <i>277, 2,</i> ayant été proposé pour être élu pylagore, <i>càd</i>. député au conseil amphictionique ; πρ. λειτουργεῖν γυμνασίαρχον, AND. <i>17, 19,</i> proposer un gymnasiarque pour une liturgie : <i>cf</i>. LUC. <i>Cat. 25 au pass. ;</i><br><b><i>Moy.</i></b> <span>(<i>f</i>. προϐαλοῦμαι, <i>ao.2</i> προεϐαλόμην, <i>par contr</i>. προὐϐαλόμην, <i>pf</i>. προϐέϐλημαι)</span><br><b>A <i>tr</i>.<br>   I</b> jeter devant soi : οὐλοχύτας, IL. <i>1, 458 ; 2, 421 ;</i> OD. <i>3, 447,</i> commencer le sacrifice en répandant l’orge sacrée ;<br><b>   II</b> placer devant soi, <i>càd. :</i><br><b>      1</b> se proposer, se charger de : ἔργον, HÉS. <i>O. 777,</i> se mettre au travail ;<br><b>      2</b> placer devant soi comme un rempart ; τὰ ὅπλα, XÉN. <i>An. 1, 2, 17,</i> tenir les armes en avant, <i>càd</i>. les piques étendues et les boucliers en avant ; τὼ χεῖρε, AR. <i>Ran. 201,</i> jeter les mains en avant pour se garantir ; προϐεϐλημένοι τοὺς θωρακοφόρους, XÉN. <i>Cyr. 6, 3, 24,</i> couverts par les soldats armés de cuirasses ; προϐάλλεσθαι ποταμόν, POL. <i>2, 5, 5,</i> se couvrir d’un fleuve ; <i>abs</i>. se garantir, s’abriter, DÉM. <i>51, 27 ; fig</i>. πρ. συμμαχίαν, DÉM. <i>293, 20,</i> s’abriter derrière une alliance ; πρ. τὸν Ὅμηρον, PLAT. <i>Lach. 201</i> b, se retrancher derrière Homère, l’alléguer comme une autorité ; πρ. μάρτυρα, ISOCR. <i>373</i> c, <i>ou abs</i>. πρ. DÉM. <i>1132, 5 ; 1139, 10,</i> se retrancher derrière un témoin, produire un témoin ;<br><b>      3</b> placer devant soi comme un modèle : ἔθνος σοφίης πέρι, HDT. <i>4, 46,</i> se proposer un peuple comme un modèle de sagesse ;<br><b>   III</b> proposer pour une charge : τινα, HDT. <i>1, 98 ;</i> XÉN. <i>An. 5, 9, 25, etc</i>. qqn ; στρατηγούς, PLAT. <i>Leg. 755</i> c, <i>etc</i>. proposer d’élire comme généraux ;<br><b>   IV</b> jeter en avant, jeter au loin, rejeter : ἐν ᾗ (ἀκτῇ) με προὐϐάλου ἄφιλον, SOPH. <i>Ph. 1017,</i> ce rivage sur lequel tu m’as jeté sans ami ;<br><b>   V</b> <i>t. de droit att</i>. poursuivre par une instance προϐολή : τινα, DÉM. <i>571, 16,</i> accuser qqn ; τινά τι, DÉM. <i>523, 21,</i> accuser qqn de qqe ch. ; <i>avec une prop. inf. :</i> προὐϐαλόμην ἀδικεῖν τουτονί, DÉM. <i>514, 6,</i> je l’ai accusé de méfaits ; <i>abs</i>. ὁ προϐαλλόμενος, DÉM. <i>572, 15,</i> le poursuivant, l’accusateur dans un procès προϐολή ; <i>au sens pass</i>. être accusé, XÉN. <i>Hell. 1, 7, 35 ; p. ext</i>. accuser, <i>en gén</i>. attaquer, blâmer, DH. <i>4, 24, etc. ;</i><br><b>B <i>intr</i>.<br>      1</b> se jeter devant : τινος, DÉM. <i>21, 100 ;</i><br><b>      2</b> πρ. πρό τινος, XÉN. <i>Cyr. 2, 3, 10,</i> protéger une partie de son corps ;<br><b>      3</b> surpasser : τινος νοήματι, IL. <i>19, 218,</i> surpasser qqn en intelligence.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. itér. 3 sg</i>. προϐάλεσκε (<i>v. ci-dessus) ; impf. moy. 3 pl. poét</i>. προϐάλοντο, IL. <i>1, 458 ; 2, 421, etc. ;</i> OD. <i>3, 447</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-βαλλω - προβάλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4262":"<h1>probatikos</h1>\n<p>Strong n° 4262 <i>Prononciation [prob-at-ik-os']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appartenant aux brebis</li>\n<li>la porte des brebis, porte des brebis (porte dans le mur nord de Jérusalem)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προϐατικός, ή, όν</b> <span>[ᾰ]</span> qui concerne les moutons, <i>et, p. ext.,</i> les chèvres, EUP. <i>2-1, 427 Meineke ;</i> προϐατικὴ πύλη, NT. <i>Joh. 5, 2,</i> porte <i>ou</i> piscine probatique où on lavait les bestiaux pour les sacrifices, <i>à Jérusalem</i>.<br><span><b>Étym</b>. πρόϐατον.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προβατικος - προβατικός</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Jean (1)</li>\n</ul>\n</td></tr>\n</table>","G4263":"<h1>probaton</h1>\n<p>Strong n° 4263 <i>Prononciation [prob'-at-on]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>tout animal à quatre pattes ayant coutume de paître, petit bétail, (par opposition au gros bétail, chevaux, etc.) et généralement une brebis ou une chèvre\n<ol type=\"a\">\n<li>une brebis dans l'ensemble du N.T.</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόϐατον, ου (τὸ)</b> <span>[ᾰ]</span> <i>d’ord. au pl</i>. ce qui marche en avant, <i>càd. :</i><br><b>   I</b> animal à quatre pieds, <i>p. opp. à ceux qui volent, rampent ou nagent, d’où :</i><br><b>      1</b> <i>en gén</i>. bête apprivoisée, <i>d’où</i> bétail, troupeau de bétail, IL. <i>14, 124 ; 23, 550 ;</i> HH. <i>Merc. 571 ; p. opp. à</i> ἄνθρωπος, HÉS. <i>O. 556 ; en parl. de chevaux,</i> HDT. <i>6, 56 ; de cavales,</i> PD. <i>fr. 305 Bgk ; d’un taureau,</i> SIM. <i>fr. 249 Bgk ; de bœufs,</i> HDT. <i>4, 61 ; de bêtes de boucherie,</i> HDT. <i>2, 41 ;</i><br><b>      2</b> <i>d’ord. en parl. d’animaux de petit bétail (brebis, chèvres</i>) HDT. <i>1, 133 ; 8, 137 ; p. opp. à</i> ἵπποι, IL. <i>23, 550 ; aux bêtes de somme,</i> THC. <i>2, 14 ; particul</i>. brebis, moutons, AR. <i>Av. 714 ;</i> ATT. ; <i>fig. comme emblème de douceur,</i> débonnaire, LUC. <i>As. 33 ; d’où prov. p. opp. au lion,</i> POL. <i>5, 35, 13 ;</i> PLUT. <i>Cleom. 32 ; en ce sens comiq. au cp. :</i> προϐάτου προϐατότερον, SOPHR. <i>96 Ahrens</i> plus mouton qu’un mouton ; <i>comme emblème de simplicité ou de naïveté,</i> AR. <i>Nub. 1203 ; de pureté,</i> l’agneau sans tache, <i>en parl. de J.C</i>. ECCL. ;<br><b>   II</b> <i>sorte de poisson de mer,</i> OPP. <i>H. 1, 146 ; 3, 139 ;</i> EL. <i>N.A. 9, 38</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Dat. plur. hétérocl</i>. πρόϐασι, ARCAD. <i>138 ; cf</i>. AR. <i>fr. 937, 949, 1022 Dind. ;</i> PLAT. <i>Euthyd. 302</i> a, <i>etc</i>.<br><span><b>Étym</b>. προϐαίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προβατον - πρόβατον</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n41 fois dans 37 versets de 9 livres bibliques (NT)\n<ul>\n<li>Matthieu (11)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Jean (21)</li>\n<li>Actes (1)</li>\n<li>Romains (1)</li>\n<li>Hébreux (1)</li>\n<li>1 Pierre (1)</li>\n<li>Apocalypse (1)</li>\n</ul>\n</td></tr>\n</table>","G4264":"<h1>probibazo</h1>\n<p>Strong n° 4264 <i>Prononciation [prob-ib-ad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>faire aller, se pencher en avant, traîner</li>\n<li>métaph. inciter, instiguer, presser\n<ol type=\"a\">\n<li>persuader, agir par persuasion</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ϐιϐάζω</b> <span>(<i>f. att</i>. -ϐιϐῶ, <i>ao</i>. προεϐίϐασα)</span> <span>[ῐ]</span><br><b>   I <i>tr</i>.<br>      1</b> faire avancer, <i>acc</i>. SOPH. <i>O.C. 180 ; fig</i>. εἰς ἀρετήν, PLAT. <i>Prot. 328</i> b ; <i>cf</i>. XÉN. <i>Mem. 1, 5, 1,</i> dans la voie de la vertu, <i>etc. ;</i><br><b>      2</b> avancer, prolonger (un rempart) <i>acc</i>. DS. <i>4, 78 ;</i><br><b>      3</b> <i>fig</i>. faire faire des progrès, rendre plus grand, plus fort, <i>acc</i>. POL. <i>9, 10, 4 ;</i> τινὰ ἐς τὰς ἀρχάς, DC. <i>58, 23,</i> élever qqn aux dignités ;<br><b>   II <i>intr</i>.<br>      1</b> avancer, POL. <i>5, 100, 1 ; 10, 44, 1 ;</i><br><b>      2</b> couvrir (une jument) <i>acc</i>. ARSTT. <i>H.A. 5, 14, 20</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προβιβαζω - προβιβάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Actes (1)</li>\n</ul>\n</td></tr>\n</table>","G4265":"<h1>problepo</h1>\n<p>Strong n° 4265 <i>Prononciation [prob-lep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prévoir</li>\n<li>pourvoir</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ϐλέπω</b>, prévoir, prévenir, DH. <i>11, 20 ;</i><br><b><i>Moy.</i></b> <i>m. sign</i>. NT. <i>Hebr. 11, 40</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προβλεπω - προβλέπω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4266":"<h1>proginomai</h1>\n<p>Strong n° 4266 <i>Prononciation [prog-in'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>provenir ou venir avant, arriver avant\n<ol type=\"a\">\n<li>des péchés commis antérieurement</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>προ·γίγνομαι</b> <span>(<i>f</i>. προγενήσομαι, <i>ao.2</i> προεγενόμην, <i>pf</i>. προγέγονα ; <i>pf. pass</i>. προγεγένημαι)</span><br><b>   I</b> (<i>avec idée de lieu</i>) :<br><b>      1</b> se produire au jour, se montrer, IL. <i>18, 525 ;</i> HH. <i>6, 7 ;</i><br><b>      2</b> s’avancer, aller en avant, HÉS. <i>Sc. 345 ;</i> CALL. <i>Dian. 178 ;</i> OPP. <i>H. 2, 103 ;</i><br><b>   II</b> (<i>avec idée de temps</i>) :<br><b>      1</b> <i>en parl. de pers</i>. naître avant : οἱ προγεγονότες, HDT. <i>7, 3 ;</i> XÉN. <i>Mem. 4, 8, 10 ;</i> οἱ προγεγενημένοι, XÉN. <i>Cyr. 8, 7, 24 ;</i> οἱ προγενόμενοι, POL. <i>10, 17, 12,</i> ceux qui nous ont précédés, les ancêtres ;<br><b>      2</b> <i>en parl. de choses,</i> se produire avant, THC. <i>1, 1 ;</i> PLAT. <i>Conv. 219</i> e, <i>etc. ;</i> τὰ προγεγενημένα, THC. <i>1, 20, etc</i>. les événements antérieurs, le passé ; πρ. πρό τινος, T. LOCR. <i>97</i> a ; PLAT. <i>Phil. 39</i> d, se produire avant qqe ch.<br><span><b><span class=\"arrow\"></span></b> <i>Ion. et réc</i>. προγίνομαι, HDT. ; <i>ao. 3 pl. épq</i>. προγένοντο, IL. HÉS. <i>ll. cc. ; pl.q.pf. 3 sg</i>. προὐγεγόνει, PLAT. <i>Conv. 219</i> e.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προγινομαι - προγίνομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4267":"<h1>proginosko</h1>\n<p>Strong n° 4267 <i>Prononciation [prog-in-oce'-ko]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir la connaissance avant</li>\n<li>savoir d'avance\n<ol type=\"a\">\n<li>de ceux qui sont élus par Dieu pour le salut</li>\n</ol>\n</li>\n<li>être prédestiné</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<u>Mot apparenté</u> : <b>προ·γιγνώσκω</b> <span>(<i>f</i>. προγνώσομαι, <i>ao.2</i> προέγνων, <i>d’où inf</i>. προγνῶναι)</span><br><b>      1</b> savoir, connaître <i>ou</i> comprendre d’avance, <i>acc</i>. HH. <i>Cer. 258 ; abs</i>. EUR. <i>Hipp. 1072 ; avec</i> ὅτι, XÉN. <i>Hipp. 8, 12 ; p. suite</i> faire connaître d’avance, annoncer, pronostiquer, <i>acc</i>. ARSTT. <i>H.A. 9, 40, 57 ;</i><br><b>      2</b> décider auparavant, THC. <i>2, 64 ; d’où</i> pourvoir à, <i>acc</i>. XÉN. <i>Cyr. 2, 4, 11 ; p. suite,</i> juger, <i>d’où</i> condamner d’avance : προεγνωσμένος ἀδικεῖν, DÉM. <i>861, 23,</i> reconnu auparavant coupable.<br><span><b><span class=\"arrow\"></span></b> <i>Ion. et réc</i>. προγινώσκω, ARSTT. <i>l. c. ; ao. inf. épq</i>. προγνώμεναι, HH. <i>l. c</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-γινοσκω - προγινώσκω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 4 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Romains (2)</li>\n<li>1 Pierre (1)</li>\n<li>2 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4268":"<h1>prognosis</h1>\n<p>Strong n° 4268 <i>Prononciation [prog'-no-sis]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>prescience (savoir d'avance)</li>\n<li>prévoyance, pré-arrangement</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόγνωσις, εως (ἡ)</b> connaissance anticipée, prévision, PLUT. <i>M. 399</i> d, <i>982</i> c ; LUC. <i>Alex. 8, etc. ; t. de méd</i>. prévision de la marche d’une maladie, ANTH. <i>11, 382</i>.<br><span><b>Étym</b>. προγιγνώσκω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προγνωσις - πρόγνωσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4269":"<h1>progonos</h1>\n<p>Strong n° 4269 <i>Prononciation [prog'-on-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>né avant, plus vieux, aîné\n<ol type=\"a\">\n<li>des ancêtres</li>\n<li>d'une mère</li>\n<li>de grand-parents</li>\n<li>d'arrières grand-parents (s'ils sont encore en vie)</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n➀ <b>προγονός, οῦ</b>, <i>ou</i> <b>πρόγονος, ου (ὁ, ἡ)</b> enfant né d’un premier mariage, <i>au masc</i>. beau-fils (<i>lat</i>. privignus) EUR. <i>Ion</i> 1329 ; DH. <i>Isocr</i>. 18 ; LUC. <i>Cal</i>. 26 ; <i>au fém</i>. ἡ πρόγονος, IS. <i>Euph</i>. § 5 ; PLUT. <i>Pomp</i>. 9 ; <i>postér</i>. ἡ προγόνη, PHIL. 2.303, belle-fille.<br><span><b>Étym</b>.</span> προγίγνομαι.<br><br>\n➁ <b>πρόγονος, ος, ον :<br>   I</b> né avant, <i>d’où :</i><br><b>      1</b> plus âgé, HERMÉSIAN. <i>El. 74 ;</i><br><b>      2</b> ancêtre, aïeul, HDT. <i>4, 127 ;</i> EUR. <i>Ion 267 ;</i> PLAT. <i>Conv. 186</i> e, <i>etc. ; au fém</i>. ESCHL. <i>Suppl. 533 ; au plur</i>. οἱ πρόγονοι, HDT. <i>7, 150 ;</i> ESCHL. <i>Pers. 405, etc</i>. les ancêtres ; οἱ ἄνωθεν πρ. PLAT. <i>Menex. 236</i> e ; οἱ πάλαι πρ. PLAT. <i>Ep. 359</i> d, les ancêtres les plus reculés ; ἐκ προγόνων, PLAT. <i>Theæt. 173</i> d, de toute antiquité, <i>litt</i>. depuis les ancêtres ; <i>en parl. des dieux auteurs ou fondateurs d’une race,</i> ESCHL. <i>fr. 271 ;</i> PLAT. <i>Euthyd. 302</i> d, <i>etc. ; particul. en parl. de Zeus,</i> EUR. <i>Or. 1242 ; fig. en parl. des fondateurs d’une école,</i> LUC. <i>Herm. 15 ;</i> PHILSTR. <i>333 ;</i><br><b>   II</b> né après, <i>propr</i>. « en continuant » : οἱ πρόγονοι, rejetons, postérité (<i>cf. lat</i>. progenies) DH. <i>7, 50</i>.<br><span><b>Étym</b>. προγίγνομαι.</span><br><br>\n➂ <b>πρό·γονος, ου (ὁ, ἡ)</b> enfant né d’un premier mariage, <i>au masc</i>. beau-fils (<i>lat</i>. privignus) EUR. <i>Ion 1329 ;</i> DH. <i>Isocr. 18 ;</i> LUC. <i>Cal. 26 ; au fém</i>. ἡ πρόγονος, IS. <i>12, 5 ;</i> PLUT. <i>Pomp. 9 ; postér</i>. ἡ προγόνη, PHIL. <i>2, 303,</i> belle-fille.<br><span><b>Étym</b>. προγίγνομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προγονος - πρόγονος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4270":"<h1>prographo</h1>\n<p>Strong n° 4270 <i>Prononciation [prog-raf'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>écrire avant (dans le temps)\n<ol type=\"a\">\n<li>de ce qui est indiqué ou désigné avant l'actuel (dans les écritures de l'A.T.)</li>\n</ol>\n</li>\n<li>dépeindre ou peindre ouvertement\n<ol type=\"a\">\n<li>écrire pour les yeux de tous ceux qui peuvent lire</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προγράφω</b> <span>[ᾰ]</span><br><b>      1</b> écrire auparavant, <i>att</i>. THC. <i>1, 23, etc. ; au pass</i>. PLUT. <i>M. 1018</i> c ; κρίσιν τινί, DÉM. <i>1151 fin, ou</i> δίκην τινί, PLUT. <i>Cam. 11,</i> envoyer d’avance à qqn par écrit une assignation en justice ;<br><b>      2</b> écrire en tête de : τινὰ τῆς βουλῆς, PLUT. <i>Æmil. 38, Flam. 18,</i> écrire le nom du princeps senatus (<i>propr</i>. inscrire qqn en tête de la liste des sénateurs) <i>en parl. du censeur ; en gén</i>. τινὰ ἐπὶ τῶν ψηφισμάτων, PLUT. <i>Demetr. 10,</i> inscrire qqn en tête des décrets ; <i>au pass</i>. être inscrit en tête de, <i>gén</i>. PLUT. <i>M. 318</i> c ;<br><b>      3</b> faire savoir par un écrit exposé en public, afficher, placarder : ἐν πινακίοις, AR. <i>Av. 450,</i> inscrire sur de petites tablettes affichées ; πρ. ἐκκλησίαν, ESCHN. <i>3, 5 fin, etc</i>. convoquer une assemblée par voie d’affiches ; χορηγούς, ARSTT. <i>Œc. 2, 32, 1,</i> publier la liste des chorèges ; <i>au pass</i>. φρουρὰ προγραφεῖσα, DÉM. <i>1257, 5,</i> garnison établie qqe part par un édit ; <i>particul</i>. annoncer au moyen d’affiches une vente aux enchères, TH. (STOB. <i>Fl. 44, 21) ; à Rome,</i> inscrire sur une liste de proscription affichée : τινά, POL. <i>32, 21, 12,</i> qqn ; <i>au pass</i>. προγραφεὶς ἐπὶ θανάτῳ, PLUT. <i>Brut. 27,</i> inscrit, pour être mis à mort, sur une liste de proscription ; <i>abs</i>. οἱ προγεγραμμένοι, POL. <i>32, 22, 1,</i> les proscrits.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προγραφω - προγράφω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 4 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (2)</li>\n<li>Galates (1)</li>\n<li>Ephésiens (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4271":"<h1>prodelos</h1>\n<p>Strong n° 4271 <i>Prononciation [prod'-ay-los]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>ouvertement évident, connu de tous, manifeste</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρό·δηλος, ος, ον</b>, qui éclate aux yeux, très clair, très évident, HPC. <i>Art. 797 ;</i> EUR. <i>Or. 190 ;</i> PLAT. <i>Phædr. 238</i> b ; DÉM. <i>293, 25, etc. ; p. opp. à</i> ἀγνοούμενος, ISOCR. <i>123</i> b ; πρόδηλον ὅτι, XÉN. <i>Hell. 6, 4, 9 ; ou</i> πρόδηλα ὅτι, HDT. <i>9, 17 ;</i> XÉN. <i>Eq. 3, 3,</i> (il est) de toute évidence que ; ἐκ προδήλου, SOPH. <i>El. 1429,</i> de toute évidence, distinctement.<br><span><b>Étym</b>. π. δῆλος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προδηλος - πρόδηλος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>1 Timothée (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4272":"<h1>prodidomi</h1>\n<p>Strong n° 4272 <i>Prononciation [prod-id'-o-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>donner avant, donner en premier</li>\n<li>trahir, livrer</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·δίδωμι</b> <span>[δῐ]</span> <span>(<i>f</i>. προδώσω, <i>ao</i>. προέδωκα-προὔδωκα, <i>etc</i>.)</span><br><b>   I</b> donner d’avance, payer d’avance, faire l’avance de, avancer, <i>acc</i>. XÉN. <i>Hell. 1, 5, 7 ;</i> ARSTT. <i>Œc. 2, 24, 2 ;</i> POL. <i>8, 17, 7 ;</i><br><b>   II</b> livrer, <i>càd. :</i><br><b>      1</b> livrer par trahison : τινά <i>ou</i> τί τινι, HDT. <i>6, 23 ;</i> ESCHL. <i>Pr. 38,</i> une personne <i>ou</i> une chose à qqn ; πόλιν, HDT. <i>8, 128 ;</i> ἱκέτας, EUR. <i>Her. 246,</i> une ville, des suppliants, <i>etc. ; avec l’inf. :</i> τινὰ θανεῖν, EUR. <i>Or. 1588,</i> livrer qqn à la mort ;<br><b>      2</b> <i>p. suite,</i> trahir, déserter, abandonner lâchement : τινά, HDT. <i>9, 7 ;</i> AR. <i>Pax 408, etc. ;</i> PLAT. <i>Leg. 762</i> c, <i>etc</i>. qqn ; <i>au pass</i>. être trahi, être abandonné : ὑπό τινος, HDT. <i>9, 60,</i> par qqn ; <i>avec une prép. :</i> πρός τινα, HDT. <i>3, 45,</i> passer par trahison dans le parti de qqn ; <i>avec un acc. explétif :</i> προδοσίαν προδιδόναι, DIN. <i>91, 27,</i> accomplir une trahison ; <i>fig. :</i> ὅρκους, XÉN. <i>Cyr. 5, 1, 22,</i> trahir des serments ; τὸ δίκαιον, PLAT. <i>Leg. 907</i> a, trahir la justice ; <i>avec un suj. de chose,</i> faire défaut à, <i>acc</i>. HDT. <i>7, 187 ; 8, 52 ;</i> XÉN. <i>Hell. 5, 2, 5 ;</i> ἐπεὶ ᾔσθετο τὸν ὀφθαλμὸν αὐτὸν προδιδόντα, DÉM. <i>1239 fin,</i> quand il s’aperçut que son œil lui faisait défaut ;<br><b>      3</b> renoncer à : τὸν ἀγῶνα, ESCHN. <i>16, 19,</i> à la lutte ; ἡδονάς, SOPH. <i>Ant. 1166,</i> aux plaisirs ; <i>cf</i>. AR. <i>Nub. 1500 ;</i> DÉM. <i>1397, 25</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προδιδωμι - προδίδωμι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4273":"<h1>prodotes</h1>\n<p>Strong n° 4273 <i>Prononciation [prod-ot'-ace]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>celui qui trahi, un traître</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προδότης, ου (ὁ) :<br>      1</b> traître, HDT. <i>8, 30, 144 ;</i> τῶν ὅρκων, LYS. (DH. <i>Lys. 14</i>) traître à ses serments ;<br><b>      2</b> <i>particul</i>. déserteur, XÉN. <i>An. 6, 6, 5 ; Hell. 7, 3, 7 ; en gén</i>. celui qui abandonne qqn dans le danger, ESCHL. <i>Pr. 1068, etc</i>.<br><span><b>Étym</b>. προδίδωμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προδοτης - προδότης</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom masculin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Actes (1)</li>\n<li>2 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4274":"<h1>prodromos</h1>\n<p>Strong n° 4274 <i>Prononciation [prod'-rom-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>un avant-coureur, un précurseur\n<ol type=\"a\">\n<li>celui qui est envoyé à l'avant pour observer ou agir comme un espion, un éclaireur, un soldat peu armé</li>\n<li>celui qui vient à l'avance dans un lieu où les autres vont</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρό·δρομος, ος, ον</b> ; :<br><b>   I</b> <i>au propre,</i> qui court devant, qui précède en courant, HDT. <i>1, 60, etc. ;</i> ESCHL. <i>Sept. 211 ;</i> SOPH. <i>Ant. 108 ;</i> EUR. <i>Ph. 296 ;</i> ὁ πρ. coureur envoyé en avant, PLAT. <i>Charm. 154</i> a ; οἱ πρόδρομοι :<br><b>      1</b> corps <i>ou</i> division d’avant-garde, HDT. <i>4, 121, 122 ;</i> THC. <i>2, 22 ; particul. dans l’armée macédonienne,</i> ARR. <i>An. 1, 12 ;</i> troupe de cavalerie légère, XÉN. <i>Hipp. 1, 25 ;</i><br><b>      2</b> vents du N. E. précédant de huit jours la canicule, ARSTT. <i>Meteor. 2, 15, 2 ; Probl. 26, 12, 2 ;</i> TH. <i>Vent. 11 ;</i><br><b>   II</b> <i>fig. :</i><br><b>      1</b> précurseur : ἀστὴρ ἀελίου πρ. ION <i>11,</i> astre précurseur du soleil ; ἠπίαλος πυρετοῦ πρ. AR. <i>fr. 315,</i> salivation qui annonce la fièvre ; <i>subst. en parl. de saint Jean-Baptiste,</i> NAZ. <i>1, 729 Migne ;</i><br><b>      2</b> précoce : σῦκα πρόδρομα, TH. <i>C.P. 5, 1, 5, etc</i>. figues précoces ; πρόδρομος οἶνος, ATH. <i>30</i> b, sorte de vin de Mytilène provenant d’un jus qui coule avant le pressurage du raisin.<br><span><b>Étym</b>. π. δραμεῖν.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προδρομος - πρόδρομος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4275":"<h1>proeido</h1>\n<p>Strong n° 4275 <i>Prononciation [pro-i'-do]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>prévoir</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·οράω-ῶ</b> <span>(<i>f</i>. προόψομαι, <i>ao.2</i> προεῖδον, <i>pf</i>. πρόοιδα, <i>d’où inf</i>. προειδέναι)</span><br><b>   I</b> voir en avant :<br><b>      1</b> voir devant soi, <i>acc</i>. THC. <i>7, 44 ; abs</i>. XÉN. <i>Cyr. 4, 3, 21 ; avec</i> εἰς <i>et l’acc</i>. ARSTT. <i>H.A. 4, 1, 12 ;</i><br><b>      2</b> prévoir, connaître d’avance, <i>acc</i>. PD. <i>N. 1, 27 ;</i> HDT. <i>5, 24 ;</i> XÉN. <i>Cyr. 3, 2, 15 ; Conv. 4, 5 ;</i> DÉM. <i>52, 4, etc. ;</i><br><b>   II</b> pourvoir à, <i>gén</i>. HDT. <i>3, 159 ; d’où</i> prendre soin de, <i>gén</i>. HDT. <i>2, 121 ; 5, 39 ;</i><br><b><i>Moy.</i></b> :<br><b>      1</b> regarder devant soi, XÉN. <i>Cyr. 4, 3, 21 ;</i><br><b>      2</b> prévoir pour soi, THC. <i>5, 111 ;</i> DÉM. <i>63, 11 ;</i><br><b>      3</b> pourvoir à, <i>acc</i>. THC. <i>1, 17 ;</i> PLAT. <i>Rsp. 499</i> b, prendre ses précautions, <i>avec</i> πρός <i>et l’acc</i>. DS. <i>20, 102 ; avec</i> μή, DÉM. <i>773, 1</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. sbj. 2 pl</i>. προειδῆτε, THC. <i>1, 37</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-ειδω - προοράω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4276":"<h1>proelpizo</h1>\n<p>Strong n° 4276 <i>Prononciation [pro-el-pid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>espérer d'avance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ελπίζω</b>, espérer longtemps avant, POSIDIPP. (ATH. <i>377</i> c) ; NT. <i>Eph. 1, 12, etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προελπιζω - προελπίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4277":"<h1>proepo</h1>\n<p>Strong n° 4277 <i>Prononciation [pro-ep'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>dire d'avance\n<ol type=\"a\">\n<li>dire dans ce qui précède, dire au-dessus</li>\n<li>dire avant c.à.d. auparavant</li>\n<li>dire d'avance c.à.d. avant l'événement : prophéties</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\nπρο·λέγω :<br>   I</b> (πρό, devant) :<br><b>      1</b> choisir de préférence à d’autres, IL. <i>13, 689 ;</i> THCR. <i>Idyl. 13, 18 ;</i><br><b>      2</b> désigner comme premier, mettre au premier rang, PD. <i>N. 2, 28 ;</i><br><b>   II</b> (πρό, auparavant) dire auparavant, <i>d’où :</i><br><b>      1</b> prédire, <i>acc. en parl. d’un oracle,</i> HDT. <i>1, 53 ; 8, 136 ;</i> ESCHL. <i>Pr. 1071 ;</i> PLAT. <i>Euthyphr. 3</i> c ; <i>en parl. d’un médecin,</i> pronostiquer, HPC. <i>Progn. 42 ;</i><br><b>      2</b> prévenir, avertir, <i>avec</i> ὅτι, PLAT. <i>Rsp. 337</i> a, <i>etc. ;</i><br><b>      3</b> annoncer, déclarer d’avance, <i>acc</i>. (une interdiction légale, LYCURG. <i>148, 16 ;</i> une guerre, POL. <i>13, 3, 5, etc.) ; avec une prop. inf</i>. ESCHL. <i>Sept. 336, etc. ;</i> τινί, <i>avec l’inf</i>. XÉN. <i>An. 7, 7, 3 ;</i> DIN. <i>99, 14 ;</i> τινὶ ὅτι, ANT. <i>126, 17 ; ou</i> ὡς, POL. <i>5, 57, 2,</i> ordonner à qqn de, <i>etc</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προεπω - προλέγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>Galates (1)</li>\n<li>1 Thessaloniciens (1)</li>\n</ul>\n</td></tr>\n</table>","G4278":"<h1>proenarchomai</h1>\n<p>Strong n° 4278 <i>Prononciation [pro-en-ar'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>faire un commencement avant, commencer, entreprendre auparavant</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ενάρχομαι</b>, commencer auparavant <i>ou</i> avant les autres, NT. <i>2Cor. 8, 6</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-εν-αρχομαι - προενάρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (2)</li>\n</ul>\n</td></tr>\n</table>","G4279":"<h1>proepaggellomai</h1>\n<p>Strong n° 4279 <i>Prononciation [pro-ep-ang-ghel'-lom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>annoncer avant</li>\n<li>promettre avant</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·επαγγέλλω :<br>      1</b> annoncer auparavant, DC. <i>38, 13 ; 40, 32 ;</i><br><b>      2</b> briguer auparavant, DC. <i>39, 31 ;</i><br><b><i>Moy.</i></b> <i>c. à l’act</i>. 1, DC. <i>42, 32 ; 46, 40</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-επ-αγγελλω - προεπαγγέλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4280":"<h1>proereo</h1>\n<p>Strong n° 4280 <i>Prononciation [pro-er-eh'-o]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>dire d'avance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προερέω-ῶ</b>, <i>v</i>. *προέρω.<br><br>\n<b>*προ·έρω</b> (<i>seul. aux temps suiv. : f</i>. προερῶ, <i>ion</i>. προερέω ; <i>pf</i>. προείρηκα ; <i>pass. ao</i>. προερρήθην, <i>par contr</i>. προὐρρήθην, <i>d’où part</i>. προρρηθείς ; <i>pf</i>. προείρημαι ; <i>pl.q.pf</i>. προειρήμην) :<br><b>      1</b> dire d’avance <i>ou</i> auparavant, PLAT. <i>Pol. 292</i> d, <i>etc. ; au pass</i>. être dit auparavant, PLAT. <i>Phæd. 75</i> b, <i>etc. ;</i> ταῦτα προειρήσθω, ISOCR. <i>43</i> e, que cela soit dit en manière de préface ;<br><b>      2</b> publier <i>ou</i> déclarer d’avance (une guerre) XÉN. <i>Ages. 1, 17 ;</i><br><b>      3</b> ordonner d’avance <i>ou</i> auparavant : τινί, <i>avec l’inf</i>. HDT. <i>1, 77, 81 ; ou</i> τινὶ ὡς, HDT. <i>3, 61,</i> à qqn de, <i>etc. ; au pass</i>. HDT. <i>1, 126, etc</i>. THC. <i>2, 84, etc</i>.<br><span><b>Étym</b>. π. *ἔρω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-ερεω - προλέγω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n<li>2 Corinthiens (2)</li>\n<li>Galates (1)</li>\n<li>Hébreux (1)</li>\n<li>2 Pierre (1)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4281":"<h1>proerchomai</h1>\n<p>Strong n° 4281 <i>Prononciation [pro-er'-khom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>aller vers l'avant, avancer</li>\n<li>marcher en avant\n<ol type=\"a\">\n<li>devancer, précéder</li>\n<li>prendre les devants, avant un autre</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·έρχομαι</b> <span>(<i>ao.2</i> προῆλθον, <i>etc</i>.)</span><br><b>   I</b> s’avancer, <i>càd. :</i><br><b>      1</b> aller en avant, continuer d’aller, <i>avec l’acc. d’instrum. :</i> πρ. πόδα, LUC. <i>Herm. 32,</i> aller en avant ; <i>ou de lieu :</i> ἡμερησίαν ὁδόν, PLAT. <i>Rsp. 616</i> b, marcher pendant un jour ; κατὰ τὴν ὁδόν, XÉN. <i>An. 4, 2, 16,</i> poursuivre son chemin ; ἔς τι, THC. <i>5, 65,</i> s’avancer vers un but ; <i>abs</i>. s’avancer à la tribune, s’avancer pour parler, ESCHN. <i>75, 27, etc. ; en parl. du temps :</i> προελθόντος πολλοῦ χρόνου, THC. <i>1, 10,</i> beaucoup de temps s’étant écoulé ; οἱ προεληλυθότες ταῖς ἡλικίαις, XÉN. <i>Hell. 6, 1, 4,</i> ceux qui sont avancés en âge, les vieillards ; <i>en parl. d’un discours, d’une argumentation,</i> PLAT. <i>Phædr. 237</i> c, <i>etc. ; fig. :</i> ἐς τοῦτο προελθεῖν, HDT. <i>7, 50,</i> en être arrivé à ce degré (de puissance) ; ἐνταῦθα πρ. ὥστε, ISOCR. <i>Antid. § 88,</i> en être arrivé à ce point que, <i>etc. ;</i> προελθεῖν εἰς πᾶν μοχθηρίας, DÉM. <i>29, 18,</i> en être arrivé au dernier degré de méchanceté ;<br><b>      2</b> aller au loin : ἐπὶ χιλόν, XÉN. <i>Cyr. 6, 3, 9,</i> faire du fourrage ;<br><b>      3</b> aller au dehors, sortir : ἐκ χωρίου, XÉN. <i>Hell. 7, 5, 25,</i> d’une place forte ;<br><b>   II</b> aller avant, marcher devant, précéder : τινος, XÉN. <i>Cyr. 2, 2, 7 ; ou</i> τινα, NT. <i>Marc. 6, 33,</i> qqn.<br><span><b><span class=\"arrow\"></span></b> <i>Pour le fut. les Att. emploient d’ord</i>. πρόειμι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-ερχομαι - προέρχομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n9 fois dans 9 versets de 5 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (2)</li>\n<li>Luc (2)</li>\n<li>Actes (3)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4282":"<h1>proetoimazo</h1>\n<p>Strong n° 4282 <i>Prononciation [pro-et-oy-mad'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>préparer avant, rendre prêt d'avance</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ετοιμάζω</b> <span>(<i>f</i>. -ετοιμάσω, <i>ao</i>. -ητοίμασα)</span> préparer <i>ou</i> tenir prêt d’avance, PLUT. <i>M. 230</i> e, <i>etc. ;</i><br><b><i>Moy.</i></b> <span>(<i>impf. ion. sans augm</i>. προετοιμαζόμην, <i>ao. ion</i>. προετοιμασάμην)</span> <i>m. sign. acc</i>. HDT. <i>7, 21 ; 8, 24</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-ετοιμαζω - προετοιμάζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 2 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>Ephésiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4283":"<h1>proeuaggelizomai</h1>\n<p>Strong n° 4283 <i>Prononciation [pro-yoo-ang-ghel-id'-zom-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>annoncer ou promettre d'avance de bonnes nouvelles</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ευαγγελίζομαι</b>, annoncer d’avance une bonne nouvelle, NT. <i>Gal. 3, 8 ;</i> PHIL. <i>1, 7</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προευαγγελιζομαι - προευαγγελίζομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4284":"<h1>proechomai</h1>\n<p>Strong n° 4284 <i>Prononciation [pro-ekh-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>avoir de l'avance sur un autre, avoir la prééminence sur un autre, exceller, surpasser, l'emporter</li>\n<li>surpasser dans l'excellence qui peut être passée à son crédit</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·έχω</b> <span>(<i>f</i>. προέξω, <i>ao.2</i> προέσχον, <i>etc</i>.)</span><br><b>   I <i>tr</i>.<br>      1</b> avoir <i>ou</i> tenir devant : τὼ χεῖρε, XÉN. <i>Cyr. 2, 3, 10,</i> tenir ses deux mains devant soi ; τί τινος, AR. <i>Nub. 989,</i> tenir une chose devant une autre ;<br><b>      2</b> posséder auparavant, HDT. <i>9, 4 ;</i> DS. <i>Exc. 586, 73 ;</i> εὐεργεσίαν τινός, DC. <i>43, 3,</i> avoir déjà reçu qqe service de qqn, être déjà l’obligé de qqn ;<br><b>      3</b> posséder de préférence : ἔκ τινος τιμὴν τῶν ἐνδίκων, SOPH. <i>Ant. 208,</i> recevoir de qqn des honneurs avant ceux qui les méritent ;<br><b>   II <i>intr.</i></b> être en avant, <i>d’où :</i><br><b>      1</b> être proéminent, saillant, <i>en parl. de promontoires, de hauteurs,</i> OD. <i>6, 138 ; 12, 11 ; de tours,</i> IL. <i>22, 97, etc. ; d’une pointe de terre qui s’avance dans la mer,</i> HDT. <i>4, 177 ; cf</i>. THC. <i>4, 109 ; 6, 97, etc. ; en gén</i>. dépasser, surpasser : τῇ κεφαλῇ, XÉN. <i>Cyr. 4, 3, 16,</i> dépasser de la tête ; τῷ μεγέθει, LUC. <i>Musc. enc. 1,</i> dépasser en grandeur ; εἴκοσιν ἡλικίας ἔτεσιν, PLAT. <i>Leg. 879</i> c, être plus âgé de vingt ans ; <i>fig</i>. πρ. δήμου, HH. <i>Cer. 151,</i> être le premier parmi le peuple ; <i>abs</i>. être supérieur, être éminent, THC. <i>3, 82 ;</i> τὸ προὖχον, THC. <i>3, 84,</i> la supériorité ; οἱ προὔχοντες, THC. <i>5, 17,</i> les principaux citoyens, les chefs ; πρ. τινός τινι, HDT. <i>1, 1 ;</i> THC. <i>7, 66 ; ou</i> ἔν τινι, THC. <i>6, 16, etc. ;</i> κατά τι, LUC. <i>Am. 30,</i> surpasser qqn en qqe ch. ; <i>rar. avec un acc. de pers. :</i> τινά, XÉN. <i>An. 3, 2, 19,</i> surpasser qqn ; <i>d’où au pass</i>. προέχεσθαι ὑπό τινος, PLUT. <i>M. 1038</i> d, être surpassé par qqn ; <i>cf</i>. NT. <i>Rom. 3, 9 ;</i><br><b>      2</b> <i>impers</i>. προέχει, cela avance à qqe ch., cela est utile : οὔ τι προέχει, <i>avec l’inf</i>. HDT. <i>9, 27,</i> il n’avance à rien de, il ne sert de rien de ;<br><b><i>Moy.</i></b> :<br><b>      1</b> tenir devant soi, <i>acc</i>. OD. <i>3, 8 ;</i> AR. <i>Nub. 1385 ;</i><br><b>      2</b> présenter devant soi, <i>d’où</i> présenter, offrir, HDT. <i>2, 42 ;</i> THC. <i>3, 68 ; fig</i>. προέχεσθαί τι, SOPH. <i>Ant. 80,</i> mettre en avant qqe motif, alléguer un prétexte ; <i>cf</i>. THC. <i>1, 140</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-εχομαι - προέχω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4285":"<h1>proegeomai</h1>\n<p>Strong n° 4285 <i>Prononciation [pro-ay-geh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>aller devant et montrer le chemin, précéder et conduire, être à l'avant comme un chef</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ηγέομαι-οῦμαι :<br>   I</b> marcher en avant, <i>càd. :</i><br><b>      1</b> précéder, XÉN. <i>Hipp. 4, 5 ;</i> τὸ προηγούμενον στράτευμα, XÉN. <i>Ages. 2, 2,</i> l’avant-garde, <i>p. opp. à</i> οὐρά ; προηγεῖσθαι ὁδόν, XÉN. <i>An. 6, 3, 10,</i> devancer sur la route ; <i>avec un gén. :</i> τινος, XÉN. <i>Hipp. 4, 5 ;</i> POL. <i>12, 13, 11,</i> précéder qqn <i>ou</i> qqe ch. ; <i>fig</i>. précéder, PLUT. <i>Pomp. 45, etc. ;</i> τὰ προηγούμενα, POL. <i>16, 16, 2,</i> prémisses ; τὸ προηγούμενον, ARR. <i>Epict. 1, 20, 1, etc</i>. le point principal ;<br><b>      2</b> <i>p. suite :</i> servir de guide, montrer le chemin, HDT. <i>2, 48, etc. ;</i> τινί, AR. <i>Pl. 1195 ;</i> XÉN. <i>Cyr. 2, 1, 1,</i> montrer le chemin à qqn ;<br><b>      3</b> s’avancer : ἐς ἄκρον, PAUS. parvenir au plus haut point, au comble (de la haine, <i>etc</i>.) ;<br><b>      4</b> dépasser, <i>fig. acc</i>. NT. <i>Rom. 12, 10 ;</i><br><b>   II</b> se présenter, se produire au jour : προηγουμένη ἀντίθεσις, HERMOG. objection qui se présente d’elle-même.<br><span><b>Étym</b>. π. ἡγέομαι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-ηγεομαι - προηγέομαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4286":"<h1>prothesis</h1>\n<p>Strong n° 4286 <i>Prononciation [proth'-es-is]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>la disposition d'une chose placée en vue, le pain de proposition\n<ol type=\"a\">\n<li>douze pains de froment, correspondant au nombre des tribus d'Israël, lesquels pains étaient offerts à chaque Sabbat, et séparés en deux rangées, disposés pour sept jours sur une table placée dans le sanctuaire ou devant le tabernacle et ensuite dans le temple</li>\n</ol>\n</li>\n<li>un but, un dessein</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόθεσις, εως (ἡ)</b> action de placer devant, <i>d’où :</i><br><b>      1</b> exposition publique (d’un corps, PLAT. <i>Leg. 947</i> b, <i>etc. ;</i> DÉM. <i>1071, 21, etc. ;</i> des pains consacrés dans le temple de Jérusalem, NT. <i>Hebr. 9, 6 ; d’où</i> οἱ ἄρτοι τῆς προθέσεως, NT. <i>Matth. 12, 4,</i> les pains de proposition) ;<br><b>      2</b> ce qu’on se propose, projet, dessein, intention, PHILIPP. (DÉM. <i>284, 13</i>) ; POL. <i>4, 73, 2, etc. ;</i> κατὰ τὴν πρόθεσιν, POL. <i>1, 54, 1 ;</i> κατὰ πρόθεσιν, POL. <i>12, 11, 6,</i> de propos délibéré ;<br><b>      3</b> <i>t. de philos. ou de rhét</i>. proposition à développer, à discuter, ARSTT. <i>Rhet. 3, 13, 2, etc. ;</i><br><b>      4</b> <i>t. de gr</i>. préposition, DH. <i>Comp. 2 ;</i> PLUT. <i>M. 1009</i> c.<br><span><b>Étym</b>. προτίθημι.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προθεσις - πρόθεσις</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n12 fois dans 12 versets de 8 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Luc (1)</li>\n<li>Actes (2)</li>\n<li>Romains (2)</li>\n<li>Ephésiens (2)</li>\n<li>2 Timothée (2)</li>\n<li>Hébreux (1)</li>\n</ul>\n</td></tr>\n</table>","G4287":"<h1>prothesmios</h1>\n<p>Strong n° 4287 <i>Prononciation [proth-es'-mee-os]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>fixé auparavant, déterminé d'avance, prédéterminé, stipulé</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·θέσμιος, α, ον</b>, fixé d’avance, LUC. <i>Nigr. 27 ;</i> ἡ προθεσμία (<i>s.-e</i>. ἡμέρα) jour fixé d’avance pour une échéance légale, échéance (d’une dette), terme (d’une assignation) ESCHN. <i>6, 14 ;</i> DÉM. <i>952, 19 ; d’où</i> échéance, <i>en gén</i>. LYS. <i>109, 42 ;</i> PLAT. <i>Leg. 954</i> d, <i>etc</i>.<br><span><b>Étym</b>. π. θέσμιος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προθεσμιος - προθεσμία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4288":"<h1>prothumia</h1>\n<p>Strong n° 4288 <i>Prononciation [proth-oo-mee'-ah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>zèle, esprit, empressement</li>\n<li>penchant, inclination, empressement de l'esprit</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προθυμία, ας (ἡ)</b> <span>[ῡ]</span><br><b>      1</b> bonne volonté, zèle, ardeur, empressement, HDT. <i>5, 49 ;</i> ESCHL. <i>Pr. 341 ;</i> XÉN. <i>Cyr. 1, 6, 13 ;</i> PLAT. <i>Leg. 961</i> c, <i>etc. ;</i> ὑπὸ προθυμίας, PLAT. <i>Phæd. 91</i> c ; διὰ τὴν προθυμίαν, POL. <i>1, 20, 15,</i> par bonne volonté, avec empressement ; πάσῃ προθυμίᾳ, PLAT. <i>Rsp. 412</i> e, avec toute la bonne volonté, <i>etc. ; au pl</i>. IL. <i>2, 588 ;</i> EUR. <i>Or. 708 ;</i> πρ. τινός, SOPH. <i>Tr. 669,</i> zèle pour qqe ch. ; ἐπί τινα, HDT. <i>7, 6 ;</i> εἴς τινα, XÉN. <i>Hell. 6, 5, 43 ;</i> περί τινα, XÉN. <i>An. 7, 7, 45 ;</i> ὑπέρ τινος, DÉM. <i>11, 13,</i> empressement à l’égard de qqn ; <i>avec l’inf</i>. HDT. <i>1, 204 ;</i> PLAT. <i>Prot. 327</i> b, <i>etc. ; avec le part</i>. PLAT. <i>Tim. 23</i> d ; <i>avec</i> ὅπως, PLAT. <i>Menex. 247</i> a ;<br><b>      2</b> désir : ἐκ προθυμίης (<i>ion</i>.) τινός, HDT. <i>6, 65 ;</i> κατὰ τήν τινος προθυμίην (<i>ion</i>.) HDT. <i>1, 124,</i> d’après le vœu <i>ou</i> sur la demande de qqn ; <i>p. ext</i>. désir sensuel, SOR. <i>Obst. p. 262 Dietz</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ion</i>. προθυμίη, HDT. <i>ll. cc. ; par except</i>. <span>[ῑ]</span> IL. <i>2, 588</i>.<br><span><b>Étym</b>. πρόθυμος.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προθυμια - προθυμία</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom féminin</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (1)</li>\n<li>2 Corinthiens (4)</li>\n</ul>\n</td></tr>\n</table>","G4289":"<h1>prothumos</h1>\n<p>Strong n° 4289 <i>Prononciation [proth'-oo-mos]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>prêt, bien disposé, plein de bonne volonté</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρό·θυμος, ος, ον</b> <span>[ῡ]</span> plein d’ardeur, de bonne volonté, d’empressement, ATT. ; τινι, XÉN. <i>Hell. 2, 3, 40 ; ou</i> εἴς τινα, EUR. <i>Med. 1146 ;</i> LYS. <i>160, 37, etc</i>. à l’égard de qqn ; τινος, THC. <i>3, 67 ;</i> SOPH. <i>El. 3 ;</i> πρός τι, XÉN. <i>Hell. 1, 5, 2 ;</i> PLAT. <i>Rsp. 468</i> c ; ἐπί τι, XÉN. <i>Hell. 1, 1, 34 ;</i> εἴς τι, THC. <i>8, 68 ;</i> XÉN. <i>Cyr. 1, 4, 22,</i> pour qqn <i>ou</i> qqe ch. ; <i>avec l’inf</i>. HDT. <i>2, 3, etc. ;</i> EUR. <i>Med. 720 ;</i> PLAT. <i>Conv. 220</i> e, <i>etc</i>. pour faire qqe ch. ; <i>subst</i>. τὸ πρόθυμον, PLAT. <i>Leg. 859</i> b, <i>etc</i>. bonne volonté, zèle, ardeur.<br><span>•<i> Cp</i>. -ότερος, PLAT. <i>Conv. 220</i> e ; <i>sup</i>. -ότατος, HDT. <i>1, 36 ;</i> THC. <i>8, 68</i>.<br><span><b>Étym</b>. π. θυμός.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προθυμος - πρόθυμος</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adjectif</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 3 livres bibliques (NT)\n<ul>\n<li>Matthieu (1)</li>\n<li>Marc (1)</li>\n<li>Romains (1)</li>\n</ul>\n</td></tr>\n</table>","G4290":"<h1>prothumos</h1>\n<p>Strong n° 4290 <i>Prononciation [proth-oo'-moce]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>volontiers, avec empressement, de bon gré</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προθύμως</b> <span>[ῡ]</span> <i>adv</i>., avec bonne volonté, de bon cœur, avec ardeur <i>ou</i> empressement, ESCHL. <i>Ag. 1591 ;</i> HDT. <i>2, 59 ;</i> ATT. ; πρ. ἔχειν πρός τι, PLAT. <i>Conv. 176</i> c, être ardent <i>ou</i> empressé pour qqe ch.<br><span>•<i> Cp</i>. -ότερον, PLAT. <i>Rsp. 498</i> c ; THC. <i>6, 80 ;</i> XÉN. <i>An. 1, 4, 9, etc. ;</i> <i>• Sup</i>. -ότατα, HDT. <i>l. c. ;</i> THC. <i>8, 68</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προθυμως - προθύμως</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Adverbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Pierre (1)</li>\n</ul>\n</td></tr>\n</table>","G4291":"<h1>proistemi</h1>\n<p>Strong n° 4291 <i>Prononciation [pro-is'-tay-mee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>disposer ou placer devant\n<ol type=\"a\">\n<li>mettre au-dessus</li>\n<li>être au-dessus de, surveiller, diriger, présider</li>\n<li>être un protecteur ou gardien\n<ol>\n<li>donner de l'aide</li>\n</ol>\n</li>\n<li>prendre soin de, prêter attention à\n<ol>\n<li>professer d'honnêtes occupations</li>\n</ol>\n</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·ΐστημι :<br>A</b> <i>tr. (aux temps suiv. : prés., impf</i>. προΐστην, <i>f</i>. προστήσω, <i>ao.1</i> προέστησα, <i>p. contr</i>. προὔστησα ; <i>pf</i>. προέστηκα, <i>p. contr</i>. προὔστηκα) :<br><b>      1</b> mettre en avant, placer en tête : τινὰ μάχεσθαι, IL. <i>4, 156,</i> mettre qqn en avant pour combattre ; τοὺς εὐκινητοτάτους τοῦ κέρατος προϊστάναι, POL. <i>1, 33, 7,</i> mettre les plus agiles en tête de l’aile ; <i>fig</i>. τινὰ τῆς πόλεως προϊστάναι, PLAT. <i>Lach. 197</i> d, placer qqn à la tête de la cité ;<br><b>      2</b> exposer publiquement : τινά, D. CHR. <i>126</i> a, qqn ;<br><b>B</b> <i>intr. (aux temps suiv. : ao.2</i> προέστην, <i>pf.1</i> προέστηκα, <i>pl.q.pf</i>. προειστήκειν) :<br><b>   I</b> se placer devant, <i>càd. :</i><br><b>      1</b> se placer en face de : τινί, HDT. <i>1, 129, ou</i> τινά, SOPH. <i>El. 1370,</i> se placer devant qqn ; <i>particul. avec idée d’hostilité,</i> se dresser en face de, <i>dat</i>. SOPH. <i>Aj. 1133 ; fig</i>. se présenter (à l’esprit), HDT. <i>1, 86 ;</i><br><b>      2</b> se placer devant pour protéger, protéger, défendre : τινός, HDT. <i>9, 107,</i> défendre qqn ; φίλων, PLUT. <i>Dio. 26,</i> ses amis ; <i>ou avec le gén. de l’objet contre lequel on protège :</i> ἀναγκαίας τύχης, SOPH. <i>Aj. 790,</i> protéger contre les rigueurs de la fortune ;<br><b>      3</b> se placer à la tête de, <i>d’où, à l’ao. et au pf</i>. être à la tête de : τοῦ δήμου, THC. <i>6, 28 ;</i> τῆς πόλεως, PLAT. <i>Gorg. 520</i> a, être à la tête du peuple, de la cité ; οἱ τοῦ δήμου προεστηκότες, THC. <i>3, 70 ; 6, 28 ; 8, 65,</i> les premiers de la cité ; οἱ ἐν ταῖς πόλεσι προστάντες, THC. <i>3, 88,</i> les premiers citoyens dans les villes ; <i>joint à</i> ἄρχων, PLAT. <i>Rsp. 428</i> e ; <i>en mauv. part,</i> être le meneur, le chef d’un parti de conjurés, XÉN. <i>An. 6, 2, 9 ; p. suite,</i> présider à : τῆς εἰρήνης, ESCHN. <i>49, 41,</i> présider à la paix ; φόνου, SOPH. <i>El. 968,</i> présider à un meurtre ; <i>fig</i>. gouverner (sa vie, <i>etc.) gén</i>. HDT. <i>2, 173 ;</i> XÉN. <i>Mem. 3, 2, 2, etc. ;</i><br><b>      4</b> être devant, dépasser, surpasser : τινὸς εὐψυχίᾳ, PLAT. <i>Tim. 25</i> b, être supérieur à qqn par la noblesse d’âme ;<br><b>   II</b> s’exposer en public, se prostituer, ESCHN. <i>Ep. 7 ;</i> CLÉM. <i>524, etc. ;</i><br><b><i>Moy</i>. προΐσταμαι</b> :<br><b>A</b> <i>tr. (aux temps suiv. : prés. impf</i>. προϊστάμην, <i>f</i>. προστήσομαι, <i>ao.1</i> προεστησάμην) :<br><b>   I</b> placer devant soi : σκίπωνα, HDT. <i>4, 172,</i> un bâton ; τὰ ἅρματα, XÉN. <i>Hell. 4, 1, 18,</i> les chars ; <i>fig. :</i><br><b>      1</b> mettre à sa tête : τινα, PLAT. <i>Leg. 629</i> a, qqn ; τινὰ πρ. ἑαυτοῦ, PLAT. <i>Rsp. 565</i> c, mettre qqn à sa tête ; στρατηγόν τινα, DÉM. <i>1432, 14,</i> mettre qqn à sa tête comme général ;<br><b>      2</b> mettre devant soi pour se protéger ; τινα αὑτῆς, DÉM. <i>1357, 25,</i> prendre qqn pour curateur, <i>propr</i>. placer qqn devant soi, se couvrir de qqn (<i>cf. l’idée de</i> tuteur) ; τὰ τῶν Ἀμφικτυόνων δόγματα, DÉM. <i>62, 4,</i> alléguer les décrets des Amphictyons ;<br><b>      3</b> se proposer : τινα παράδειγμα, LUC. <i>Somn. 18,</i> se proposer qqn comme modèle ;<br><b>   II</b> mettre en avant, mettre en relief, en évidence : τοῦ ἀγῶνος τὴν πρὸς ἐμὲ ἐχθρὰν προΐσταται, DÉM. <i>230, 8,</i> il met ainsi en évidence comme motif réel de cette lutte sa haine contre moi ;<br><b>B</b> <i>intr. au prés. et à l’impf. :</i> προΐστασθαι τέχνης, ATH. <i>612</i> a, présider à un art, être maître en un art.<br><span><b><span class=\"arrow\"></span></b> <i>Pf. 2 pl. ion</i>. προεστέατε, HDT. <i>5, 49 ; part. pl. ion</i>. προεστεῶτες, HDT. <i>4, 79, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-ισθημι - προΐστημι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n8 fois dans 8 versets de 4 livres bibliques (NT)\n<ul>\n<li>Romains (1)</li>\n<li>1 Thessaloniciens (1)</li>\n<li>1 Timothée (4)</li>\n<li>Tite (2)</li>\n</ul>\n</td></tr>\n</table>","G4292":"<h1>prokaleomai</h1>\n<p>Strong n° 4292 <i>Prononciation [prok-al-eh'-om-ahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>appeler</li>\n<li>appeler à soi\n<ol type=\"a\">\n<li>spéc. à un défi dans un combat ou une lutte</li>\n</ol>\n</li>\n<li>provoquer, irriter, chercher noise</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·καλέω-ῶ</b> <span>[ᾰ]</span> appeler au dehors, DC. <i>44, 34 ; au pass</i>. POL. <i>23, 9, 2 ;</i><br><b><i>Moy.</i></b> appeler en son nom, <i>càd. :</i><br><b>      1</b> provoquer : τινα χάρμῃ, IL. <i>7, 218,</i> qqn à un combat ; εἰς ἀγῶνα, XÉN. <i>Mem. 2, 3, 17,</i> provoquer à une lutte ; <i>avec l’inf</i>. μαχέσασθαι, IL. <i>3, 432, etc</i>. provoquer à combattre ; <i>abs</i>. IL. <i>13, 809, etc. ; fig. :</i> εὐγένειάν τινος, EUR. <i>H.f. 308,</i> faire appel à la générosité de qqn ;<br><b>      2</b> inviter, engager : τινα ἔς τι, HDT. <i>4, 201 ; ou</i> πρός τι, PLAT. <i>Conv. 217</i> c, inviter qqn à qqe ch. (à un entretien, à un repas, <i>etc</i>.) ;<br><b>      3</b> <i>p. ext</i>. exhorter, exciter ; τινα ἔς τι, THC. <i>4, 19 ; ou</i> ἐπί τι, THC. <i>5, 43 ; ou simpl</i>. τινά τι, PLAT. <i>Euthyphr. 5</i> a, <i>etc. ;</i> AR. <i>Ach. 652, etc</i>. qqn à qqe ch., presser qqn de faire qqe ch. ;<br><b>      4</b> assigner en justice : τινα εἰς ὅρκον, DÉM. <i>1240, 27,</i> qqn pour prêter serment ; κατά τινος εἰς μαρτυρίαν, DÉM. <i>850, 13,</i> porter assignation contre qqn pour obtenir un témoignage ; <i>au pass</i>. être convoqué pour un arbitrage, THC. <i>1, 34 ;</i><br><b>      5</b> faire appel en justice : ἐπί τινα, POL. <i>26, 2, 13,</i> en appeler à un tribunal ; κρίσεις ἐπὶ τὸν δῆμον, DH. <i>5, 19, 70,</i> porter des jugements en appel devant le peuple.<br><span><b><span class=\"arrow\"></span></b> <i>Ao. inf. épq</i>. προκάλεσσαι, IL. <i>3, 432. Moy. ao. ind. 3 sg. épq</i>. προκαλέσσατο, IL. <i>7, 218 ; 13, 809, etc</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προκαλεομαι - προκαλέω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>Galates (1)</li>\n</ul>\n</td></tr>\n</table>","G4293":"<h1>prokataggello</h1>\n<p>Strong n° 4293 <i>Prononciation [prok-at-ang-ghel'-lo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>annoncer d'avance (qu'une chose sera)\n<ol type=\"a\">\n<li>de prophéties</li>\n</ol>\n</li>\n<li>annoncer dans le sens de promettre</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·καταγγέλλω</b>, annoncer <i>ou</i> déclarer d’avance, NT. <i>Ap. 3, 18, 2, 2Cor. 9, 5 ;</i> JOS. <i>A.J. 2, 5, 2</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-κατ-αγγελλω - προκαταγγέλλω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n4 fois dans 4 versets de 2 livres bibliques (NT)\n<ul>\n<li>Actes (3)</li>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4294":"<h1>prokatartizo</h1>\n<p>Strong n° 4294 <i>Prononciation [prok-at-ar-tid'-zo]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>préparer d'avance, régler, organiser d'avance, mettre au point</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·καταρτίζω</b>, ajuster <i>ou</i> arranger auparavant, NT. <i>2Cor. 9, 5 ; au pass</i>. HPC. <i>24, 10 et 18</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-κατ-αρτιζω - προκαταρτίζω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n</ul>\n</td></tr>\n</table>","G4295":"<h1>prokeimai</h1>\n<p>Strong n° 4295 <i>Prononciation [prok'-i-mahee]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>se trouver ou être placé devant (une personne ou une chose) ou en face de</li>\n<li>mettre devant\n<ol type=\"a\">\n<li>être placé devant les yeux, se trouver en vue\n<ol>\n<li>se trouver en avant</li>\n</ol>\n</li>\n<li>être désigné, destiné</li>\n<li>être là, être présent, être à portée de main</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρό·κειμαι :<br>   I</b> être couché <i>ou</i> placé devant, <i>càd. :</i><br><b>      1</b> être déposé en face de : ὀνείατα προκείμενα, IL. <i>9, 91 ;</i> OD. <i>1, 149, etc</i>. mets placés devant des convives ; δαὶς πρ. HDT. <i>1, 211 ;</i> δεῖπνον πρ. HDT. <i>5, 105,</i> repas servi ;<br><b>      2</b> être situé <i>ou</i> s’étendre en avant : Αἴγυπτος προκειμένη τῆς ἐχομένης γῆς, HDT. <i>2, 12,</i> l’Égypte s’avançant dans la mer plus loin que les pays adjacents (l’Arabie et la Libye) ; <i>particul</i>. servir de rempart, de défense : πρόκειται τῆς χώρας ὄρη, XÉN. <i>Mem. 3, 5, 25,</i> des montagnes défendent les approches du pays ;<br><b>      3</b> s’étendre en avant, au loin : ἐν τῇ θαλάττῃ προκείμενον χωρίον, XÉN. <i>An. 6, 3, 3,</i> territoire qui s’avance dans la mer ; <i>d’où simpl</i>. s’étendre, s’allonger : παρὰ ἤπειρον νῆσος προκειμένη, XÉN. <i>Ath. 2, 13,</i> île qui s’étend le long du continent ;<br><b>      4</b> <i>fig</i>. être placé en avant, être préféré, SEXT. <i>P. 1, 4 ;</i><br><b>   II</b> être exposé aux regards, <i>d’où :</i><br><b>      1</b> être, se trouver : πρ. ἐν μέσῳ, LUC. <i>Nigr. 2,</i> être au milieu d’une chambre, <i>en parl. d’une table ; en mauv. part,</i> être jeté sur la voie publique, être abandonné : παιδίον προκείμενον, HDT. <i>1, 111,</i> petit enfant exposé, <i>càd</i>. abandonné ; ἄτιμος πρόκειμαι, SOPH. <i>Aj. 427,</i> me voici jeté là comme un objet de rebut ; κτίσον δὲ τῷ προκειμένῳ τάφον, SOPH. <i>Ant. 1088,</i> élève un tombeau pour ce corps abandonné ;<br><b>      2</b> être proposé (<i>propr</i>. placé devant les yeux) comme but, comme modèle, comme récompense, <i>etc. :</i> τοῖσι προὔκειτο τρίπος, HÉS. <i>Sc. 312,</i> un trépied était placé devant eux (comme prix de la lutte) ; ἄεθλος προκείμενος, HDT. <i>1, 126, etc</i>. tâche proposée ; τοῖς νικῶσιν ἆθλα πρόκειται, XÉN. <i>Cyr. 2, 3, 2, etc</i>. des prix sont proposés aux vainqueurs ; σκοπὸς προκείμενος, ARSTT. <i>Rhet. 1, 6, 1,</i> but proposé ; <i>p. ext</i>. πρόκειται ζητεῖν, LUC. <i>Par. 54,</i> on se propose de rechercher ;<br><b>      3</b> <i>p. suite,</i> être posé sous les yeux de tous, <i>d’où</i> être établi, fixé : πρόκεινται νόμοι, SOPH. <i>O.R. 865,</i> des lois sont établies ; νόμοι προκείμενοι, SOPH. <i>Ant. 481,</i> lois établies ; θανάτου ζημία πρόκειται, THC. <i>3, 45,</i> il y a peine de mort (lorsque, <i>etc</i>.) ; προκείμεναι ἡμέραι, HDT. <i>2, 87,</i> jours fixés ;<br><b>      4</b> <i>p. ext</i>. se présenter, se produire : γνῶμαι τρεῖς προεκέατο, HDT. <i>3, 83,</i> trois avis se produisaient ; δύο κινδύνων προκειμένων, HDN <i>7, 5, 16,</i> deux dangers se présentant ;<br><b>   III</b> (πρό, auparavant) être placé auparavant : γράμμα προκείμενον, ANTH. <i>11, 426,</i> lettre initiale ; ἐν τοῖς πρ. DYSC. <i>Synt. 138,</i> dans ce qui précède.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-κειμαι - πρόκειμαι</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n5 fois dans 5 versets de 3 livres bibliques (NT)\n<ul>\n<li>2 Corinthiens (1)</li>\n<li>Hébreux (3)</li>\n<li>Jude (1)</li>\n</ul>\n</td></tr>\n</table>","G4296":"<h1>prokerusso</h1>\n<p>Strong n° 4296 <i>Prononciation [prok-ay-rooce'-so]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>annoncer ou proclamer être un héraut des choses futures</li>\n<li>annoncer d'avance (du héraut lui-même)</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·κηρύσσω</b>, <i>att</i>. <b>-ύττω</b> <span>(<i>f</i>. ύξω, <i>ao</i>. προεκήρυξα, <i>par contr</i>. προὐκήρυξα)</span><br><b>      1</b> faire annoncer par un héraut, <i>en prose avec double rég. :</i> τί τινι, POL. <i>5, 60, 3,</i> qqe ch. à qqn ; <i>avec une prop. inf</i>. ARSTT. <i>Œc. 2, 23 ;</i><br><b>      2</b> publier <i>ou</i> annoncer, <i>en parl. d’un héraut, acc</i>. SOPH. <i>Ant. 461</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Ao</i>. προὐκήρυξα, SOPH. <i>Ant. 461</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-κηρυσσω - προκηρύσσω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n2 fois dans 2 versets de 1 livre biblique (NT)\n<ul>\n<li>Actes (2)</li>\n</ul>\n</td></tr>\n</table>","G4297":"<h1>prokope</h1>\n<p>Strong n° 4297 <i>Prononciation [prok-op-ay']</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td><ol><li>progrès, avancement</li></ol></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προκοπή, ῆς (ἡ) :<br>      1</b> marche en avant (<i>v</i>. προκόπτω) PLUT. <i>M. 76</i> d ;<br><b>      2</b> <i>fig</i>. progrès, avancement (en crédit, en puissance) POL. <i>1, 12, 7, etc. ; au plur</i>. PLUT. <i>M. 75</i> b ; LUC. <i>Alex. 22 ; en mauv. part,</i> POL. <i>5, 16, 9 ;</i> JOS. <i>A.J. 4, 4, 1</i>.\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προκοπη - προκοπή</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td></td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n3 fois dans 3 versets de 2 livres bibliques (NT)\n<ul>\n<li>Philippiens (2)</li>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>","G4298":"<h1>prokopto</h1>\n<p>Strong n° 4298 <i>Prononciation [prok-op'-to]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>battre vers l'avant\n<ol type=\"a\">\n<li>allonger par martelage (comme un forgeron façonne un métal)</li>\n<li>métaph. promouvoir, encourager, davantage</li>\n</ol>\n</li>\n<li>aller de l'avant, avancer, procéder\n<ol type=\"a\">\n<li>du temps : la nuit qui est bien avancée</li>\n<li>métaph. augmenter, progresser, faire des progrès</li>\n</ol>\n</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>προ·κόπτω</b> <span>(<i>impf</i>. προὔκοπτον, <i>f</i>. προκόψω, <i>ao</i>. προέκοψα, <i>pf</i>. προκέκοφα)</span><br><b>      1 <i>tr.</i></b> étirer <i>ou</i> allonger une plaque de métal à coups de marteau, <i>d’où</i> travailler, préparer, faire progresser, <i>gén</i>. THC. <i>4, 60 ; 7, 56 ; au pass</i>. s’avancer, progresser, s’accroître, HDT. <i>1, 190 ; 3, 56 ;</i><br><b>      2 <i>intr.</i></b> progresser, avancer : τὴν ὁδόν, JOS. <i>A.J. 2, 6, 7 ; ou abs</i>. JOS. <i>A.J. 2, 16, 3,</i> avancer dans sa marche ; τι, EUR. <i>Alc. 1079,</i> en qqe ch. ; οὐδὲν ἔς τι, XÉN. <i>Hell. 7, 1, 6, etc</i>. n’avancer en rien vers un but ; ἐπὶ τοσοῦτο, POL. <i>39, 9, 2,</i> jusqu’à ce point ; ἐπὶ πλεῖον, DS. <i>14, 98 ;</i> NT. <i>2Tim. 2, 16 ; avec un dat. :</i> τοῖς πλούτοις, DS. <i>Exc. 598, 61,</i> croître en fortune ; <i>avec une prép. :</i> ἐν παιδείᾳ, DS. <i>Exc. 554, 69 ;</i> avancer en instruction ; <i>en parl. du temps,</i> JOS. <i>B.J. 4, 4, 6 ; d’un discours,</i> SEXT. <i>P. 2, 240</i>.<br><span><b><span class=\"arrow\"></span></b> <i>Impf. contr</i>. προὔκοπτον, NT. <i>Rom. 13, 11</i>.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προ-κοπτω - προκόπτω</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Verbe</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n6 fois dans 6 versets de 4 livres bibliques (NT)\n<ul>\n<li>Luc (1)</li>\n<li>Romains (1)</li>\n<li>Galates (1)</li>\n<li>2 Timothée (3)</li>\n</ul>\n</td></tr>\n</table>","G4299":"<h1>prokrima</h1>\n<p>Strong n° 4299 <i>Prononciation [prok'-ree-mah]</i></p>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Strong</big></td></tr>\n<tr><td>\n<ol>\n<li>une opinion formée avant que les faits ne soient connus</li>\n<li>un pré-jugement, un préjugé, partialité</li>\n</ol>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Définition Bailly</big></td></tr>\n<tr><td colspan=\"2\">\n<b>πρόκριμα, ατος (τὸ)</b> <span>[ῐ]</span> jugement porté d’avance, prévention, NT. <i>1Tim. 5, 21 ;</i> RHÉT. <i>7, 1123 W</i>.<br><span><b>Étym</b>. προκρίνω.</span>\n</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Étymologie</big></td></tr>\n<tr><td><font face=\"Georgia\">προκριμα - πρόκριμα</font>\n<br><br>Voir définition </td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Nature du mot</big></td></tr>\n<tr><td>Nom neutre</td></tr>\n</table>\n<table class=\"border\">\n<tr><td class=\"strong\"><big>Occurrences</big></td></tr>\n<tr><td>\n1 fois dans 1 verset de 1 livre biblique (NT)\n<ul>\n<li>1 Timothée (1)</li>\n</ul>\n</td></tr>\n</table>"};
